export const CLASSIC_BATTLE_BRIEFINGS: Readonly<Record<string, ClassicBattleBriefing>> = {
    "aba_shapuer": {"strategic":["公元二六〇年春，萨珊波斯雄主沙普尔趁罗马帝国深陷东西边境危机，统波斯大军再度西进美索不达米亚，重兵围攻战略锁钥埃德萨。年迈的罗马皇帝瓦勒良为挽救东方半壁江山，亲调帝国各省精锐军团自安条克东驰解围，与沙普尔主力会战于埃德萨城外。"],"tactical":["埃德萨城西丘陵干旱炎热，罗马远征军久受瘟疫折磨，士卒虚弱饥渴。瓦勒良勉力列开方阵突围求进，沙普尔从容调轻弓骑四面游射断其水源，再挥萨珊具装铁骑将罗马军团铁桶般锁死在荒原。罗马军突围无望、粮水断绝，瓦勒良被迫亲赴波斯营帐乞和，当场被沙普尔扣留生擒，创罗马皇室前所未有的奇耻。"],"history":"公元二六〇年春，萨珊波斯君主沙普尔再度挥师西征两河上游，重兵围困罗马东方门户卡莱与埃德萨。年迈的罗马帝国皇帝瓦勒良亲统各省军团主力自安条克东进救援，军中瘟疫蔓延；两军决战于埃德萨城西，沙普尔以具装铁骑合围歼灭罗马大军，生擒罗马皇帝瓦勒良，震动古典世界。","sources":"沙普尔一世·卡巴耶·扎尔都什特铭文；佐西姆斯·新史"},
    "aba_shapuer@244": {"strategic":["公元二四四年冬，罗马帝国皇帝戈尔迪安三世收复上美索不达米亚后，乘胜统大军沿幼发拉底河南下，企图一举攻陷波斯都城泰西封。萨珊波斯新王沙普尔毫无退让，集结具装铁骑与各省劲旅，在泰西封西门屏障米西奇迎头阻截。"],"tactical":["米西奇地处幼发拉底河与运河交汇沃野，水渠纵横限制步兵机动。戈尔迪安三世催罗马军团强行推进；沙普尔亲自披甲督率人马俱装的萨珊重骑正面雷霆反冲，配合强弓骑兵两翼攒射。血战中罗马军阵被铁骑撕碎，戈尔迪安三世重伤殒命，继立新帝被迫割地纳赎求和，沙普尔遂将此大捷刻上摩崖纪功。"],"history":"公元二四三年罗马年轻皇帝戈尔迪安三世在岳父近卫军长官提美西修斯辅佐下东征波斯，于雷萨伊纳取胜收复尼西比斯，未几提美西修斯病亡，菲利普继掌禁卫。公元二四四年冬春戈尔迪安三世沿幼发拉底河南下进逼萨珊王都泰西封西障米西奇，萨珊王中之王沙普尔一世亲统铁骑迎战大破罗马军，戈尔迪安三世殒命，菲利普赔款割地求和。","sources":"沙普尔一世·卡巴耶·扎尔都什特铭文"},
    "aiji_lameisisi": {"strategic":["公元前一二七四年，埃及新王国与赫梯帝国并立近东，反复争夺叙利亚走廊。奥龙特斯河畔重镇卡迭石扼守南北要冲，藩属阿穆鲁易帜归埃。年轻的法老拉美西斯决意北上夺回卡迭石，编成阿蒙、拉、普塔赫、塞特各路军团亲统北出；赫梯王穆瓦塔利亦倾发联军南下迎敌，两强主力直趋卡迭石。"],"tactical":["卡迭石筑于奥龙特斯河西岸台地，河水环绕其侧。拉美西斯误信细作，率阿蒙军团孤军渡河扎营，与后队拉开间距。穆瓦塔利遣战车自城东渡河冲垮拉军团，旋即围攻王营；拉美西斯乘车苦战待援，幸得海岸支队与普塔赫军团赶到夹击解围。此战两军俱疲，拉美西斯无力攻城，遂引军南还。"],"history":"公元前一二七四年五月，埃及法老拉美西斯北征叙利亚，与赫梯王穆瓦塔利于奥龙特斯河畔卡迭石会战。拉美西斯轻信诈降牧人，率阿蒙军团孤军渡河扎营，遭赫梯战车奇袭被围；幸赖海岸支队与后续军团赶到解围，次日再战未分胜负，拉美西斯引军南还，卡迭石仍属赫梯。","sources":"卡迭石铭文；埃赫银板和约"},
    "aiji_neiketaneibu": {"strategic":["公元前三七三年，埃及摆脱波斯统治独立已久，法老内克塔内布锐意整饬三角洲防务。波斯王室决意夺回富庶的尼罗河流域，命老将法那巴佐斯集结水陆大军与希腊雇佣兵沿海路南侵，直扑东门佩鲁西姆；内克塔内布亲率守军扼守门户水道迎敌。"],"tactical":["佩鲁西姆地处尼罗河东支入海口，内克塔内布预先掘壕塞道、广筑壁垒，令法那巴佐斯正面寸步难进。波斯军乘夜绕自门德斯支流登陆，却因法那巴佐斯多疑迟疑、不肯急袭孟菲斯而顿兵水网。内克塔内布乘隙增防袭扰，未几盛夏尼罗河泛滥淹没低洼波斯营寨，埃军乘水势全线反攻，法那巴佐斯败逃，埃及再保独立。"],"history":"公元前三七三年春，波斯老将法那巴佐斯会合雅典雇佣军水陆进逼埃及东门佩鲁西姆，企图收复独立的埃及。埃及法老内克塔内布预先筑垒塞道迫波斯军改由门德斯河口登陆；趁敌帅争执迟疑之际，尼罗河夏汛泛滥淹没波斯营寨，内克塔内布挥军反击大破波斯军。","sources":"西西里的狄奥多罗斯·历史丛书·第十五卷"},
    "ailan_julushi": {"strategic":["公元前五三九年，波斯王居鲁士二世已并吞米底与吕底亚，西亚唯剩新巴比伦尚存。其时巴比伦王久居绿洲，留王子伯沙撒摄政，因冷落主神马尔杜克致朝野离心。居鲁士二世看准时机挥师渡河，于奥皮斯击破巴比伦野战军，旋即统大军南指伯沙撒留守的巴比伦城。"],"tactical":["巴比伦双垣高耸，幼发拉底河穿城而过，伯沙撒自恃城坚粮足，在城中欢庆节日疏于戒备。居鲁士二世避开强攻，命工兵在上游掘渠分流河水入泽，使穿城河道骤浅。入夜波斯精锐顺浅涸河床潜入未锁的沿河铜门，一举突入王宫，伯沙撒死于乱军；巴比伦全城归降，两河流域自此并入波斯帝国。"],"history":"公元前五三九年秋，波斯国王居鲁士二世进攻新巴比伦帝国，于奥皮斯击破巴比伦军后进逼巴比伦城。留守摄政王子伯沙撒恃坚城宴饮无备，波斯军在上游分流幼发拉底河水，趁夜沿浅涸河床潜入城内，伯沙撒败死，新巴比伦灭亡。异说：那波尼德编年史载波斯军未历大战即入城，分流河水奇袭见于希罗多德等记载。","sources":"那波尼德编年史；居鲁士圆柱；希罗多德·历史"},
    "ailan_julushi@-547": {"strategic":["公元前五四七年，波斯王居鲁士二世推翻米底后，吕底亚国王克罗伊索斯结盟东侵波斯。两军秋战难分高下，时值隆冬，克罗伊索斯断定波斯不敢冒雪深入，遂退回撒狄遣散盟军待春再战。岂料居鲁士二世看破其懈怠，率军踏雪西进直抵提姆布拉平原，逼克罗伊索斯仓促应战。"],"tactical":["提姆布拉平原辽阔平坦，克罗伊索斯尽起吕底亚长矛重骑与步兵方阵，张开两翼企图合围波斯军。居鲁士二世收拢步弓塔车结成严阵，更卸下随军骆驼辎重列于前线。吕底亚铁骑呼啸冲来，战马畏惧骆驼气味纷纷惊窜调头，阵形大乱；居鲁士二世趁势反扑击溃敌军，旋即攻克撒狄，将吕底亚并入波斯。"],"history":"公元前五四七年冬，吕底亚国王克罗伊索斯在普特里亚与居鲁士二世战平后，以为隆冬波斯必不进兵，遂回都撒狄遣散盟军待春再战。居鲁士二世冒冬疾追至撒狄城东提姆布拉平原，以辎重骆驼列前阵惊散吕底亚骑兵，合围大破克罗伊索斯主力，继克撒狄灭吕底亚。异说：年份一作前五四六年。定值：敌将取克罗伊索斯。","sources":"希罗多德·历史·第一卷；色诺芬·居鲁士的教育"},
    "ailan_julushi@-550": {"strategic":["公元前五五〇年，统治伊朗高原的米底帝国因国王阿斯提阿格斯严苛专断而贵族离心。南方附庸波斯诸部之长居鲁士二世暗结米底重臣，团结波斯各族起兵抗命。阿斯提阿格斯震怒，倾发主力御驾南征；居鲁士二世将妇孺撤入深山，率军依托帕萨尔加德隘口迎敌。"],"tactical":["帕萨尔加德群山环抱、谷口险峻，居鲁士二世凭山坡设防。阿斯提阿格斯分兵迂回两翼高山夹击，首日迫波斯军退至山巅；波斯妇孺出帐激愤将士，全军死志顿起。次日居鲁士二世率军自山顶怒吼俯冲，迎头猛撞仰攻敌阵，兼之米底怀怨贵族临阵倒戈，米底军土崩瓦解；阿斯提阿格斯被擒，波斯帝国由此崛起。"],"history":"公元前五五〇年，波斯国王居鲁士二世起兵反抗宗主米底帝国，退守波斯腹地帕萨尔加德群山。米底王阿斯提阿格斯亲率大军围攻，首日迫波斯军退保山顶；次日波斯军在妇孺激励下俯冲反扑，兼之米底贵族临阵倒戈，居鲁士二世大破米底军并生擒阿斯提阿格斯，建立波斯帝国。定值：敌将取米底王阿斯提阿格斯。","sources":"那波尼德编年史；希罗多德·历史·第一卷"},
    "ailan_shuteluke": {"strategic":["公元前一一五八年，巴比伦加喜特王朝内外交困，东方埃兰王国则在纳克昆特治下兵甲强盛。纳克昆特借累代联姻索讨巴比伦王位遭拒，遂自苏萨举兵西征；埃兰军强渡底格里斯河连克西帕尔诸城，直抵恩利尔纳丁退守的巴比伦内城之下，加喜特社稷悬于一线。"],"tactical":["巴比伦城跨幼发拉底河而筑，重垣深壕拱卫宫庙，恩利尔纳丁收拢守军闭门死守。纳克昆特先扫清外围卫城、断绝水陆粮援，再督步骑与攻城器械四面合围猛攻。孤城粮尽防溃，埃兰军破城俘获恩利尔纳丁，将汉谟拉比法典石碑与主神像拆运回苏萨，加喜特王朝自此覆灭。"],"history":"公元前一一五八年，埃兰国王纳克昆特乘巴比伦加喜特王朝衰弱大举西征，攻破巴比伦诸城，掳走汉谟拉比法典碑与纳拉姆辛胜利碑运回苏萨；加喜特末王恩利尔纳丁继续抵抗，终兵败被俘，马尔杜克神像被掳，加喜特王朝覆灭。定值：守方定为加喜特王朝，以末王恩利尔纳丁为守将代表。","sources":"苏萨埃兰王铭；巴比伦同步史"},
    "ansxi_aershake": {"strategic":["公元前二三八年，塞琉古帝国深陷叙利亚战事与王室内战，东方控制崩解；帕提亚总督安德拉戈拉斯乘乱自立，却外失中枢后援、内乏贵族拥戴。里海东南草原的帕尼部族首领阿尔沙克窥见良机，统剽悍铁骑越山南下，直扑安德拉戈拉斯驻守的重镇尼萨。"],"tactical":["尼萨地处山麓绿洲走廊，北接荒漠，极利骑兵驰突。安德拉戈拉斯孤立无援，率驻防步卒出城迎战。阿尔沙克发挥草原游骑返身骑射之长，先断外围联络；接战后以密集箭雨反复消磨敌阵，待其阵脚疲乱再挥披甲重骑雷霆冲杀。安德拉戈拉斯兵败被杀，阿尔沙克攻占尼萨称王，开创安息帝国基业。"],"history":"公元前二三八年前后，塞琉古帝国深陷外战与内乱无暇东顾，帕提亚总督安德拉戈拉斯脱离帝国自立。里海东南草原帕尼部族首领阿尔沙克抓住良机，率游牧骑射劲旅南下攻入帕提亚，在尼萨击败并斩杀孤立无援的安德拉戈拉斯，创建安息帝国。定值：年份统一取前二三八年。","sources":"斯特拉波·地理志·第十一卷；查士丁·腓力史概要·第四十一卷"},
    "aqimeinide_daliushi": {"strategic":["公元前五二一年，波斯宫廷剧变未久，大流士一世诛除夺位者登基，帝国各省趁乱纷叛。巴比伦贵族尼丁图-贝尔冒称故王之子自立为王，两河诸城景从。大流士一世深知巴比伦乃帝国赋税命脉，不容坐视复国，遂亲统波斯与米底劲旅火速西征，直扑尼丁图-贝尔据守的巴比伦。"],"tactical":["巴比伦外有两河环护，内有重垣可恃。尼丁图-贝尔遣舟师封锁底格里斯河渡口；大流士一世命士卒乘皮筏战马强渡破防，复败敌主力于幼发拉底河畔，迫其退入城中死守。大流士一世乘胜合围巴比伦，分道猛攻突破城防，生擒处死尼丁图-贝尔，稳住两河大局并进而荡平各省叛乱。"],"history":"波斯王冈比西斯二世死后帝国大乱，大流士一世夺位之际各省纷叛，巴比伦贵族尼丁图-贝尔冒称前王之子自立为巴比伦王。大流士一世亲统大军强渡底格里斯河，再败敌于幼发拉底河畔，合围攻破巴比伦城并擒杀尼丁图-贝尔。异说与定值：贝希斯敦铭文载其败亡于前五二二年末，定稿表取前五二一年破城。","sources":"贝希斯敦铭文；希罗多德·历史·第三卷"},
    "baiyang_mengtian": {"strategic":["公元前二一五年，秦始皇一统六国后北巡边塞；匈奴单于头曼乘中原混战南占河套水草，威胁关中北门，秦廷遂命大将蒙恬统重兵北征。蒙恬一举扫清河南地游牧部众，旋即挥师西北强渡黄河，直指头曼据守的阴山咽喉高阙塞。"],"tactical":["高阙塞双峰壁立如阙，控扼阴山南北往来孔道，头曼聚草原控弦主力凭山口迎抗。蒙恬督久历灭国大战的秦国锐师据险推进，以严整车步强弩阵正面压住匈奴骑群冲击，再遣精骑分断侧翼退路。匈奴游骑难破秦军坚阵，死伤惨重，头曼被迫弃阴山远遁漠北；蒙恬因山河险塞修筑延袤长城，镇边十余载令匈奴不敢南下牧马。"],"history":"公元前二一五年，秦始皇统一六国后巡边得亡秦者胡之谶，命大将蒙恬统重兵北击匈奴。蒙恬先扫清河套河南地诸部，继而西北渡黄河直扑阴山咽喉高阙塞，正面击破匈奴单于头曼主力，迫头曼远遁漠北，因地形修筑延袤长城，驻守上郡十余年威震匈奴。定值：年份取前二一五年。","sources":"史记·蒙恬列传；史记·匈奴列传；史记·秦始皇本纪"},
    "beidi_yaochang@389": {"strategic":["公元三八九年夏，入据长安开创后秦的姚苌遭前秦残余势力南安王苻登苦苦纠缠；苻登军中供奉故主神位，将士头盔皆刻死休二字，抱必死之心屡挫后秦锋芒。苻登将全军家眷与粮草军资屯于大界大营，亲统主力逼攻安定；姚苌洞悉虚实，决计奇袭敌巢。"],"tactical":["大界坐落陇东新平与安定群山之间，乃苻登全军命脉所系。姚苌留下重臣死守安定孤城吸住苻登主力，亲自简选精锐铁骑趁夜避开大道，循山间僻路神速绕插大界后方；拂晓后秦铁骑突破营门，留守秦兵溃不成军，苻登家眷与如山军资尽落姚苌之手，前秦残军自此根基崩塌一蹶不振。"],"history":"公元三八六年姚苌入据长安称帝建后秦，前秦宗室南安王苻登于陇东继帝位，军中载苻坚神主、将士胄刻死休之字苦战屡挫姚苌。建初四年即公元三八九年夏秋，苻登安置军资妻室于新平与安定间之大界营，自率主力进逼安定。八月姚苌留尚书令姚旻守安定，亲率精骑乘夜出奇道偷袭攻陷大界，杀毛皇后尽收其辎重，扭转战局。","sources":"晋书·姚苌载记"},
    "bendou_d_mitelidati": {"strategic":["公元前六七年，被罗马军团逐出故土的本都国王密特里达梯看准罗马远征主力在亚美尼亚哗变厌战，毅然率精干旧部潜回本都掀起反攻。留守本都的罗马副将特里阿里乌斯贪图独揽破王大功，不等主帅回援便率军赶赴泽拉寻战，密特里达梯遂整军迎击。"],"tactical":["泽拉城外丘陵起伏，暴雨后河沟满溢泥泞。特里阿里乌斯急于求成，驱罗马军团主动进攻；密特里达梯身先士卒冲锋，虽中刺负伤，包扎止血后仍重返前线督军猛扑。本都步骑将笨重的罗马步兵逼入泥泞沟泽分割砍杀，一举冲破敌阵并夺占大营；特里阿里乌斯仅以身免，密特里达梯乘胜尽复本都故土。"],"history":"公元前六七年春，曾被罗马主帅卢库卢斯逐往亚美尼亚的本都国王密特里达梯趁罗马军团厌战哗变之机，潜回本都招集旧部反攻。留守的罗马副将特里阿里乌斯急于在主帅赶到前独揽战功，在泽拉城外主动出战；密特里达梯负伤督战，借泥泞沟泽冲垮罗马军团夺占大营，光复本都全境。","sources":"阿庇安·密特里达梯战争史；普鲁塔克·卢库卢斯传"},
    "bendou_d_mitelidati@-66": {"strategic":["公元前六六年，罗马共和国改派名将庞培总揽东方兵权，结好安息断绝本都外援，统优势军团大举东侵。年近古稀的本都王密特里达梯坚壁清野，边战边向亚美尼亚边境撤退；突围东行途中密特里达梯率军夜宿尼科波利斯狭谷，不料庞培已绕道抢占四周山岭。"],"tactical":["尼科波利斯谷地狭窄幽深，四面陡崖环锁，本都军入谷安营未察山头已失。半夜残月西沉，庞培督罗马军团背月自西坡俯冲夜袭；斜射月光将罗马兵黑影拉长投向谷底，本都射手误朝黑影射空箭矢，转瞬遭罗马重步兵贴身砍杀。全军暗夜大溃之际，密特里达梯临危不惧，亲率随骑硬生生劈开罗马军阵突围北奔黑海。"],"history":"公元前六六年，面对拥有绝对兵力优势并结盟安息孤立本都的罗马新统帅庞培，年近七旬的密特里达梯六世采取坚壁清野边战边退策略东撤亚美尼亚边境。突破庞培筑墙包围后，密特里达梯夜宿利库斯河畔尼科波利斯山谷；庞培抢占四面山脊乘残月背光发动夜袭，本都军因月影误判射空箭矢而大溃，密特里达梯偕勇妾海普西克拉提亚劈开罗马重步兵突围北走。","sources":"阿庇安·密特里达梯战争史；普鲁塔克·庞培传"},
    "bendou_d_mitelidati@-74": {"strategic":["公元前七四年，比提尼亚老王遗命将国土赠予罗马共和国；本都国王密特里达梯决不容罗马封锁海峡咽喉，当即兴水陆大军闪电西征。比提尼亚望风归附，罗马执政官科塔仓皇退保博斯普鲁斯海峡重镇卡尔西顿，密特里达梯遂挥师海陆合围。"],"tactical":["卡尔西顿扼守海峡南口，城坚港深，科塔以粗重铜链封锁海港，并率罗马步兵出城背墙迎战。密特里达梯调彪悍雇佣步卒正面冲垮科塔军团，将其杀得尸横城外、争门溃逃；随即命本都战舰与陆军协同猛攻港口，硬生生撞断封港铜链杀入内港，将罗马舰队尽数焚毁俘获，密特里达梯一战尽夺海峡制海权。"],"history":"公元前七四年，比提尼亚老王死后遗诏将王国赠予罗马，本都国王密特里达梯六世拒不承认，联络西班牙反罗名将塞多留发动第三次密特里达梯战争，率水陆大军闪电席卷比提尼亚，逼罗马执政官科塔退保博斯普鲁斯海峡要塞卡尔西顿。科塔出城野战遭密特里达梯巴斯塔奈雇佣兵击溃，本都水陆夹攻撞断港口封港铜链，尽数焚夺罗马战舰，打响开战首捷。","sources":"阿庇安·密特里达梯战争史；普鲁塔克·卢库卢斯传"},
    "bfe2_esarhaddon": {"strategic":["公元前六七一年，距首次征埃受挫已过两载，推罗王再度倚仗法老塔哈尔卡撑腰背叛亚述。亚述王以撒哈顿痛定思痛，预先征调阿拉伯驼队运水，分兵钳制推罗，亲统大军稳步越过西奈荒漠。亚述军入埃及东境后连破拦截兵马，沿三角洲边缘推进，直抵下埃及都城孟菲斯。"],"tactical":["孟菲斯扼守尼罗河三角洲顶点，白墙高耸、水陆辐辏，塔哈尔卡亲督守军背城迎战。以撒哈顿先于城外野战击溃埃军并射伤塔哈尔卡，随即水陆合围孟菲斯；亚述军在箭雨掩护下架冲车云梯猛攻，半日便突破外郭杀入内城。塔哈尔卡弃城南逃底比斯，以撒哈顿俘其王室家眷，将下埃及纳入亚述版图。"],"history":"公元前六七一年夏，亚述王以撒哈顿吸取前败教训，征调阿拉伯驼队供水穿越西奈，连破埃及边防直抵下埃及都城孟菲斯。法老塔哈尔卡力战负伤南逃底比斯，以撒哈顿攻克孟菲斯，俘获王后太子，册封三角洲诸侯，将下埃及纳入亚述版图。","sources":"以撒哈顿辛吉尔利胜利碑；巴比伦编年史"},
    "bfe2_esarhaddon@-673": {"strategic":["公元前六七三年，亚述王以撒哈顿虽已震慑叙利亚诸邦，埃及法老塔哈尔卡却屡向腓尼基输送财货援兵，煽动沿海诸城反叛。以撒哈顿踏平西顿后决意直捣祸根，集结远征军自迦南南境强穿西奈荒漠，企图抢先夺下埃及东境门户佩鲁西姆，打开尼罗河三角洲。"],"tactical":["佩鲁西姆横亘西奈沙碛尽头与尼罗河东支水网之间，遍布盐泽流沙。以撒哈顿督军缺水急行，抵阵时已人困马乏、队列拉长。塔哈尔卡早已凭河渠壁垒严阵以待，趁亚述战车步卒陷于沙泽泥泞之际全线猛攻。亚述军久行力竭伤亡惨重，以撒哈顿果断收拢残师北撤返国，留待日后再图埃及。"],"history":"公元前六七三年初春，亚述王以撒哈顿为铲除黎凡特叛乱的幕后支柱埃及，率军强行穿越西奈荒漠，进攻埃及东境门户佩鲁西姆。因行军过急、缺水疲敝，亚述军遭埃及法老塔哈尔卡迎头痛击而大败，以撒哈顿撤军返国。异说：巴比伦编年史或折算为前六七四年，定稿表取前六七三年。","sources":"巴比伦编年史；亚述年代记"},
    "bfe2_pang_juan": {"strategic":["公元前三四二年，魏国国力复振，大将庞涓辅太子申倾国攻韩，欲重夺中原霸权。韩国危急求救于齐，齐国复遣主帅田忌越境直扑魏都大梁；正督军攻韩的庞涓惊闻后方告急，新仇旧恨交织，当即撤韩围东向，追击田忌主力直奔马陵道。"],"tactical":["马陵道夹于崇山幽谷之间，林密路窄，极易设伏。庞涓入边境见田忌东退，查齐营遗灶逐日锐减，喜认齐卒怯懦逃亡，遂撇下步卒辎重，亲率精锐轻骑昼夜急追，日暮扎入马陵道。夜色中庞涓见道旁刮皮大树写有墨字，命点火辨认；火亮处两侧山崖强弩齐发，狭道魏军死伤枕藉，庞涓拔剑自刎，魏霸就此终结。"],"history":"公元前三四二年，魏大将庞涓与太子申率军伐韩，齐威王以田忌为将、孙膑为师直趋大梁救韩，迫庞涓撤围回救。齐军逐日减灶示弱，庞涓弃步卒率轻骑兼程追入马陵道，夜间举火读树中伏，齐弩齐发，魏军大溃，庞涓自刎。定值：同场三行统一取前三四二年、战场马陵道。","sources":"史记·孙子吴起列传；史记·魏世家；战国策"},
    "bfe2_pang_juan@-353": {"strategic":["公元前三五三年，魏国大将庞涓统精锐魏武卒猛攻赵都邯郸逾年，刚拔外城之际，后方魏都大梁忽传火急警报。原来齐国应赵求援，命大将田忌趁魏国内空虚挥师西进，扬言直捣大梁；庞涓不敢坐视根本有失，只得率久战主力掉头南下，疾趋桂陵迎堵田忌。"],"tactical":["桂陵地处黄河南岸通往大梁的孔道，丘陵沟渠交错。庞涓自恃魏武卒悍勇，急于解大梁之危，催督疲师丢弃粮车昼夜狂奔，致队列拉长脱节。岂料田忌早已抢占桂陵险要筑垒设伏、蓄锐待敌；庞涓前锋撞入伏击圈，遭齐军四面合击拦腰截断，全军溃散，庞涓亦在混战中被俘，魏国霸气大挫。"],"history":"公元前三五四年魏将庞涓围攻赵都邯郸，次年即前三五三年攻克邯郸之际，齐将田忌与军师孙膑率师直扑魏都大梁。庞涓闻警，率久战疲师弃辎重星夜回救，在桂陵中齐军以逸待劳之伏而大败被俘，后获释归魏。定值：同场三行年份统一取前三五三年。","sources":"史记·孙子吴起列传；史记·魏世家；战国策"},
    "bfe3_13": {"strategic":["公元前二二五年，三晋俱亡，秦廷拒老将稳进之议，遣少壮猛将李信分兵南下大举侵楚。李信初入淮颍势如破竹，连拔平舆与鄢郢；临危受命的楚国大将军项燕避开敌军初来锐气，暗集楚地主力悄然机动，紧紧尾随骄狂东返的李信大军逼向淮北城父。"],"tactical":["城父地处颍涡平原，乃秦军约定会师之地。李信自恃连捷轻视楚人，督军急行赶赴城父，战线绵长、疏于筑垒。项燕看准破绽，率蓄锐楚师紧咬秦军尾后，全军三日三夜甲不离身疾追；待李信抵城父外围立足未稳，项燕擂鼓四面突袭，踏破秦军连营、阵斩诸位都尉，李信狼狈败逃，创秦并六国以来罕见惨败。"],"history":"公元前二二五年，秦已灭三晋，遣少壮将领李信与蒙恬分路南下伐楚。李信连克平舆、鄢郢后引军东向拟会师城父；楚大将军项燕洞悉秦军远入骄轻之弊，率主力收敛锋芒尾随紧追三日三夜不息，趁李信军疲垒虚于城父突袭猛攻，连破秦军大营、阵斩诸都尉，重创李信。","sources":"史记·白起王翦列传；史记·楚世家"},
    "bfe3_13@-224": {"strategic":["公元前二二四年，城父胜后未久，秦王倾尽举国机动重兵托付老帅王翦卷土南侵；楚王亦悉数动员江淮男丁，复命大将军项燕赴淮北迎击。面对深沟高垒闭营不出的王翦，项燕屡次搦战无果，双方举国大军在淮北旷野硬生生对峙经年，终移师向蕲县蕲南。"],"tactical":["蕲县蕲南地处睢涡平原，道路四通。项燕统各路楚师在野地久耗逾年，见王翦营中安静、士卒投石嬉戏而绝不出战，误判秦军师老意怠，兼之粮饷难继，遂下令拔营东移。不料蓄锐已久的王翦趁楚军行列拉长、未及回身结阵，挥秦国虎贲从背后掩杀；楚师于蕲南崩溃，项燕力战不支自刎，荆楚主力自此覆灭。"],"history":"公元前二二四年，秦王亲请老帅王翦统倾国大军再伐楚，楚大将军项燕尽发全境兵马于淮北相拒。王翦筑垒坚守逾年不出，优养士卒蓄锐；项燕久耗粮匮引军东移，王翦乘楚军拔营移动之际全军追击，于蕲县蕲南大破楚军，项燕自刎殉国，楚主力覆亡。","sources":"史记·白起王翦列传；史记·楚世家"},
    "bfe3_38": {"strategic":["公元前九九年，汉廷再发大军西击天山，另遣骑都尉李陵独率荆楚善射步卒自居延北出塞外策应。新立未久的匈奴且鞮侯单于侦知这支深入草原的汉军全是步卒而无骑兵护翼，当即亲统王庭精骑南下，赶赴浚稽山张网合围。"],"tactical":["浚稽山双峰夹峙，南通返塞山谷狭道。且鞮侯单于初驱精骑猛冲汉营，却被李陵以大车长戟配强弩齐射杀伤甚众。探明汉军孤立无援后，且鞮侯单于重振军心，广调各部骑射沿南撤山谷节节截杀，纵火烧荒、居高投石，昼夜紧逼八日之久；终将汉军箭矢彻底耗尽，于距塞咫尺处迫降李陵，重振草原声威。"],"history":"公元前九九年秋，汉贰师将军出击天山，骑都尉李陵独率荆楚步卒自居延北进至浚稽山侦察。匈奴且鞮侯单于侦知李陵孤军无骑，亲率主力将其合围于浚稽山谷；面对汉军战车强弩重创，且鞮侯单于广调各部弓骑沿山谷南追截击八昼夜，耗尽汉军箭矢，于塞北迫降李陵。","sources":"史记·李将军列传；汉书·李广苏建传；汉书·匈奴传"},
    "bfe3_38@-97": {"strategic":["公元前九七年春，汉武帝为雪浚稽山折将之耻，倾发各路步骑大举出塞，命贰师将军李广利统主力自朔方北进。匈奴且鞮侯单于闻讯镇定自若，命各部将妇孺畜产悉数北迁至余吾水以北安全腹地，亲统精锐控弦铁骑列阵于余吾水南岸以逸待劳。"],"tactical":["余吾水横卧漠北寒原，早春冰雪初融，汉军远涉沙碛已是师老力疲。李广利督汉军进抵河岸求战，且鞮侯单于凭河岸地利指挥匈奴精骑轮番冲击、避实击虚，一连鏖战十余昼夜令汉军寸步难进。适逢汉廷后方突起大狱，李广利闻家眷获罪军心剧摇，被迫引兵南撤；且鞮侯单于挥骑衔尾追击，令汉廷四路远征无功而返。"],"history":"公元前九七年春，汉武帝为雪浚稽山之耻，大发步骑四道击匈奴：贰师将军李广利出朔方，韩说、公孙敖、路博德分道并进。匈奴且鞮侯单于闻报沉着应变，将全部妇孺辎重远迁至漠北余吾水以北安全地带，亲统精锐主力铁骑驻待于余吾水南岸。李广利北进与且鞮侯单于连战十余日不能破，闻全族因巫蛊罪被诛无心恋战引还，四路汉军皆无功而返。","sources":"汉书·匈奴传；汉书·武帝纪；资治通鉴·汉纪十四"},
    "bfe3_46": {"strategic":["公元前五二年，高卢阿维尔尼贵族维钦托利联络全高卢诸部掀起反抗罗马统治的大起义，行坚壁清野屡挫罗马锋芒。秋日骑战失利后，维钦托利收拢主力退入山顶要塞阿莱西亚，急遣轻骑趁夜突围遍召各族援兵，准备与追围城下的罗马统帅恺撒决一死战。"],"tactical":["阿莱西亚高踞陡山，两水夹流其下，恺撒督罗马军团环山筑起内外双重壁垒断绝粮水。维钦托利苦撑盼来高卢各部援军，即率守军自城内猛冲内壁，与城外援军前后夹击西北山坡缺口。血战竟日外援遭罗马骑兵抄后溃散；维钦托利见复国绝望，披华甲单骑赴恺撒帐前献降，以一身保全城中部众性命。"],"history":"公元前五二年，高卢阿维尔尼贵族维钦托利团结全高卢诸部起义抗击罗马，秋日骑战受挫后率主力退守山顶坚城阿莱西亚，遣骑突围召集全高卢援军。罗马统帅恺撒筑内外双重环城壁垒围困，维钦托利与城外援军内外夹攻失败，为保全部众性命披华甲单骑出城献降。","sources":"恺撒·高卢战记·第七卷；普鲁塔克·恺撒传"},
    "bfe3_79": {"strategic":["公元二七二年夏，罗马帝国皇帝奥勒良连破帕尔米拉野战大军；女王芝诺比娅率残部穿过沙海退回沙漠王都塔德莫尔，企图凭瀚海天险与波斯外援拖垮远征军。奥勒良毫不退缩，重金招抚沙漠游牧部族保障驼运水源，亲统军团横穿酷热荒漠，兵临塔德莫尔城下。"],"tactical":["塔德莫尔孤悬叙利亚沙漠绿洲，高大石墙上架满强弩发石机，芝诺比娅傲然拒降，奥勒良督战亦被冷箭射伤。奥勒良改用深沟长围锁死绿洲通道，并派骑兵截溃波斯派来的微弱援军；城内粮尽绝望，芝诺比娅乘快驼趁夜南逃赴波斯求救，在幼发拉底河渡口被奥勒良追骑生擒，孤城献降，罗马收复东方。"],"history":"公元二七二年夏末，罗马皇帝奥勒良在埃梅萨击溃帕尔米拉主力后，冒酷暑与游牧骑兵袭扰强穿叙利亚沙漠，进围绿洲王都塔德莫尔即帕尔米拉城。女王芝诺比娅凭坚城劲弩拒守待波斯外援，奥勒良筑围断粮并击败萨珊援骑，于幼发拉底河岸生擒乘驼夜逃的芝诺比娅，收复东方。定值：战场定为塔德莫尔。","sources":"佐西姆斯·新史；罗马皇帝传·神圣奥勒良传"},
    "bfe3_79@272": {"strategic":["公元二七二年夏，罗马帝国皇帝奥勒良亲统大军东征分裂独立的东方强藩帕尔米拉，在安条克城外首战告捷后挥师南下叙利亚腹地。帕尔米拉女王芝诺比娅与统帅收拢全境主力，退驻重镇埃梅萨城外原野重整旗鼓，与奥勒良展开决定东方霸权的决战。"],"tactical":["埃梅萨平原炽热宽广，芝诺比娅依仗披挂重甲的帕尔米拉具装铁骑迎敌。奥勒良先令罗马轻骑佯退，诱使重甲敌骑在烈日下长途狂追至精疲力竭；待敌骑阵散力衰，奥勒良骤然投入持沉重木棒的巴勒斯坦步兵专砸铁甲骑士，军团两翼合围猛杀。芝诺比娅主力全线崩溃，被迫仓皇逃回沙漠王都。"],"history":"公元二七二年夏六月，罗马皇帝奥勒良在安条克近郊伊迈击败帕尔米拉军后，挥师南下叙利亚重镇埃梅萨。女王芝诺比娅偕大将扎布达斯集结帕尔米拉主力于埃梅萨平原决战。帕尔米拉具装重骑一度冲散罗马骑兵，奥勒良调集巴勒斯坦棍棒辅助兵专击铁骑并率军团合围，大破芝诺比娅，迫其退守沙漠王都。","sources":"佐西姆斯·新史"},
    "bfe3_79@274": {"strategic":["公元二七四年春，荡平东方帕尔米拉的罗马皇帝奥勒良马不停蹄挥师西向，翻越阿尔卑斯山讨伐已割据高卢与不列颠十余载的高卢帝国。高卢末帝泰特里库斯一世内受骄兵哗变裹挟，被迫统莱茵军团南下迎截，两军主力在香槟卡塔隆平原摆开决战大阵。"],"tactical":["卡塔隆平原辽阔无垠，马恩河水蜿蜒流经战场。泰特里库斯一世厌倦乱兵挟持，战前已暗通款曲，开战不久便策马投奔奥勒良军营。然而高卢莱茵老兵仍凭悍勇死战不退；奥勒良沉着指挥罗马军团与东方骑兵分翼包抄围歼，终将无主敌军彻底击溃，分裂多年的罗马帝国至此重归完整一统。"],"history":"公元二七四年春，已平定东方的罗马皇帝奥勒良挥师越阿尔卑斯山西征割据十四载的高卢帝国。高卢帝国末帝泰特里库斯一世内受兵变困扰、外惧日耳曼寇掠，统莱茵军团自都城特里尔南下迎战于香槟卡塔隆平原。会战中泰特里库斯一世过阵投向奥勒良，群龙无首的高卢军团遭奥勒良主力合围歼灭，罗马帝国重归完整一统。","sources":"欧特罗庇乌斯·罗马史纲"},
    "bfe3_9": {"strategic":["公元前二六〇年，秦军截断韩国上党，上党郡守举郡献赵，赵王贪地受纳。秦王震怒，命宿将王龁统秦军主力夺取上党并紧追北上；赵廷急遣老将廉颇率重兵进驻长平设防接应，王龁挥锐师跨入太行腹地直逼廉颇防线，拉开长平决战序幕。"],"tactical":["长平群山环峙、丹水南流，廉颇沿丹水西岸分筑前哨壁垒阻截。王龁率秦军迎头猛攻，连拔西岸要塞并阵斩赵军都尉与裨将，打得赵军野战连挫；廉颇遂收兵退守丹水东岸筑起长垒，任王龁百般搦战始终闭营不出。僵持日久后秦施反间诱赵王易将，王龁改任副帅配合主帅诱敌入伏、截断粮道，终助秦国铸就长平全胜。"],"history":"公元前二六二年上党献赵引发秦赵决战。公元前二六〇年前期，秦左庶长王龁率军夺上党后进逼长平，连续攻破赵老将廉颇前哨壁垒、斩赵裨将与都尉，迫廉颇退守丹水东岸筑长垒坚壁不出；后秦施反间计诱赵括代将，秦密派白起为上将军、王龁改任副帅，协同合围全歼赵军。","sources":"史记·白起王翦列传；史记·秦本纪"},
    "bfe3_9@-257": {"strategic":["公元前二五七年，秦王欲乘长平余威吞灭赵国，在前锋攻城受挫后，改命宿将王龁增兵合围赵都邯郸，并恫吓诸侯不得来救。王龁连月猛攻将邯郸困成绝粮孤城；不料原本驻邺观望的魏军生变，信陵君魏无忌夺掌精兵会合楚师疾驰北援，王龁遂于邯郸城下分兵迎敌。"],"tactical":["邯郸城垣坚厚，城外秦营环列，然秦师久暴于外、攻坚死伤甚重，早已师老兵疲。面对魏无忌率精选魏卒自西面发起的悍勇突击，王龁急调主力迎堵；怎奈楚国援军自侧翼压上，邯郸城门亦骤开杀出敢死赵卒。内外夹击下秦军连营被破，王龁见势不可为，果断收拢本部残军西撤渡河退保汾城，灭赵之图暂告受挫。"],"history":"公元前二五八年秦将王陵攻赵都邯郸失利，秦王改命长平宿将王龁接掌主力继续猛攻邯郸。王龁围城经年致邯郸绝粮垂危；公元前二五七年冬，魏信陵君魏无忌窃符夺军北上，会合楚援军猛袭秦营，城内赵军开门夹击，久师疲敝的王龁兵败撤围，退保汾城。","sources":"史记·白起王翦列传；史记·魏公子列传"},
    "bfe_antigonus": {"strategic":["公元前三〇一年，年届八旬的安提柯一世坐拥小亚细亚与叙利亚霸权，意图重统亚历山大旧疆，促成诸王结盟共讨。东方霸主塞琉古携大批印度战象翻山与盟友会师；安提柯一世急召爱子渡海归援，父子合兵进抵伊普苏斯平原，迎战塞琉古联军。"],"tactical":["伊普苏斯平原坦阔，安提柯一世亲领重装方阵居中，命爱子统重骑居右翼主攻。开战后右翼重骑一鼓冲垮联军左翼，却贪功远追脱离战场；塞琉古乘隙驱印度象群横插而入，筑起活墙截断其归路，再令弓骑环绕裸露的中军方阵攒射。安提柯一世至死苦盼爱子回救不至，身中标枪倒毙阵中，一统旧梦就此落幕。"],"history":"公元前三〇一年，年逾八旬的安提柯一世携子德米特里在弗里吉亚伊普苏斯平原迎战塞琉古、利西马科斯等反安提柯一世联军。德米特里率重骑击溃联军左翼骑兵但追击过远，被塞琉古以印度战象排墙截断归路；联军弓骑环射中军方阵，安提柯一世中乱枪阵亡，帝国被瓜分。","sources":"普鲁塔克·德米特里传；西西里的狄奥多罗斯·历史丛书·第二十卷"},
    "bfe_antigonus@-316": {"strategic":["公元前三一六年隆冬，欧墨涅斯率联军入加比埃奈绿洲分散过冬。安提柯一世探知敌营相隔遥远，冒严寒强穿荒漠企图奇袭；欧墨涅斯在山顶遍燃空营篝火阻滞敌锋，及时聚齐各部与战象，两大宿敌遂在加比埃奈盐碱荒原迎来生死决战。"],"tactical":["加比埃奈遍铺干燥盐沙，铁骑战象奔突间白尘遮天。中路欧墨涅斯的银盾老兵再度杀穿敌步阵，右翼安提柯一世则率重骑击退敌左翼；混战中安提柯一世借浓尘掩护，密遣轻骑绕后一举夺下守备空虚的敌军大营。战罢银盾兵惊闻毕生积蓄与妻儿被掳，竟哗变捆献欧墨涅斯乞降，安提柯一世自此独霸东方。"],"history":"公元前三一六年冬，安提柯一世冒寒穿漠奇袭欧墨涅斯冬营未果，两军决战于加比埃奈盐碱荒原。交锋扬起遮天盐尘，安提柯一世借浓尘密派骑兵绕后夺获欧墨涅斯大营及银盾兵家眷积蓄；银盾兵虽正面胜敌，却为赎回妻儿家产哗变捆献欧墨涅斯投降。定值：敌将取欧墨涅斯。","sources":"普鲁塔克·欧迈尼斯传；西西里的狄奥多罗斯·历史丛书·第十九卷"},
    "bfe_antigonus@-317": {"strategic":["公元前三一七年，继业者混战正酣，手握重兵的独眼宿将安提柯一世决意铲除王室派支柱欧墨涅斯。欧墨涅斯收服传奇银盾老兵，又获东方诸省总督携战象骑兵归附；安提柯一世跨越两河紧追入高原，深秋与欧墨涅斯对阵于帕莱塔西奈山谷。"],"tactical":["帕莱塔西奈背山临谷，两军皆以方阵居中、战象列前。初战安提柯一世左翼擅出受挫，中路步阵更被欧墨涅斯的宿战银盾老兵撞碎，全线濒危。危急关头，安提柯一世窥见银盾兵猛追过速而与敌左翼脱开巨口，即亲率右翼重骑刺入缺口侧击敌翼，迫欧墨涅斯回救；入夜安提柯一世返占战场扎营，夺回主动。"],"history":"公元前三一七年秋，亚细亚统帅安提柯一世追击效忠马其顿王室的希腊名将欧墨涅斯进入波斯高原帕莱塔西奈山地。会战中欧墨涅斯麾下银盾老兵击溃敌方阵，左翼亦占优；危急关头安提柯一世亲率右翼重骑斜插敌阵脱节缺口反击得手，连夜返占战场迫欧墨涅斯撤离。定值：敌将取欧墨涅斯。","sources":"西西里的狄奥多罗斯·历史丛书·第十九卷；普鲁塔克·欧迈尼斯传"},
    "bfe_crassus": {"strategic":["公元前五三年，罗马共和国显贵克拉苏为追平同僚赫赫武功，出镇叙利亚后不宣而战，统重装军团东渡幼发拉底河大举入侵安息帝国。克拉苏拒纳盟邦取道北方山地的良言，轻信向导深入两河酷热荒漠，在卡莱原野撞上安息名将苏伦的骑兵主力。"],"tactical":["卡莱原野黄沙无际、烈日炙烤，全无山林依托。克拉苏结成巨大空心方阵迎敌，苏伦则以重装铁骑配合轻装弓骑环绕驰射；更用骆驼源源运送箭矢，令罗马盾阵抱头挨射寸步难行。克拉苏命爱子率骑兵突围反击却遭诱歼，首级被挑于枪尖示众；罗马军心崩溃夜撤卡莱，次日克拉苏赴会谈判时遇害，军团鹰旗尽落敌手。"],"history":"公元前五三年，罗马三巨头之一克拉苏为博取武功，自叙利亚渡幼发拉底河东侵安息帝国。克拉苏拒走北方山地，被向导诱入美索不达米亚酷热荒原；在卡莱近郊遭安息年轻名将苏伦以轻弓骑与重装铁骑协同围击，爱子战死、方阵崩溃，克拉苏赴议和被杀，军团鹰旗尽失。","sources":"普鲁塔克·克拉苏传；狄奥·卡西乌斯·罗马史·第四十卷"},
    "bfe_crassus@-71": {"strategic":["公元前七一年，色雷斯角斗士领袖斯巴达克斯率义军纵横意大利两载，连挫罗马军团；元老院震恐，拜豪门显贵克拉苏挂帅平叛。克拉苏以严酷军法重振士气，筑长墙困敌并剪除其分营支队，将斯巴达克斯主力逼至卢卡尼亚西拉鲁斯河畔。"],"tactical":["西拉鲁斯河上游丘陵起伏，退路已被罗马军团层层封锁。因远征西班牙的友军即将返国争功，克拉苏急令军团挖壕设防逼敌速决；斯巴达克斯知无退路，在阵前亲手刺杀坐骑以示与士卒同生共死，率义军向克拉苏本阵发起舍命猛冲。克拉苏沉着督重装步兵结密盾硬顶，苦战中斯巴达克斯身被重创力战阵亡，起义就此覆灭。"],"history":"公元前七一年春，横扫意大利两载、连败多支执政官大军的色雷斯角斗士起义统帅斯巴达克斯被新帅克拉苏筑长墙深壕困于意大利靴尖瑞吉乌姆半岛，冒风雪突围后分裂，克拉苏先行歼灭分营的高卢日耳曼部众。随着庞培自西班牙班师逼近，急于独得全功的克拉苏与斯巴达克斯主力决战于卢卡尼亚西拉鲁斯河源；斯巴达克斯阵前刺死战马步战冲向克拉苏，连斩两名百夫长后力战身亡，起义告终。","sources":"普鲁塔克·克拉苏传；阿庇安·内战史·第一卷"},
    "bfe_xiangliang": {"strategic":["公元前二〇八年，楚将门之后项梁渡江北上举起反秦大旗，拥立楚怀王，接连在东阿、濮阳大破秦军，各路义军纷纷归附。连战皆捷令项梁滋生轻秦之心，拒纳谋士宋义骄兵必败之谏，率军推进至定陶，浑然不知秦帅章邯已获关中增援悄然逼近。"],"tactical":["定陶地处济水冲要平原，深秋大雨不止，道路泥泞。项梁自恃前番屡挫章邯，以为秦军胆寒远遁，军营戒备松懈。岂料章邯合关中生力军冒雨潜行，趁寒夜风雨交加令士卒衔枚疾扑定陶楚营；楚军梦中猝不及防，全营惊溃，项梁拔剑率亲随殊死搏杀，终寡不敌众阵亡沙场，反秦大局一时陷入低谷。"],"history":"公元前二〇八年，楚名将项燕之子项梁渡淮举兵反秦，拥立楚怀王，连在东阿、濮阳、雍丘大破秦军，声威大震而渐生骄轻，不听宋义忠告。秦二世尽发关中兵增援名将章邯；九月秋雨连绵，章邯趁楚军麻痹懈怠夜袭定陶楚营，项梁措手不及力战阵亡。","sources":"史记·项羽本纪；史记·秦始皇本纪"},
    "bfe_zhanghe": {"strategic":["公元二二八年春，蜀汉大军声东击西突现祁山，陇右三郡望风叛魏，关中朝野惊骇。曹魏明帝御驾西镇长安，特命百战宿将右将军张郃统关中步骑精锐星夜西驰，抢夺通往陇右的咽喉孔道街亭；蜀汉前锋主将马谡亦奉命兼程赶抵街亭设防，两军前锋在此狭路相逢。"],"tactical":["街亭位于陇山古道出口，谷道旁孤山高耸而水源尽在山脚。马谡死搬兵书居高临下之语，违背节度舍弃城邑水源，将全军拉上南山孤峰扎营。老练的张郃一眼看透死穴，分兵围住山下彻底截断蜀军汲水通路；山上断水干渴大乱，张郃乘势督铁骑重步四面纵火仰攻，马谡全军溃散弃山奔逃，曹魏一举扭转陇右危局。"],"history":"公元二二八年春，蜀汉丞相诸葛亮首次出祁山北伐，陇右天水、南安、安定三郡叛魏响应，关中大震。魏明帝西镇长安，命宿将右将军张郃率精锐步骑西进迎击。诸葛亮违众议遣参军马谡督前锋扼守咽喉街亭；马谡舍水上山扎营，张郃断绝山下汲道四面围攻，大破马谡，一战收复陇右三郡。","sources":"三国志·魏书·张乐于张徐传；三国志·蜀书·诸葛亮传"},
    "bfe_zhanghe@231": {"strategic":["公元二三一年夏，蜀汉丞相诸葛亮北伐祁山，在卤城交锋后因夏雨连绵、栈道粮运不继，有序收拢全军东退汉中。曹魏统帅急令老将车骑将军张郃率骑步劲旅衔尾追击；张郃深谙兵法归师勿遏之理力谏勿追，怎奈主帅严令难违，只得督兵追向木门道。"],"tactical":["木门道两山绝壁对峙如门，谷底西汉水湍急，山径逼仄幽暗。诸葛亮早料魏军必来追袭，预先在峡谷两侧悬崖密林中埋伏精熟连弩射手，静候追兵入彀。张郃明知前途险恶仍身先士卒督军踏入峡谷，行至谷中号炮骤响，两岸高山强弩齐发箭如飞蝗；魏军拥挤谷底无处躲避，张郃右膝不幸中箭，一代沙场宿将喋血阵亡。"],"history":"三国魏太和五年即蜀建兴九年夏六月，诸葛亮第四次北伐于卤城击败司马懿后，因天雨运粮不继自祁山退军回汉中。大都督司马懿命车骑将军张郃率军追击，张郃引军法归师勿遏力谏不听，被迫督兵追入险仄幽深的木门道峡谷，中诸葛亮预设高山连弩埋伏，右膝中飞矢阵亡，以身殉职。","sources":"三国志·魏书·张乐于张徐传"},
    "cai_lishuo": {"strategic":["公元三一一年春，执掌西晋大权的东海王病死军中，随军王公秘不发丧；众推清谈领袖太尉王衍为帅，拥西晋仅存的中央禁军与车乘护送灵柩东还海滨。正在河南经略的汉赵猛将石勒敏锐捕捉战机，亲选精锐轻骑弃辎重昼夜疾驰，直追王衍大军至宁平城。"],"tactical":["宁平城四野平旷无险，王衍所统晋军携家眷财帛车队绵延漫野，闻追骑骤至惊慌挤作一团。石勒分遣铁骑如旋风般将晋军长龙团团锁死，不下马肉搏而由骑射手环绕四面密集攒射；晋军进退不得自相践踏，尸积如山全军覆没。王衍被擒后犹自脱罪劝进，石勒斥其空谈误国，入夜命人推倒高墙将王衍与晋室王公尽数压毙。"],"history":"公元三一一年春，西晋太傅东海王司马越忧死项城，军中秘不发丧，推太尉王衍率西晋最后中央主力及宗室公卿护丧东归封国。汉赵骁将石勒闻报亲统精锐轻骑星夜追击，于苦县宁平城追及晋军，命铁骑四面合围攒射，晋军尸积如山无一幸免，石勒生擒王衍并推墙压杀之。定值：战场改定为宁平城。","sources":"晋书·石勒载记上；晋书·王衍列传；资治通鉴·晋纪九"},
    "cai_lishuo@314": {"strategic":["公元三一四年春，盘踞幽州重镇蓟城的西晋大司马王浚手握鲜卑乌桓强骑，骄奢淫逸妄图僭号称帝，屡与镇守襄国的石勒争衡河北。石勒采纳谋主张宾奇计，先派使者奉重宝卑辞上表诈劝王浚登基，趁王浚狂喜麻痹之际，亲统精骑昼夜兼程北袭蓟城。"],"tactical":["蓟城城郭宏大、街巷纵横，王浚正沉醉于受禅幻梦毫无战备。石勒冒春雨执火炬疾行抵城下，见城门大开却恐街巷藏有伏兵；他急命士卒驱赶大批牛羊塞满诸道以防暗算，随即统铁骑长驱杀入府衙。王浚惊惶失措当场被生擒，押回襄国闹市斩首；石勒兵不血刃夺占蓟城，幽冀沃野尽归囊中。"],"history":"西晋建兴二年春，盘踞幽州蓟城的大司马王浚骄奢暴虐谋僭称尊号，镇守襄国的石勒采谋主张宾之计，先遣舍人王子春奉重宝卑辞上表诈劝王浚称帝，待王浚狂喜不设戒备，石勒亲率轻骑火炬夜行倍道奇袭幽州。三月抵蓟城，石勒驱牛羊塞诸街巷防伏兵，入城生擒王浚押送襄国斩首，尽有幽冀。","sources":"晋书·石勒载记上"},
    "cai_lishuo@328": {"strategic":["公元三二八年冬，分据东西的前赵主刘曜与后赵主石勒迎来北方霸权总决战；刘曜先挫后赵前锋，乘胜南渡黄河重兵合围洛阳。群臣畏惧劝阻亲征，石勒按剑怒斥决意孤注一掷，亲统步骑主力自成皋津秘密抢渡黄河，疾驰洛阳城西与刘曜一决存亡。"],"tactical":["洛阳西依洛水谷地、东扼成皋天险。刘曜未分兵把守成皋渡口，反在洛阳城西终日痛饮懈怠军务；石勒轻骑滑过险津抢先入据金墉城，将主力隐蔽集结于洛阳诸门之内。决战清晨石勒命诸将自北门与东门分路夹击，亲自披甲出西阳门正面猛冲；嗜酒昏乱的刘曜坠马被后赵兵生擒，石勒一战扫灭前赵，尽统北方河山。"],"history":"后赵太和元年即前赵光初十一年秋，前赵主刘曜于高候大破石虎后南围洛阳。后赵主石勒拒群臣退守之议，亲统步骑自成皋津渡河疾救洛阳，见刘曜未守成皋大喜。十二月石勒入据金墉城，趁刘曜嗜酒昏醉列阵洛西之际，命石虎、石堪、石聪分门夹击，石勒亲出西阳门督战大破前赵军，生擒刘曜统一北方。","sources":"晋书·石勒载记下"},
    "cao_d_caocao": {"strategic":["公元二〇〇年，河北霸主袁绍一统幽冀青并四州，挟骄盛兵威南渡黄河，企图一举踏平许都。司空曹操兵力居劣，在白马与延津连挫敌锋后，果断收拢主力退扼鸿沟要冲官渡筑垒深守；双方遂展开决定中原归属的相持对决。"],"tactical":["官渡地处黄河南岸沙原水口，锁钥许都北门。袁绍堆筑高橹土山俯射曹营，曹操造霹雳发石车与地道针锋相对，苦撑至军粮将竭仍死战不退。寒冬袁营谋士许攸投奔献策，指明袁军命脉屯粮重地乌巢守备空虚；曹操当机立断亲统轻骑衔枚夜袭，一把大火烧尽乌巢粮储，袁绍军心瓦解全线大溃，北方霸权自此易手。"],"history":"公元二〇〇年，河北袁绍兼有幽冀青并四州，倾大军南渡黄河进逼许都。司空曹操兵少粮匮，先解白马之围斩颜良、延津诛文丑，主动收兵退守官渡坚壁相持。冬十月袁绍谋士许攸来投献计，曹操亲率轻骑乘夜奇袭乌巢焚尽袁军屯粮，袁绍大军崩溃北逃，曹操奠定统一北方之基。","sources":"三国志·魏书·武帝纪；三国志·魏书·袁绍传；资治通鉴·汉纪五十五"},
    "cao_d_caocao@198": {"strategic":["公元一九八年秋，割据徐州的骁将吕布再度背叛朝廷，南结袁术猛攻小沛，成为许都东侧芒刺。司空曹操采纳谋臣速剪东顾之忧再图河北的方略，亲统大军东征徐州；曹操先破外围彭城守敌，一路进逼徐州治所下邳，将出城迎战失利的吕布困入孤城。"],"tactical":["下邳地势低平，沂水与泗水自城北交汇南流。吕布自恃骑射无双且城中粮多，闭门死守等待淮南外援；曹操先以急攻挫其突围之念，随即采荀攸、郭嘉奇策，命士卒掘开沂泗河堤引大水灌入下邳。寒冬水淹三月城垣崩坏，吕布猜忌刚愎致诸将离心，部将乘隙生缚谋主举城献降，吕布退登白门楼就擒伏诛，徐州尽归曹操。"],"history":"东汉建安三年秋九月，吕布复叛朝廷与袁术连结攻刘备于小沛，司空曹操采荀攸、郭嘉速灭吕布以除官渡后顾之忧之策，亲统大军东征徐州。曹操于彭城破陈宫，进至下邳连挫吕布骑兵将其逼入城中，用荀攸、郭嘉计决沂水、泗水灌城三月，冬十二月宋宪、魏续缚陈宫降，吕布于白门楼就擒伏诛。","sources":"三国志·魏书·吕布臧洪传"},
    "cao_d_caocao@211": {"strategic":["公元二一一年春，丞相曹操遣军借道关中进讨汉中，关西猛将马超与韩遂诸部疑曹军假途灭虢，遂合纵举兵反叛，进据天险潼关抗拒朝廷。曹操命偏师先行潜渡蒲坂津迂回河西，自统大军赶赴潼关正面牵制马超主力，筹划渡河越渭的决胜之策。"],"tactical":["潼关南倚秦岭绝壁、北临黄河激流，马超倾关西精骑紧盯关前。曹操避开仰攻，冒敌骑截杀北渡黄河，乘寒夜泼水浇沙冻成冰城稳住滩头，继而架浮桥跨过渭水。趁敌求地求和，曹操巧施离间妙计，阵前单骑交谈并涂改书信，令马超深疑韩遂内乱顿生；曹操看准时机纵虎豹精骑猛冲，一战荡平关西联军。"],"history":"东汉建安十六年春，曹操欲借道关中伐汉中张鲁，关西马超、韩遂、杨秋等十部疑惧举兵反曹，合重兵据守潼关。曹操命徐晃、朱灵先渡蒲坂津据河西，自统主力于潼关正面诱敌后北渡黄河，泼水结冰筑沙城，及渡渭水采贾诩离间计令马超、韩遂互疑内乱，九月纵虎豹骑大破关西联军，平定关中。","sources":"三国志·魏书·武帝纪"},
    "caoren": {"strategic":["公元二一九年秋，镇守荆州的猛将关羽乘刘备夺取汉中之威，尽起荆襄水陆劲旅大举北伐，将北方南线咽喉樊城团团围困。征南将军曹仁坐镇樊城统筹防务，未几城北外援遭秋雨大水吞没覆灭，孤城外断救兵、浊浪拍城，华夏震动；曹仁临危镇定，誓与孤城共存亡。"],"tactical":["樊城紧邻汉水北岸，连旬暴雨令汉水暴涨数丈，孤城仅露垛口于汪洋之中，关羽乘大船直抵城垣之下架梯猛攻。或劝乘夜弃城北走，曹仁采纳满宠之言，指出弃樊则黄河以南尽失，当众沉白马入水盟誓死守。守军感泣拼死堵住坍塌缺口，苦撑至大水渐退、徐晃援军杀到，曹仁开城夹击击退关羽，保住中原南屏。"],"history":"公元二一九年秋，汉中王刘备前将军关羽率荆州主力北攻襄樊，征南将军曹仁固守樊城被重重围困。曹操所遣于禁援军遭汉水暴溢覆没，樊城城墙多处崩塌几与水齐。曹仁采满宠之谏沉白马与将士盟誓同心死守，顶住关羽水师昼夜急攻，直至徐晃援军赶到内外合击解樊城之围。","sources":"三国志·魏书·诸夏侯曹传；资治通鉴·汉纪六十"},
    "caoren@209": {"strategic":["公元二〇九年，赤壁战后北方大军引归休整，征南将军曹仁受命留镇荆州咽喉南郡江陵，独自直面乘胜溯江而上的江东名将周瑜。周瑜水陆大军渡江压境，并分兵奇袭西邻夷陵企图合围孤城；曹仁临危不惧，激励守军整备器械，誓死钉在江陵城头。"],"tactical":["江陵外临大江、内控沮漳平畴，乃荆北南屏。周瑜前锋逼近城下，曹仁先派部将出城挫敌锐气，不料陷入重围；曹仁不顾属官苦谏，披甲跨马率骁勇亲骑突入江东军阵，硬生生杀开血路救出部将与余卒，神勇惊服三军。此后岁余相持中曹仁据城死战，重箭射伤周瑜令敌伤亡惨重，待北境防线稳固后方奉令全师北还。"],"history":"赤壁战后曹操北归，留征南将军曹仁与徐晃镇守南郡江陵拒东吴大都督周瑜。周瑜渡江逼城，曹仁先遣部将牛金迎战被重重围困，曹仁不顾长史陈矫劝阻，亲率数十壮骑冲入吴阵救出牛金并返身救回余卒，陈矫叹为天人。曹仁坚守孤城岁余重创周瑜，令东吴付出惨重代价后方奉命全师北撤。","sources":"三国志·魏书·诸夏侯曹传"},
    "caoren@223": {"strategic":["公元二二三年春，孙权在挫败西线蜀军后再度违背盟约拒遣质子入洛，曹魏文帝震怒之下分兵三路大举伐吴。曹魏大司马曹仁奉诏统领步骑主力南下江淮，兵锋直指历来南北反复拉锯的水陆锁钥濡须口，与年轻胆壮的东吴守将朱桓展开智勇交锋。"],"tactical":["濡须口夹水筑坞，外接巢湖、南通大江，中洲横卧水道中央。曹仁欲用声东击西之计，故意张扬将东攻羡溪，诱骗朱桓分兵东救，实则亲督大军与部将分扑濡须本城与水寨中洲。不料朱桓在分兵后迅速识破虚实，偃旗息鼓诱魏军攻城，同时借中洲风浪水道截杀登洲孤军；曹仁攻城受挫、中洲偏师覆没，无奈收拢兵马北退。"],"history":"三国魏黄初三年冬至四年春，吴王孙权在夷陵破蜀后拒绝送质于魏，魏文帝曹丕震怒兴三路大军伐吴，命大司马曹仁统步骑南攻江淮重镇濡须口。曹仁扬言东攻羡溪以诱分东吴濡须督朱桓守兵，实则亲督主力与子曹泰、将军常雕袭取濡须城及中洲，遭朱桓识破反击斩常雕，曹仁失利退还。","sources":"三国志·吴书·朱治朱然吕范朱桓传"},
    "chenghan_lite": {"strategic":["公元三〇二年，关陇饥荒迫使大批流民南入巴蜀求生，西晋益州官吏却限期驱逐截杀；流民遂推巴氐豪帅李特起兵自卫，屯营广汉鹿头关与绵竹一带。西晋朝廷急拜将门之后张微为广汉太守进驻德阳，统集官军扼守险隘，企图乘流民立足未稳一举剿灭李特。"],"tactical":["广汉德阳至鹿头关山谷绵延，控扼成都平原北门。张微探知李特分兵略地、本营空虚，率西晋精兵连夜翻山突袭李特大营；营垒火起，李特临危不乱，收拢精悍部曲退据山谷险阻死守待援。长子率外营劲卒闻讯疾驰杀回，父子两路自山谷前后死命夹击；西晋军困于窄谷全军覆没，张微被斩，李特乘胜进逼成都。"],"history":"公元三〇二年秋，入蜀就食的关陇六郡流民受西晋地方官催逼截杀，推巴氐豪帅李特为主据绵竹与广汉自保。西晋朝廷与河间王起复名门之后张微任广汉太守，进据德阳险要讨伐李特；趁李特分营在外，张微乘虚夜袭李特本营，李特临危据山谷逆击，会合长子李荡夹攻破斩张微。定值：年份改定为三〇二年、敌方定为司马晋。","sources":"晋书·李特载记；资治通鉴·晋纪七"},
    "chenghan_lite@303": {"strategic":["公元三〇三年春，巴氏流民领袖李特不堪西晋益州刺史罗尚贪残逼迫，率关陇流民揭竿反抗，连破官军水陆防线进逼蜀都成都。李特一举攻占成都少城并建号改元，罗尚仓皇退保太城闭门死守，一面遣使虚辞乞和麻痹李特，一面暗中联络蜀地豪强坞壁。"],"tactical":["成都分太城与少城双城并峙，外围村落坞堡星罗棋布。李特入少城后仁厚爱民，却因大军缺粮，不顾诸将力谏信以为真，准许流民将士分散入各村坞壁就食，致主力兵势大散。罗尚探知流民各营孤立无备，暗通诸坞主约定日期，突开太城大门倾军掩杀，各坞豪强同时反戈夹击；李特措手不及连营溃败，退至新繁力战阵亡。"],"history":"西晋太安二年春正月，李特渡江击破益州刺史罗尚水陆防线，攻克成都少城，罗尚退保太城乞和。李特建元建初，礼贤恤民，惟不听李流、任回勿信蜀民虚降之谏，准许流民军分散就食各村坞壁。二月罗尚暗结蜀民坞主并得荆州宗岱水军声援，出太城内外合击连破流民散营，李特退新繁力战阵亡。","sources":"晋书·李特载记"},
    "chu_guanyu": {"strategic":["公元二一九年秋，镇守荆襄的前将军关羽响应汉中胜势，亲统水陆劲旅挥师北伐，把襄阳与汉水北岸重镇樊城围困如铁桶。北方大震，急命老成宿将左将军于禁假节钺督领精锐援师星夜南救；于禁抵达樊城北郊，未察秋汛水文便在低洼平川扎下连营，关羽早已备妥高大战舰严阵待机。"],"tactical":["樊城北郊罾口川地势低平，南接汉水干流。入秋暴雨狂泻十余日，汉水骤涨漫堤，平地水深数丈，于禁诸营瞬间沦为泽国，北方旱兵狼狈攀登高阜避水。关羽抓住天赐良机，亲乘巨舰指挥精锐水师顺流四面合围猛射；顽抗的敌方副将力战就戮，走投无路的于禁举众乞降，关羽水淹七军威震华夏，许都几欲迁避。"],"history":"公元二一九年秋，前将军关羽统荆州水陆大军北伐襄樊，重重围困樊城曹仁。魏王曹操急遣宿将左将军于禁假节钺督七军南下救援，屯营于樊城北郊低洼川道。秋八月大雨连旬、汉水暴溢，于禁诸营尽被大水淹没，关羽亲乘大船督水师猛攻，生擒于禁、斩杀庞德，威震华夏。定值：战场改定为樊城。","sources":"三国志·蜀书·关张马黄赵传；三国志·魏书·张乐于张徐传"},
    "chu_guanyu@200": {"strategic":["公元二〇〇年春，河北霸主袁绍倾师南下争夺中原，先遣麾下骁将颜良渡过黄河猛围东郡重镇白马，河南震动。曹军采声东击西之计佯趋延津分散袁军兵力，随即轻骑疾驰东救白马；暂栖曹营的名将关羽受命与同僚共统前锋铁骑，迎面撞上颜良大军。"],"tactical":["白马城南黄河故道平畴开阔，颜良见救兵远来兵少，麾动河北重兵列开严整大阵迎战。关羽立马高阜远眺，一眼认出重阵之中颜良华丽的帅旗麾盖，当即纵马挥刃孤身直插敌阵中坚；河北将士猝不及防纷纷披靡闪避，关羽冲至麾盖下亲手刺死颜良，割取首级从容策马归阵，河北军群龙无首大溃，白马之围立解。"],"history":"东汉建安五年春，袁绍大军南下黎阳，遣大将颜良渡河围东郡太守刘延于白马。四月司空曹操采荀攸声东击西之计，引军先趋延津佯作渡河截后，诱使袁绍分兵西应，随即轻兵疾驰救援白马。关羽时暂栖曹营，与张辽同为前锋，望见颜良麾盖策马冲入敌阵刺杀颜良并斩其首还，遂解白马之围。","sources":"三国志·蜀书·关张马黄赵传"},
    "danyang_huanwen": {"strategic":["公元三四七年春，割据巴蜀四十余载的成汉政权在末主李势治下纲纪败坏、边备空虚。志图大业的东晋荆州刺史桓温看准灭国良机，不等建康朝廷批复便留书出师，精选荆楚水师溯长江三峡疾进；抵彭模后桓温断然弃船留辎，率轻兵避开敌军江北防线直扑成都。"],"tactical":["成都西南笮桥横跨锦江，李势惊闻晋军天降，倾成都兵力背城死战。初交锋成汉军拼死猛冲，晋军前锋失利参军战殁，敌箭直射至桓温马前，众将欲退。千钧一发之际，传令鸣金的鼓吏慌乱中竟误擂进军战鼓；晋军闻鼓声震天以为全线总攻，人人拔刀怒吼反扑，一鼓冲垮李势主力直入成都，巴蜀重归东晋。"],"history":"公元三四七年春，东晋安西将军荆州刺史桓温不等朝廷诏准，先斩后奏统水师自江陵溯江伐蜀。桓温弃舟彭模轻装疾进，避开成汉江北阻截大军直插成都，与成汉末主李势倾国主力决战于成都西南笮桥。前锋受挫矢及马首之际，鼓吏误擂进军鼓，晋军死战大破李势，攻灭成汉。","sources":"晋书·桓温列传；晋书·李势载记；资治通鉴·晋纪二十"},
    "danyang_huanwen@354": {"strategic":["公元三五四年春，东晋征西大将军桓温志在立北伐不世之功，统荆楚水陆精兵自江陵北上，讨伐初据关中称帝的前秦君主苻健。桓温分遣偏师出子午谷牵制，亲率主力突破武关长驱北出秦岭；苻健急调皇子与王公精锐东扼蓝田险隘，阻截东晋大军。"],"tactical":["蓝田控扼武关出山咽喉，西北直通白鹿原与灞水，拱卫长安东门。桓温督晋军精锐猛冲蓝田关隘，一举生擒前秦守将，继而在白鹿原击破前秦太子大军，兵锋直抵灞水之畔，关中百姓争持牛酒迎劳王师。然而苻健早将田野青麦尽数抢割入长安坚壁死守；桓温顿兵坚城之下待熟麦落空，初夏粮尽只得击退追兵引师南归。"],"history":"东晋永和十年春二月，征西大将军桓温统步骑自江陵水陆北伐立国关中的前秦皇帝苻健。桓温命司马勋出子午道，自统主力破荆子关出武关，于蓝田生擒苻健弟淮南王苻生前部，大破太子苻苌与丞相苻雄于白鹿原，进驻长安东郊霸上，三辅豪杰迎降；因苻健坚壁清野刈麦，六月桓温乏粮退师。","sources":"晋书·桓温列传"},
    "danyang_huanwen@369": {"strategic":["公元三六九年夏，东晋大司马桓温统江淮荆楚水陆大军再度北伐前燕，连破燕军进抵黄河与淇水交汇要冲枋头，前燕震恐几欲弃都东奔。危急关头前燕名将吴王慕容垂挺身请命挂帅御敌，一面西联前秦援骑，一面率燕军精锐赶赴枋头迎战桓温。"],"tactical":["枋头扼守黄河漕运枢纽，晋军孤师深入全赖河道运粮接济。桓温未采速取敌都之策而按兵待粮，慕容垂看准晋军命脉，先派精骑截断石门水道、尽焚晋军粮船；继而又联合赶到的前秦骑兵步步紧逼。入秋晋军断粮恐慌，桓温被迫焚舟陆退，行至襄邑遭慕容垂铁骑猛扑大败而归。"],"history":"东晋太和四年夏，大司马桓温统江淮荆楚水陆大军第三次北伐前燕，拒郗超轻兵直取邺城或顿河漕运两策，缓进至淇水口枋头。前燕吴王慕容垂受命御敌，遣慕容德断绝石门水道焚晋粮船，并引前秦苟池、邓羌援骑威胁侧翼。九月桓温粮尽焚舟陆退，至襄邑遭慕容垂与前秦骑兵夹击大败。","sources":"晋书·桓温列传"},
    "delan_sulun": {"strategic":["公元前五三年，罗马统帅克拉苏撕毁盟约渡河东侵，企图一举吞并两河流域。安息国王率步卒北制亚美尼亚，将阻击罗马主力的重任托付给年轻有为的贵族名将苏伦；苏伦纯以精锐弓骑与披甲重骑组军，诱敌深入卡莱荒原。"],"tactical":["卡莱旷野平坦无遮，极利骑兵驰突。苏伦先令具装铁骑披兽皮遮掩甲光，逼近克拉苏方阵时骤亮明晃钢甲、擂响革鼓夺其心魄；随即命轻弓骑施展回马射，由骆驼驮载箭囊循环补给，以不绝箭雨钉死敌步阵，再用重骑长矛冲碎出击之敌。克拉苏突围无望赴约丧命，苏伦一战折断罗马东征锋芒。"],"history":"公元前五三年，罗马统帅克拉苏率重兵入侵美索不达米亚，安息国王率步兵北上牵制亚美尼亚，命年轻名将苏伦统全骑兵军团于卡莱原野迎击。苏伦首创骆驼运箭无限补给战术，以回马弓骑消磨结合具装铁骑冲杀，歼灭罗马突击队并诱杀克拉苏，挡住罗马东扩。","sources":"普鲁塔克·克拉苏传；狄奥·卡西乌斯·罗马史·第四十卷"},
    "dibisi_tahaerka": {"strategic":["公元前六七三年，新亚述帝国囊括两河与黎凡特大部，唯尼罗河流域在法老塔哈尔卡治下统一强盛，堪与亚述抗衡。塔哈尔卡持续资助沿海诸城抗亚述，引来亚述王以撒哈顿倾师南侵。闻知敌军强穿西奈沙碛直扑东门佩鲁西姆，塔哈尔卡即调埃及与库施精锐北上东境迎击。"],"tactical":["佩鲁西姆地处西奈沙漠与尼罗河三角洲水网交界要冲，沙丘与河汊交错。塔哈尔卡依托水道塞堡严密布防、蓄锐待敌；以撒哈顿催军昼夜穿过缺水荒原，抵前线时饥渴交迫、阵形散乱。待亚述前锋踏入湿软沙泽受阻，塔哈尔卡挥师全线反扑重创敌军，迫使以撒哈顿北撤，成功保住埃及独立。"],"history":"公元前六七三年初春，亚述王以撒哈顿率军疾穿西奈走廊远征埃及东门佩鲁西姆。埃及第二十五王朝法老塔哈尔卡预作整备，乘亚述军长途跋涉疲敝之际迎头痛击，大败亚述远征军，迫使以撒哈顿退回亚述。异说：巴比伦编年史或折算为前六七四年，定稿表取前六七三年。","sources":"巴比伦编年史；以撒哈顿王家铭文"},
    "dibisi_tahaerka@-671": {"strategic":["公元前六七一年，埃及法老塔哈尔卡击退亚述首次入侵两载后，继续联结推罗共抗亚述。亚述王以撒哈顿卷土重来，重金征募阿拉伯驼队克服西奈缺水天险，突破埃及东门防线疾进。塔哈尔卡急调上下埃及与库施精锐会聚古都孟菲斯，决意凭尼罗河枢纽坚城阻挡亚述兵锋。"],"tactical":["孟菲斯控扼上下埃及咽喉，白墙外环绕尼罗河干流与深壕。塔哈尔卡披挂坐镇，先遣精兵出城挫敌锐气；怎奈亚述铁甲步骑层层压进，塔哈尔卡督战中箭负伤，守军退回城内固守。以撒哈顿旋即水陆合围，督冲车云梯强攻撕裂外城；塔哈尔卡见孤城难支，突围南撤底比斯，留存南方复国火种。"],"history":"公元前六七一年夏，亚述王以撒哈顿借阿拉伯驼队供水越过西奈，突破埃及东防进逼孟菲斯。法老塔哈尔卡亲督守军在孟菲斯浴血拒战，终因身受箭伤、外郭被破而南退上埃及底比斯，孟菲斯陷落，王室家眷被俘，塔哈尔卡其后仍据南方继续抗争。","sources":"巴比伦编年史；以撒哈顿辛吉尔利胜利碑"},
    "dingzhou_d_murongchui@384": {"strategic":["公元三八四年春，淝水大败令前秦帝国分崩离析，完师归来的鲜卑名将慕容垂在黄河畔摆脱羁绊举兵复国，自称燕王开创后燕。为夺回昔日前燕故都号令河北，慕容垂倾发鲜卑与关东乌桓义兵北上，重重包围前秦宗室长乐公苻丕死守的河北名都邺城。"],"tactical":["邺城城垣宏丽坚厚，北引漳水入城，苻丕督前秦关中老兵拼死拒守。慕容垂先引漳水灌淹外郭，迫苻丕退缩中城，继而在外围挫败怀有异心的东晋援军；见孤城困兽犹斗，慕容垂巧施围师必阙之策，撤开西面围网放任饥疲的苻丕弃城西奔晋阳，终不损精锐收复故都邺城，奠定后燕河北霸业。"],"history":"公元三八四年春，淝水战后保全本部的前秦冠军将军慕容垂于荥阳脱身起兵复国，自称燕王建立后燕，挥师北围镇守前燕故都邺城的前秦长乐公苻丕。慕容垂引漳水灌邺外城迫苻丕退守中城，击败东晋刘牢之援兵并巧用围城必阙纵苻丕西奔晋阳，三八五年秋收复故都邺城，奠定后燕河北基业。","sources":"晋书·慕容垂载记"},
    "dingzhou_d_murongchui@394": {"strategic":["公元三九四年，鲜卑西燕主慕容永割据并州上党称帝，与定鼎河北的后燕形成二燕并立之势。年近古稀的后燕成武帝慕容垂力排群臣畏老怯战之议，决意亲统大军翻越太行西灭西燕；慕容垂以疑兵牵制太行东口，主力出奇道进逼慕容永国都长子。"],"tactical":["长子高处太行山脊上党盆地，东有壶关、南有天井关拱卫，地势险固。慕容永误判燕军主攻方向分兵把守东关，慕容垂却遣偏师自南路天井关奇袭台壁，诱慕容永主力出战并将其设伏击溃，乘胜合围长子孤城。围困至秋八月城内人心瓦解，西燕守将开城内应迎入后燕铁骑，慕容垂生擒斩杀慕容永，一举兼并并州实现燕室一统。"],"history":"公元三九三年冬至三九四年秋，年近七旬的后燕成武帝慕容垂力排群臣畏老之议，自中山亲征割据并州上党称帝的西燕主慕容永。慕容垂扬言出滏口、壶关吸引西燕重兵，暗遣慕容瓒自天井关奇袭台壁诱败慕容永主力，六月合围西燕国都长子，八月开内应破城斩慕容永，一统燕室兼有并州。","sources":"晋书·慕容垂载记"},
    "dongxian_sunbin": {"strategic":["公元前三四二年，魏将庞涓大举伐韩，韩国急向齐廷乞师。齐军师孙膑献缓救待敝之策，待韩魏相持俱疲后，辅主将径逼魏都大梁以攻其必救。前线庞涓果然盛怒撤围东返追截，孙膑遂因势利导，引诱宿敌一步步踏向预设绝地马陵道。"],"tactical":["马陵道深涧绝壁夹束羊肠狭路。孙膑洞悉三晋兵悍而轻齐，命齐军佯退并逐日减灶，伪造士卒逃散假象。庞涓查灶大喜，果弃大军仅携轻骑穷追；孙膑算定其日暮必抵马陵道，预伐木塞路，刮白大树书字，伏善射弩手令见火即发。庞涓夜入绝谷举火读字，刹那乱箭攒射，魏军覆没、庞涓自戕，孙膑大仇得报。"],"history":"公元前三四二年，魏帅庞涓攻韩，齐威王命田忌为将、孙膑为师趋大梁诱庞涓回师。孙膑利用庞涓悍勇轻齐之心，命齐军逐日减灶诱其孤军夜追，算定行程于马陵道刮树书字、伏强弩待火齐射，歼灭魏军精锐逼死庞涓。定值：同场三行统一取前三四二年、战场马陵道。","sources":"史记·孙子吴起列传；孙膑兵法"},
    "dongxian_sunbin@-353": {"strategic":["公元前三五三年，魏将庞涓重兵围困赵都邯郸，赵急乞师于齐。齐王用曾遭庞涓陷害受膑刑的孙膑为军师，坐帷车辅主将出征。孙膑力劝勿赴河北硬拼，主张乘魏境空虚直趋大梁以攻其必救；齐军依计西进，果诱庞涓弃赵回援，奔向孙膑预设的桂陵战场。"],"tactical":["桂陵控扼魏师南返大梁的咽喉，冈阜隐蔽。孙膑先遣偏师佯攻平陵示弱以骄庞涓之心，使其毫无戒备督疲师兼程南奔；同时指挥齐军主力进驻桂陵高坡构筑伏阵，饱餐蓄锐。待庞涓率饥疲散乱的魏军闯入谷口，孙膑挥旗令正面截堵、两翼包抄；魏武卒力竭阵乱土崩瓦解，庞涓当场被擒，围魏救赵名扬天下。"],"history":"公元前三五三年，魏帅庞涓攻赵都邯郸，齐威王命田忌为将、曾受膑刑的孙膑为军师发兵救赵。孙膑劝阻赴赵硬拼，定围魏救赵之策直趋大梁，诱庞涓急行回救，并于桂陵设伏大破魏军、生擒庞涓。定值：同场三行年份统一取前三五三年。","sources":"史记·孙子吴起列传；孙膑兵法·擒庞涓"},
    "fushi_wangmeng@370": {"strategic":["公元三七〇年秋，前秦全面发动灭燕大战，辅国将军王猛统主力东攻拔取上党壶关，北路偏师围攻前燕并州重镇晋阳却久攻不下。晋阳乃前燕西屏锁钥，由东海王慕容庄凭坚城精兵死守；王猛留下部将监视东线燕军援兵，亲率精锐北驰晋阳督攻。"],"tactical":["晋阳西依悬瓮山、东临汾水，城高粮足，慕容庄据城严防令强攻秦军屡屡受挫。王猛抵营巡视地形后停止仰攻，暗命工兵昼夜向城基之下秘密挖掘地道，以粗木支撑后纵火焚毁支柱；晋阳城墙轰然坍塌出巨大缺口，王猛立遣猛将率敢死精卒潜入斩关纳军，内外夹击生擒慕容庄，并州门户就此洞开。"],"history":"前秦建元六年秋八月，辅国将军王猛统军伐燕攻拔上党壶关，而别将杨安围攻前燕并州重镇晋阳久不能下。九月王猛留屯骑校尉苟苌守壶关监视潞川慕容评援军，亲率精锐北赴晋阳会师杨安，秘凿地道塌城，遣猛将张蚝率壮士由地道潜入城内大呼斩关，内外合击攻克晋阳，生擒前燕并州刺史东海王慕容庄。","sources":"晋书·苻坚载记下"},
    "gen_alaric@402": {"strategic":["公元四〇二年春，西哥特国王亚拉里克趁西罗马帝国北疆空虚，统举族劲旅翻越阿尔卑斯山侵入北意大利，逼得西罗马皇帝弃米兰逃遁。西罗马最高统帅斯提里科星夜自莱茵河调边防军团南下勤王，赶赴北意大利波伦提亚迎击亚拉里克。"],"tactical":["波伦提亚坐落塔纳罗河谷平原，亚拉里克大营环列重车，内藏历年战利与家眷。时值复活节庆典，笃信教规的哥特将士解甲欢庆以为必无战事；斯提里科采盟将奇策，趁节日突遣骑兵与军团猛扑哥特营盘。亚拉里克临危披甲重整铁骑反击稳住战线，但后方车营家眷被斯提里科攻占，被迫订约撤出意大利。"],"history":"公元四〇一年秋西哥特国王亚拉里克乘西罗马北防空虚首次翻越阿尔卑斯山入侵北意大利，进逼西罗马宫廷驻地米兰，迫皇帝霍诺留西逃并转攻阿斯蒂与波伦提亚。公元四〇二年四月六日复活节，西罗马最高统帅斯提里科统莱茵与不列颠援军赶至都灵东南波伦提亚，趁哥特人庆祝复活节突袭决战，夺占哥特大营迫亚拉里克退兵。","sources":"克劳狄安·哥特战记"},
    "gen_alexander_great": {"strategic":["公元前三三四年，马其顿王亚历山大稳固希腊后方后，统精锐渡赫勒斯滂海峡东征波斯。效力波斯的希腊名将门农力劝诸总督焚粮清野，波斯总督们却拒不采纳；敌军集铁骑与门农麾下雇佣步卒扼守格拉尼库斯河，亚历山大闻讯即挥师迎击。"],"tactical":["格拉尼库斯河水急岸陡，波斯诸总督将骑队紧贴东岸排开，反把门农的雇佣步阵留于后坡。亚历山大拒纳待明晨偷渡之议，先遣前锋诱敌，随即亲率伙伴骑队斜涉急流强冲敌阵。陡岸肉搏中亚历山大头盔被劈仍力战破敌，马其顿方阵亦登岸压垮敌骑，继而合围全歼后坡雇佣军；门农仅以身免，小亚细亚门户洞开。"],"history":"公元前三三四年五月，马其顿国王亚历山大渡赫勒斯滂海峡东征波斯。希腊客将门农向波斯诸总督献坚壁清野之策遭拒，波斯军沿格拉尼库斯河陡峭东岸列骑兵于前、雇佣步兵于后。亚历山大不待次日，午后亲率伙伴骑兵斜渡急流肉搏破阵，全歼波斯雇佣军，敞开小亚细亚大门。","sources":"阿里安·亚历山大远征记·第一卷；普鲁塔克·亚历山大传"},
    "gen_alexander_great@-331": {"strategic":["公元前三三一年，亚历山大拔除推罗并收服埃及后挥师东渡两河。波斯王大流士三世倾发各省重骑、战象与镰刀战车，特选辽阔的高加米拉原野铲平地面待战。亚历山大抵阵后断然否决部将夜袭之议，令全军安眠蓄锐，待天明与大流士三世堂堂决战。"],"tactical":["高加米拉旷野无垠，大流士三世战线宽广远超对手。亚历山大布双线空心阵防备合围，亲统伙伴骑队不断向右斜移；波斯左翼急于跟进拦截，与中军拉出豁口，冲阵的镰刀战车亦被让道歼灭。亚历山大结楔形阵直刺缺口猛扑大流士三世本阵；波斯王再度策马北逃，亚历山大旋即回救左翼，一战终结波斯霸业。"],"history":"公元前三三一年十月，收服推罗与埃及的亚历山大东渡两河，与波斯王大流士三世决战于铲平的高加米拉平原。亚历山大拒行夜袭，布双线空心阵防包抄，率右翼斜向机动拉裂波斯防线，随以楔形阵直刺缺口再迫大流士三世败逃，回救左翼击溃波斯主力，终结波斯帝国国运。","sources":"阿里安·亚历山大远征记·第三卷；库尔提乌斯·亚历山大大帝史"},
    "gen_alexander_great@-333": {"strategic":["公元前三三三年秋，马其顿王亚历山大南出奇里乞亚山门；御驾亲征的波斯王大流士三世误认其怯战，竟弃开阔平原翻山插至敌后，占领伊苏斯截断归路。亚历山大喜见波斯军自投狭窄海岸，立令全军星夜北返，直扑大流士三世设防的伊苏斯。"],"tactical":["伊苏斯西临海湾、东靠陡山，皮纳罗斯河横贯其间，大流士三世将大军叠挤于河北岸筑栅固守。亚历山大令副帅守海侧左翼，自领伙伴骑队居靠山右翼。开战后中路方阵涉河受阻，亚历山大亲率铁骑冲垮敌左翼，旋即斜插直扑大流士三世御车；波斯王丧胆弃车逃遁，亚历山大回师合击大破敌军，尽俘波斯王室家眷。"],"history":"公元前三三三年十一月，波斯王大流士三世亲率大军翻越阿马努斯山隘绕至南下马其顿军背后，夺占伊苏斯截断归路，屯兵皮纳罗斯河北岸。亚历山大掉头北返，借狭小海岸抵消波斯兵力优势，亲率右翼伙伴骑兵涉河破敌左翼后直扑大流士三世御车，吓退波斯王并回救左翼大获全胜。","sources":"阿里安·亚历山大远征记·第二卷；普鲁塔克·亚历山大传"},
    "gen_aristides": {"strategic":["公元前四七九年，波斯陆军主力仍留驻希腊，统帅马尔多尼乌斯遣使诱雅典单独媾和以瓦解同盟。雅典将军阿里斯提德严词拒降，敦促斯巴达发兵会师；马尔多尼乌斯遂退入易骑的彼奥提亚平原。阿里斯提德率雅典重步兵会合诸邦联军翻山追击，对峙于普拉提亚。"],"tactical":["普拉提亚南依山麓、北临河原，马尔多尼乌斯据河北筑木寨，纵骑截粮毁泉迫联军夜移营地。天明联军队列脱节，马尔多尼乌斯误认敌军溃逃，挥师渡河猛扑斯巴达军；左翼阿里斯提德驰援途中遭亲波斯的底比斯方阵缠住。激战中斯巴达军阵斩马尔多尼乌斯，阿里斯提德亦击溃底比斯劲旅，合兵攻破波斯木寨。"],"history":"公元前四七九年八月，留驻希腊的波斯统帅马尔多尼乌斯再占雅典后退至普拉提亚寻战，阿里斯提德统雅典重装步兵居希腊联军左翼。波斯骑兵断水截粮迫联军夜撤，马尔多尼乌斯误认联军溃逃渡河猛扑，被斯巴达军击毙；阿里斯提德亦击溃亲波斯的底比斯军，会师攻破波斯木寨，终结波斯侵希。","sources":"希罗多德·历史·第九卷；普鲁塔克·阿里斯提德传"},
    "gen_artaphernes": {"strategic":["公元前四九八年，波斯治下的爱奥尼亚诸邦掀起叛乱。米利都僭主阿里斯塔哥拉斯惧遭吕底亚总督阿尔塔弗涅斯治罪，煽动各城反波斯并引雅典战舰助战。联军自以弗所登陆翻山，出其不意直扑阿尔塔弗涅斯驻守的首府撒狄，企图瘫痪波斯西疆中枢。"],"tactical":["撒狄下城铺展河谷，背靠三面绝壁的撒狄卫城。阿里斯塔哥拉斯一方联军突入下城，阿尔塔弗涅斯临危不乱，收拢精锐退保山顶卫城死守，将敌挡在绝壁下。混战中芦苇民居失火延烧全城，反困联军于火海；阿尔塔弗涅斯乘乱率守军俯冲反击逼退敌军，神庙被焚亦由此埋下希波大战祸根。"],"history":"公元前四九八年春，小亚细亚爱奥尼亚诸城在米利都僭主阿里斯塔哥拉斯策动下反叛波斯，联雅典等援军翻山突袭吕底亚行省首府撒狄。波斯总督阿尔塔弗涅斯退守撒狄卫城顽强抵抗；下城民居失火延烧全城，阿尔塔弗涅斯乘乱反击逼退联军，随后波斯援兵追败希腊人，埋下希波战争导火索。","sources":"希罗多德·历史·第五卷"},
    "gen_brasidas": {"strategic":["公元前四二二年，雅典与斯巴达鏖战日久，色雷斯重镇安菲波利斯的归属令战火重燃。斯巴达名将巴西达斯此前奇袭夺取该城，扼断雅典造船木材与银矿财源；雅典主战派领袖克里昂亲率重装步兵北上收复失地，逼近城郊山岭，巴西达斯收兵入城待机。"],"tactical":["安菲波利斯三面环河、东筑长墙，地势险固。克里昂率军登城东山脊窥探，见城内寂静便令左翼转身撤回海口待援，不意将步卒未持盾的右侧暴露于城门下。巴西达斯窥破战机，亲率精锐推开南门猛冲敌阵中段，副将自北门杀出夹击；雅典军大溃、克里昂被刺死，巴西达斯亦重伤瞑目，两邦旋即议和。"],"history":"公元前四二二年，雅典主战派领袖克里昂率军北上色雷斯，企图夺回斯巴达名将巴西达斯攻占的重镇安菲波利斯。克里昂抵城外山丘侦察后转身撤回埃昂待援，暴露无盾右侧翼；巴西达斯分自两门突击大破雅典军，克里昂被杀，巴西达斯亦重伤殉国，促成尼西阿斯和约。","sources":"修昔底德·伯罗奔尼撒战争史·第五卷"},
    "gen_cambyses": {"strategic":["公元前五二五年，波斯帝国囊括两河与黎凡特，近东唯剩埃及孤悬尼罗河畔。波斯王冈比西斯二世继父志南征，恰逢埃及海疆盟友倒戈、老法老病逝，普萨美提克三世仓促嗣位。冈比西斯二世借阿拉伯驼队供水越过西奈荒漠，水陆并进直扑埃及东境咽喉佩鲁西姆要塞。"],"tactical":["佩鲁西姆要塞扼守尼罗河东支入海要冲，沼泽沙堤环护，普萨美提克三世集埃及军与雇佣步卒于塞外迎战。两军激战肉搏，埃军在波斯步骑与弓矢轮番冲击下防线崩裂，溃退入城。冈比西斯二世合围猛攻，传闻更于阵前驱赶埃及神兽扰乱守军心神，终克佩鲁西姆要塞，打开征服埃及全境之门。"],"history":"公元前五二五年春，波斯国王冈比西斯二世结好阿拉伯部族供水穿越西奈沙漠，在尼罗河三角洲东门户佩鲁西姆要塞击败新立的埃及法老普萨美提克三世，攻克要塞后顺河陷孟菲斯，灭亡埃及第二十六王朝。异说：波利亚努斯载波斯军阵前驱赶猫犬扰乱守军，希罗多德未载此节。","sources":"希罗多德·历史·第三卷；波利亚努斯·战略"},
    "gen_chabrias": {"strategic":["公元前三七六年，雅典组建海上同盟抗衡斯巴达，斯巴达海军统帅波利斯率舰队封锁近海，截击黑海运粮船，令雅典民食告急。雅典推举名将卡布里亚斯统新造舰队出征；卡布里亚斯护送粮船进港后，主动扬帆进攻纳克索斯，逼波利斯赶来海上决战。"],"tactical":["纳克索斯外海水道宽阔，卡布里亚斯见波利斯舰队来援，即登舰迎敌，自居右翼而命副将统左翼。开战后波利斯猛攻雅典左翼令其濒溃；早已击退当面之敌的卡布里亚斯不贪远追，果断横越海面夹击波利斯本阵。斯巴达舰队反胜为败遭受重创，卡布里亚斯战后妥善打捞落水同胞，一战重夺爱琴海制海权。"],"history":"公元前三七六年九月，斯巴达海军统帅波利斯率舰队封锁爱琴海粮道，雅典名将卡布里亚斯率舰队主动围攻纳克索斯岛诱波利斯决战。海战中雅典左翼受挫，卡布里亚斯及时自右翼分舰驰援反败为胜，重夺爱琴海制海权。注：任务表战场标希马鲁塔，史籍通称纳克索斯海战。","sources":"西西里的狄奥多罗斯·历史丛书·第十五卷；色诺芬·希腊史·第五卷"},
    "gen_chabrias@-357": {"strategic":["公元前三五七年，雅典强征军费激起盟邦不满；在卡里亚君主摩索拉斯煽动与战舰援助下，基奥斯等岛脱离雅典掀起同盟战争。雅典急调陆海重兵扑向叛盟核心基奥斯，宿将卡布里亚斯亲率水师封锁海面，欲突入基奥斯港速战速决。"],"tactical":["基奥斯港湾入口狭窄，港内泊满基奥斯及摩索拉斯助战的战舰。交锋打响，卡布里亚斯令座舰当先冲破封锁闯入内港，后续雅典战舰却畏惧拦击迟疑未进，致其孤舰深陷重围。敌舰四面猛撞刺穿船腹，海水灌舱，水手纷纷跳海逃生；卡布里亚斯耻于弃舰，持盾立于甲板力战阵亡，雅典终被迫承认诸盟邦独立。"],"history":"公元前三五七年，基奥斯、罗得岛等邦在卡里亚君主摩索拉斯策动与舰队援助下反叛雅典，掀起同盟战争。雅典老将卡布里亚斯率水师强攻基奥斯港，座舰率先突入港内而友舰未跟进，遭敌舰合击刺穿进水；卡布里亚斯耻于弃舰，力战殉国。定值：敌方定为卡里亚，敌将取摩索拉斯。","sources":"西西里的狄奥多罗斯·历史丛书·第十六卷；科尔奈利乌斯·奈波斯·卡布里亚斯传"},
    "gen_civilis": {"strategic":["公元六九年，罗马帝国深陷争位内战，莱茵河边防精锐多被抽调南下，留守官吏却强征巴塔维部族青壮入伍，民怨沸腾。熟谙罗马军制的巴塔维贵族西维利斯趁乱在莱茵河下游举起义旗，串联日耳曼诸部共抗罗马，进逼下日耳曼统帅霍尔多尼乌斯防区。"],"tactical":["莱茵河下游水道纵横，罗马基地老营孤悬前线。霍尔多尼乌斯年迈多病且军心分裂，麾下士卒猜忌主将毫无斗志。交锋之中，罗马辅助骑兵与舰队纷纷临阵倒戈投向西维利斯；巴塔维与日耳曼勇士乘势猛冲，打得罗马军团溃退入老营要塞闭门苦守。西维利斯水陆合围要塞，起义烈火一度席卷莱茵河防线。"],"history":"公元六九年罗马帝国陷入四帝内战，莱茵河驻军强征巴塔维青年入伍激起民怨。出身巴塔维王族的罗马辅助军军官西维利斯于莱茵河下游举兵起义，联日耳曼诸部击败下日耳曼罗马统帅霍尔多尼乌斯麾下军团，进围老营要塞。定值：战场改定为莱茵河下游要塞老营。","sources":"塔西佗·历史·第四卷"},
    "gen_civilis@70": {"strategic":["公元七〇年，罗马帝国结束内战重归稳定，新皇急遣宿将凯里亚利斯统多个精锐军团翻越阿尔卑斯山北上，全力扑灭莱茵河叛乱。巴塔维起义统帅西维利斯收拢日耳曼盟军，选定曾攻克过的旧塞卡斯特拉韦特拉原野筑坝引水，迎战步步紧逼的凯里亚利斯。"],"tactical":["卡斯特拉韦特拉地势低洼，西维利斯斜筑长坝拦蓄莱茵河水，将阵前原野化作茫茫泥沼。首日罗马军团不知深浅贸然踏入水泽，甲重滑倒者无数，遭巴塔维长矛手涉水猛刺狼狈败退；次日再战西维利斯正占上风，不料逃兵向凯里亚利斯密告侧后干爽浅滩，罗马骑兵悄然绕袭后背，西维利斯腹背受敌被迫北撤。"],"history":"公元七〇年夏，罗马新皇韦斯芗平定内战后，命姻亲名将昆图斯·佩蒂利乌斯·凯里亚利斯统多个精锐军团翻越阿尔卑斯山平定莱茵河叛乱。巴塔维起义领袖西维利斯在已毁的老营即卡斯特拉韦特拉沼泽原野筑坝蓄水，诱罗马军团陷入泥沼血战两日，因逃兵泄密后方浅滩遭罗马骑兵迂回夹击而败退。","sources":"塔西佗·历史"},
    "gen_constantine_great": {"strategic":["公元三一二年秋，罗马帝国四帝争雄烧至意大利本土；高卢统帅君士坦丁率精悍军团越阿尔卑斯山，连拔坚城兵临罗马北郊。割据罗马的皇帝马克森提乌斯已在城内囤粮毁桥，原拟固守拖垮对手；不料他在登基吉日迷信神谕，竟架浮桥率大军渡台伯河出城迎战。"],"tactical":["罗马城北台伯河水深流急，米尔维安石桥已断，马克森提乌斯全军背靠狭窄浮桥列阵，自断生路。君士坦丁命将士在盾牌绘上神圣徽记鼓舞斗志，亲统高卢精骑率先冲垮敌军侧翼骑队，随即压迫步兵侧翼。马克森提乌斯大阵崩溃争抢浮桥逃命，木桥不堪重负断裂，马克森提乌斯坠入台伯河溺亡，君士坦丁凯旋入主罗马。"],"history":"公元三一二年秋，罗马西部皇帝君士坦丁翻越阿尔卑斯山挥师南下，连破北意大利重镇直抵罗马城北。盘踞罗马的敌帝马克森提乌斯本可凭高大城墙与充足粮储固守，却在登基纪念日轻信神谕，率主力出城渡过台伯河背水列阵；君士坦丁挥军猛冲将其击溃，马克森提乌斯争渡坠河溺亡。","sources":"优西比乌·君士坦丁传；拉坦提乌斯·论迫害者之死；佐西姆斯·新史"},
    "gen_constantine_great@324": {"strategic":["公元三二四年夏，分治罗马帝国东西半壁的西部皇帝君士坦丁与东部皇帝李锡尼矛盾彻底破裂，双方倾举国水陆兵力争夺帝国最高独裁权。李锡尼集结东部大军进驻色雷斯交通枢纽阿德里安堡，依山傍河筑起坚固营垒，静待挥师东进的君士坦丁。"],"tactical":["阿德里安堡地处赫布鲁斯河交汇要冲，李锡尼凭宽阔河道与陡坡阻截西军。君士坦丁隔河相持数日，故意命工兵在正面砍木造桥吸住李锡尼视线；暗中却亲统精锐骑步绕至上游隐蔽浅滩涉水过河，猛袭李锡尼侧翼。东部大军阵脚大乱全线崩溃，李锡尼弃营东逃拜占庭，君士坦丁随即一统罗马帝国。"],"history":"公元三二四年夏，罗马西部皇帝君士坦丁与东部皇帝李锡尼因宗教政策与疆域纠纷全面开战。李锡尼集结东部大军依托色雷斯重镇阿德里安堡即埃迪尔内城外河岸高地筑垒设防。七月三日君士坦丁在河畔佯装架桥吸引敌军注意，亲统精锐步骑自隐蔽浅滩涉水绕击李锡尼侧翼，大破东部主力，李锡尼败退拜占庭。","sources":"佐西姆斯·新史"},
    "gen_datis": {"strategic":["公元前四九〇年，波斯平定爱奥尼亚叛乱后，跨海问罪曾助叛军的埃雷特里亚与雅典。米底老将达提斯统舰队与陆师横越爱琴海，连下诸岛并夷平埃雷特里亚，随即引导大军在马拉松海湾抢滩登陆；雅典将军米太亚德急率公民步阵赶来扼守山口。"],"tactical":["马拉松背海面山，南北沼泽夹束，达提斯背靠战船列阵，以波斯与塞种精锐居中、仆从军居两翼。相持数日后，米太亚德乘波斯骑队调离之隙，督雅典重装步兵跑步猛冲。达提斯中军虽击穿敌军单薄中阵，两翼却先溃散，反遭雅典双翼回旋合围；达提斯突围登舰，绕袭雅典未果，遂引军东归。"],"history":"公元前四九〇年夏末，波斯大流士一世命米底将领达提斯统水陆远征军横渡爱琴海，攻陷埃雷特里亚后登陆阿提卡马拉松湾。对峙数日后，雅典将军米太亚德减薄中军、加厚两翼跑步冲阵；达提斯中军虽击穿雅典中阵，两翼却溃败被合围，波斯军抢船撤退，绕航奇袭雅典未果而东归。","sources":"希罗多德·历史·第六卷"},
    "gen_epaminondas": {"strategic":["公元前三七一年，希腊全境和会上，底比斯代表伊巴密浓达拒绝斯巴达解散彼奥提亚同盟的要求，被剔除出和约。斯巴达即命屯兵边境的国王克勒翁布罗图斯一世越境讨伐，欲摧毁底比斯；伊巴密浓达总揽兵权，率公民军赶赴留克特拉迎截。"],"tactical":["留克特拉平原开阔，克勒翁布罗图斯一世依成规置斯巴达精锐于右翼。伊巴密浓达打破两翼均衡传统，把重步卒与圣队叠成超厚纵列集于左翼，直对斯巴达王本阵；同时令中右翼呈斜线后缩避战。底比斯骑兵先驱散敌骑搅乱步阵，伊巴密浓达随率左翼巨锤猛冲压垮敌右翼，阵斩克勒翁布罗图斯一世，终结斯巴达陆霸。"],"history":"公元前三七一年七月，斯巴达王克勒翁布罗图斯一世借和会决裂攻入彼奥提亚，与底比斯统帅伊巴密浓达会战于留克特拉。伊巴密浓达首创斜线阵，将精锐与圣队厚集左翼猛冲斯巴达右翼本阵，右翼梯次后缩牵制，一举击毙克勒翁布罗图斯一世，终结斯巴达陆上霸权。","sources":"色诺芬·希腊史·第六卷；普鲁塔克·佩洛皮达斯传"},
    "gen_epaminondas@-362": {"strategic":["公元前三六二年，伯罗奔尼撒同盟生变，曼丁尼亚倒向斯巴达与雅典。底比斯统帅伊巴密浓达为护多年霸业，统联军南征，奇袭斯巴达城受阻于老王阿格西劳斯二世后，回师曼丁尼亚谷地寻战；阿格西劳斯二世亦会合雅典等盟军列阵迎敌。"],"tactical":["曼丁尼亚谷地两侧高山夹束，阿格西劳斯二世与盟军横贯谷底列阵。伊巴密浓达先引军至山麓佯装卸甲扎营，诱敌解甲松懈；暗中却将精锐叠成厚列集于左翼，以轻步混编骑队护翼。号角骤响，底比斯左翼如战舰破浪般斜冲凿穿斯巴达防线；联军崩溃之际，伊巴密浓达胸中标枪重伤而逝，希腊自此陷入均势。"],"history":"公元前三六二年夏，因阿卡迪亚同盟分裂、曼丁尼亚联结斯巴达与雅典，底比斯统帅伊巴密浓达率联军南下伯罗奔尼撒，与斯巴达王阿格西劳斯二世等联军决战于曼丁尼亚。伊巴密浓达佯装扎营麻痹敌军，骤以加厚左翼破阵击溃联军，但追击中胸中标枪阵亡，希腊陷入均势。定值：敌将取斯巴达王阿格西劳斯二世。","sources":"色诺芬·希腊史·第七卷；西西里的狄奥多罗斯·历史丛书·第十五卷"},
    "gen_hamilcar": {"strategic":["公元前二四四年，罗马共和国与迦太基争夺西西里苦战经年，迦太基在岛上仅余西岸两座海港被围。迦太基名将哈米尔卡为分担友城重压，乘夜率精兵潜航西移；他突夺半山腰的厄律克斯古城，与罗马执政官卡图卢斯所部展开山地相持。"],"tactical":["厄律克斯山孤耸西西里西北滨海，山巅与山脚皆驻罗马军，哈米尔卡楔入半山古城，仅凭海滨险径维系补给。哈米尔卡依石垒顶住上下夹攻，更频率锐卒下山袭扰罗马粮道。直至卡图卢斯建成新舰队击沉迦太基海援船群、彻底断其外援，哈米尔卡方奉命议和，严拒缴械之辱，率不败劲旅持械归国。"],"history":"公元前二四四年，第一次布匿战争后期，迦太基名将哈米尔卡乘夜跨海奇袭夺取西西里西端厄律克斯山腰古城，夹在山顶与山脚罗马军之间坚守三载牵制敌主力。直至前二四一年罗马执政官卡图卢斯于海战切断海援，哈米尔卡方奉命持械体面议和归国。定值：年份取前二四四年、敌将取卡图卢斯。","sources":"波利比乌斯·通史·第一卷；西西里的狄奥多罗斯·历史丛书·第二十四卷"},
    "gen_hamilcar@-240": {"strategic":["公元前二四〇年，刚与罗马议和的迦太基爆发雇佣兵与利比亚诸城大叛乱。叛帅斯彭迪乌斯围困北方重港，重兵扼死地峡咽喉与巴格拉达斯河唯一石桥，困死都城陆路；危亡之际迦太基重召名将哈米尔卡统公民军与新训战象出击，直趋巴格拉达斯河。"],"tactical":["巴格拉达斯河水深泥软，斯彭迪乌斯重兵扼守孤桥。哈米尔卡查明海上强东风能顶退潮水露出河口水下暗沙，遂乘黑夜大风率军衔枚涉沙渡河，突现敌后。斯彭迪乌斯大惊，急调两路叛军合击；哈米尔卡故意后撤战象轻骑示弱诱敌散乱猛追，随令方阵骤然转身结墙、象骑两翼反扑，一举击溃斯彭迪乌斯夺回河桥。"],"history":"公元前二四〇年，迦太基战后欠饷引发利比亚诸城与雇佣兵大起义，叛帅斯彭迪乌斯封锁地峡并重兵扼守巴格拉达斯河唯一石桥。哈米尔卡乘强东风吹退河口潮水露出暗沙，夜率公民军与战象涉河口奇出敌后，再以佯退反冲大破斯彭迪乌斯两路夹击之军，扭转危局。定值：敌将取斯彭迪乌斯。","sources":"波利比乌斯·通史·第一卷"},
    "gen_hannibal": {"strategic":["公元前二一六年，迦太基统帅汉尼拔翻越阿尔卑斯山入意大利连败罗马军，乘势夺占阿普利亚粮仓坎尼。罗马共和国摒弃拖延方略，命执政官瓦罗与同僚征集空前规模的大军南下寻战；汉尼拔兵力居劣却胸有成竹，在坎尼平原布阵迎候瓦罗。"],"tactical":["坎尼平原紧傍河岸，瓦罗掌印当日将罗马重步兵排成密集纵深猛压中路。汉尼拔逆势布下新月凸阵，以伊比利亚与高卢步卒居中边战边退，将贪功猛进的罗马步阵深深吸入凹袋；同时迦太基铁骑击溃敌两翼骑兵，回身与精锐利比亚重步兵四面合拢。瓦罗大军陷入铁围覆没，此战遂成包围歼灭之千古范本。"],"history":"公元前二一六年八月，横行意大利的迦太基名将汉尼拔夺占阿普利亚粮仓坎尼诱敌决战，罗马执政官瓦罗与同僚统空前大军来攻。轮值瓦罗掌印之日，汉尼拔布新月凸阵，中军步步后撤诱敌深入，利比亚重步兵与优势铁骑自两翼及背后合围，全歼罗马主力，创包围歼灭战典范。","sources":"波利比乌斯·通史·第三卷；李维·自建城以来·第二十二卷"},
    "gen_hannibal@-202": {"strategic":["公元前二〇二年，罗马青年统帅西庇阿跨海登陆北非连破城邑，并拉拢努米底亚骑兵倒戈，迦太基危在旦夕。纵横意大利十余载未尝败绩的汉尼拔奉召班师护国，两代名将于扎马原野阵前会晤议和破裂，遂列阵展开决定地中海霸权的终极对决。"],"tactical":["扎马原野开阔平缓，无险可守。汉尼拔将战象置于阵前，步卒分三线梯次配置，把百战老兵留作决胜主力；西庇阿则留出阵间宽道，鸣响号角惊散冲阵战象，并以优势骑兵率先驱散迦太基两翼骑队。两军老兵中坚浴血肉搏难解难分之际，西庇阿骑兵回师猛插汉尼拔后背，迦太基大阵崩溃，被迫屈辱求和。"],"history":"公元前二〇二年十月，因罗马青年统帅大西庇阿跨海远征北非连败迦太基军并争取努米底亚王马西尼萨倒戈，转战意大利十五载未尝一败的汉尼拔奉召归国救亡。两代名将在扎马原野会面议和无果后展开终极决战；西庇阿留出宽阔通道加号角声化解汉尼拔战象群冲击，汉尼拔三线布阵令新老三排步卒鏖战难解，最终罗马与努米底亚骑兵击溃敌骑回抄汉尼拔后背，迦太基战败求和。","sources":"波利比乌斯·通史·第十五卷；李维·自建城以来·第三十卷"},
    "gen_hannibal@-218": {"strategic":["公元前二一八年冬，迦太基统帅汉尼拔翻越冰雪覆盖的阿尔卑斯山奇袭北意大利，初战挫伤罗马执政官。罗马共和国急调另一执政官塞姆普罗尼乌斯自西西里率军团北援；汉尼拔摸准对手急躁贪功心性，在特雷比亚河畔设局诱战。"],"tactical":["特雷比亚河冬日冰水刺骨，两岸草木丛生、沟壑隐蔽。汉尼拔乘夜遣精兵埋伏于河岸荆棘深沟，拂晓派努米底亚轻骑渡河搦战佯退；塞姆普罗尼乌斯不待士卒饱食，便督罗马军团冒风雪涉冰河猛追。待冻馁交加的罗马步阵陷入苦战，汉尼拔挥战象两翼压上，伏兵骤起猛刺敌背，塞姆普罗尼乌斯全军惨败溃逃。"],"history":"公元前二一八年十二月冬至前后，翻越阿尔卑斯山进入北意大利波河平原的汉尼拔在提契诺河骑战伤罗马执政官西庇阿后，迎战自西西里赶来会合的另一执政官塞姆普罗尼乌斯。汉尼拔预先命幼弟马戈率精兵埋伏于河岸荆棘沟谷，拂晓派努米底亚轻骑诱空腹受冻的罗马军涉过冰冷刺骨的特雷比亚河，前后夹击大破塞姆普罗尼乌斯大军。","sources":"波利比乌斯·通史·第三卷；李维·自建城以来·第二十一卷"},
    "gen_julian_apostate@363": {"strategic":["公元三六三年春，罗马帝国皇帝尤里安怀抱追步亚历山大的雄心，拒绝议和，亲统大军与内河船队沿幼发拉底河大举南侵萨珊波斯。罗马军挖通古运河驶入底格里斯河，兵临波斯君主沙普尔二世的都城泰西封城下，震动两河腹地。"],"tactical":["泰西封雄踞底格里斯河东岸，波斯守军依托陡峭河岸，列开披甲重骑与战象封锁渡口，静候沙普尔二世主力回援。尤里安乘夜命先锋冒箭雨强渡激流抢滩，天明全军渡河迎战；罗马军团以严密枪盾阵正面冲垮波斯重骑战象，一路追杀直抵泰西封城门之下，后因孤军难拔坚城且沙普尔二世大军逼近方转道北撤。"],"history":"公元三六三年春，独掌罗马帝国皇位的尤里安效法亚历山大东征伟业，统大军并内河庞大舰队沿幼发拉底河南侵萨珊波斯，疏通古运河驶入底格里斯河直抵萨珊首都泰西封即今巴格达南郊。五月二十九日尤里安冒死乘夜抢渡底格里斯河，在泰西封城门外正面击溃波斯统帅斯帕赫巴德所统战象与重骑大阵，震动萨珊王廷。","sources":"阿米阿努斯·马尔切利努斯·罗马史"},
    "gen_julius_caesar": {"strategic":["公元前五二年，高卢阿维尔尼首领维钦托利掀起全境大起义，欲将罗马逐出高卢。罗马总督恺撒翻越雪山平叛，在骑战挫敌后，将维钦托利主力追困至山顶坚城阿莱西亚；全高卢援军亦四面赶来，胜负在此一举。"],"tactical":["阿莱西亚山势险峻难于强攻，恺撒命军团环城修筑对内封锁、对外迎敌的双重壁垒，遍布拒马暗桩与深壕。总攻之日维钦托利与城外高卢援军内外猛扑西北薄弱山坡，防线岌岌可危；恺撒身披醒目红袍亲临督战，暗遣骑队绕出外垒猛袭援军后背，一举击溃外援迫降维钦托利，高卢全境自此归入罗马。"],"history":"公元前五二年九月，罗马高卢总督恺撒追围高卢盟主维钦托利主力于山城阿莱西亚。面对城中守军与赶来的全高卢浩大援军，恺撒修筑对内封锁、对外防御的双重环形壁垒并遍设陷阱；决战日恺撒身披红袍率骑兵抄袭高卢援军后背大获全胜，迫维钦托利出降，彻底征服高卢。定值：敌方定为阿维尔尼。","sources":"恺撒·高卢战记·第七卷；普鲁塔克·恺撒传"},
    "gen_julius_caesar@-47": {"strategic":["公元前四七年，趁罗马深陷内战，本都故王之子法尔纳克二世自黑海北岸挥师南侵，重占本都并残杀罗马公民，击败留守罗马部将。刚平定埃及战局的恺撒闻警毫不迟疑，仅携精悍老兵自叙利亚昼夜兼程北上，直扑法尔纳克二世屯兵的泽拉。"],"tactical":["泽拉山冈对峙，中间隔着深陡山谷，正是昔日本都先王破罗马军之地。恺撒乘夜抢占高坡筑垒；法尔纳克二世迷信故地祥瑞，竟狂妄驱镰刀战车与步阵下谷仰攻陡坡。罗马军初遭突袭略乱，恺撒从容整队，借高坡之势挥老兵居高反冲；瞬息将本都大军碾入谷底全线击溃，恺撒遂写下我来我见我征服的千古捷报。"],"history":"公元前四七年夏，密特里达梯六世之子、博斯普鲁斯兼本都国王法尔纳克二世趁罗马内战重占本都，阉割罗马公民并在尼科波利斯击败恺撒部将。刚平定埃及亚历山大港战事的恺撒仅携老兵第六军团等轻兵神速北上泽拉抢占高地筑营；法尔纳克二世迷信昔日乃父在此胜地之运，竟驱镰刀战车下谷仰攻陡坡罗马军，恺撒居高反冲瞬息大破本都军，捷报仅书我来我见我征服三词。","sources":"亚历山大港战记；普鲁塔克·恺撒传；苏维托尼乌斯·神圣朱利乌斯传"},
    "gen_julius_caesar@-48": {"strategic":["公元前四八年，跨过卢比孔河掀起内战的恺撒在海岸受挫断粮后，果断引军东进色萨利腹地就粮，迫使元老院统帅庞培脱离舰队补给追来。面对兵力占优、骑兵更呈压倒之势的庞培大军，恺撒激励久经百战的老兵，在法萨卢斯原野布阵迎敌。"],"tactical":["法萨卢斯原野平坦开阔，极利庞培优势骑兵在侧翼迂回。恺撒看穿庞培左翼包抄企图，暗抽精干步兵斜列于右翼后方，严令将士双手端重标枪专刺敌骑脸面。庞培骑兵冲入圈套骤遭迎头猛刺，惊恐溃逃；恺撒趁势挥第四线反包敌左翼，再投入第三线生力军全线推进，一举击溃庞培大军，奠定罗马独裁霸业。"],"history":"公元前四八年八月九日，渡卢比孔河掀起内战的恺撒在都拉基乌姆失利后东进色萨利就粮，诱使庞培放弃困敌方略在法萨卢斯平原决战。面对兵力倍增尤其是骑兵占绝对优势的庞培大阵，恺撒从三线军团中秘密抽调精锐大队在右翼后方斜向布成第四线，严令将士双手端重标枪专刺庞培贵族骑兵面门；一举惊溃敌骑反包庞培左翼，再投第三线生力军全线压垮元老院大军，奠定独裁霸业。","sources":"恺撒·内战记·第三卷；普鲁塔克·恺撒传"},
    "gen_li_xin": {"strategic":["公元前二二五年，秦灭三晋后矛头南指大国楚国。廷议时宿将力主倾国重兵，新立衍水奇功的少壮将领李信却豪言仅凭轻装锐卒便足平楚；秦王大悦拜李信挂帅南征。李信连拔平舆、横扫鄢郢，意气风发调头东趋城父会师，浑然不觉楚帅项燕已尾随其后。"],"tactical":["城父平畴水网交错，远离秦境补给。李信因初战顺遂滋生骄心，只顾催军奔袭赶往城父，未防侧后亦未固垒。岂料项燕敛锋紧随其后三日三夜不息，趁秦师抵城父近郊人困马乏、安营未定之际，骤然全线猛扑。楚军以逸击劳连破秦军大营、斩杀诸都尉，李信率残部奔还请罪，秦王遂改请老帅倾国伐楚。"],"history":"公元前二二五年，秦廷议伐楚，少壮名将李信自请轻兵破楚，秦王拜李信为主将与蒙恬分路南征。李信初破平舆、西克鄢郢，引兵东趋城父会师途中，遭楚大将项燕尾随三日三夜突袭，连失大营、折损诸都尉而大败奔还；秦王遂亲请王翦复出灭楚。","sources":"史记·白起王翦列传；资治通鉴·秦纪一"},
    "gen_li_xin@-226": {"strategic":["公元前二二六年，因燕国太子丹遣荆轲入咸阳行刺未遂，秦廷震怒增兵攻破燕都蓟城；燕王与太子丹收拢残存精锐向东北退往辽东，欲凭山海远险苟延残喘。随军北征的秦国少壮猛将李信主动请缨，精选轻装锐骑脱离大军辎重，顶寒风跨辽西疾追太子丹直扑衍水。"],"tactical":["衍水奔流于辽东山原之间，冰寒苇密，太子丹统东撤主力依水设防，以为秦军刚克蓟城断难速至。不料李信善长途奔袭，率轻骑昼夜换马疾驰，骤抵衍水岸边，不等燕军固垒便迎面猛冲。燕军防线顷刻崩裂，太子丹败匿河洲；辽东门户洞开，惊惧的燕王搜斩太子丹献首乞和，李信携奇功凯旋咸阳。"],"history":"公元前二二七年燕太子丹遣荆轲刺秦王未遂，次年十月秦军攻拔燕都蓟城，燕王喜与太子丹率残部精兵东走辽东。秦少壮将领李信率精锐轻骑跨辽西走廊穷追，于辽东衍水大破太子丹殿后主力，逼燕王喜斩太子丹献首乞和，李信由此名震秦廷。定值：敌将取太子丹。","sources":"史记·白起王翦列传；史记·刺客列传；资治通鉴"},
    "gen_lysander": {"strategic":["公元前四〇五年，伯罗奔尼撒战争进入决胜关头。斯巴达统帅吕山德借波斯财力重建舰队，乘虚攻占海峡重镇兰普萨库斯，掐断雅典黑海粮道；雅典将领科农等倾最后家底率舰队追入海峡，泊于对岸荒僻的羊河滩头，急欲逼吕山德决战。"],"tactical":["羊河河口仅为开阔沙石滩涂，无港无粮。科农等连日横渡海峡列阵邀战，吕山德令全军披甲登船却拒不出港，待敌返航后派快船尾随侦察。数日后雅典将士骄怠，收兵回滩便任水手散入内陆觅食；吕山德见侦察船举铜盾反光传讯，立挥全舰队疾渡突袭空滩，尽俘敌舰，唯科农乘快舰突围，雅典自此绝粮倾覆。"],"history":"公元前四〇五年秋，斯巴达统帅吕山德攻占赫勒斯滂海峡重镇兰普萨库斯以断雅典黑海粮道，雅典将领科农等率舰队泊于对岸无港口的羊河海滩。吕山德连日坚拒邀战麻痹敌军，第五日趁雅典水手离船登岸觅食，率全舰队闪电横渡突袭，几乎全歼雅典海军，科农仅率少数快舰逃往塞浦路斯。","sources":"色诺芬·希腊史·第二卷；普鲁塔克·吕山德传"},
    "gen_lysander@-395": {"strategic":["公元前三九五年，斯巴达战后专横激起诸邦公愤，底比斯领袖伊斯梅尼亚斯借波斯资助联雅典抗命。名将吕山德力劝斯巴达发兵，定南北两路合击之策；吕山德先行北赴福基斯纠集盟军，按期进抵要冲哈利亚托斯城外，准备会攻伊斯梅尼亚斯一方。"],"tactical":["哈利亚托斯地处湖岸山麓要道。吕山德抵城下久候南路援军不至，不知信使已被截获，遂轻率领军逼近城墙试图劝降强攻。岂料伊斯梅尼亚斯一方的底比斯先头部队已入城设防，城外援军又自山后疾驰杀到；城门骤开，底比斯步骑内外夹击未及成阵的斯巴达军，吕山德混战阵亡，科林斯战争全面爆发。"],"history":"公元前三九五年，底比斯领袖伊斯梅尼亚斯联雅典挑起科林斯战争。斯巴达定南北夹击之策，吕山德率北路联军先抵哈利亚托斯，因联络信使被截，未等南路斯巴达王赶到便逼近城墙，遭城内守军与赶来的底比斯主力前后夹击阵亡。定值：敌将估算取底比斯主战领袖伊斯梅尼亚斯。","sources":"色诺芬·希腊史·第三卷；普鲁塔克·吕山德传"},
    "gen_lysander@-406": {"strategic":["公元前四〇六年，斯巴达命善谋的吕山德执掌海军驻节以弗所，结好波斯王子提高军饷以招徕熟练桨手。雅典统帅亚西比德进驻对岸诺提姆海角监视，因筹饷暂赴外地，严令留守舵手安提奥库斯不得主动求战；吕山德闭港整训，静待敌军破绽。"],"tactical":["诺提姆海角与以弗所隔湾相望。贪功的安提奥库斯违背禁令，驾座舰率快船划至以弗所港嘴叫阵诱敌；吕山德看穿其孤进，先遣快舰扑出撞沉安提奥库斯座舰并将其击毙。见其余雅典战舰未及编队便零散来救，吕山德立挥全舰队整列迎击，重挫敌军；雅典由此迁怒罢免亚西比德，自毁海上栋梁。"],"history":"公元前四〇六年春，斯巴达海军统帅吕山德驻节以弗所，借波斯增饷厚募水手，与驻诺提姆海角的雅典舰队对峙。雅典主帅亚西比德暂离前线并严令代理指挥安提奥库斯不得出战，安提奥库斯违命赴港前诱敌；吕山德精准反击击沉其座舰并击败赶来的雅典舰群，致使亚西比德遭罢黜。定值：敌将取安提奥库斯。","sources":"色诺芬·希腊史·第一卷；普鲁塔克·吕山德传"},
    "gen_miltiades": {"strategic":["公元前四九〇年，波斯统帅达提斯攻灭埃雷特里亚后横渡海峡，登陆马拉松平原，雅典面临灭顶之灾。斯巴达援军囿于月圆之忌未发，仅有普拉提亚倾城来助。熟知波斯战法的将军米太亚德力排畏战之议，说服执政官主战，率希腊方阵进驻山麓封死要道。"],"tactical":["马拉松平原东临海湾、西倚群山，米太亚德据山坡扎营以避波斯骑锋。及至轮掌帅印之日，侦知达提斯分调骑队，米太亚德果断削薄中军、厚集两翼与敌等宽，令重甲公民疾奔穿过箭雨猛撞敌阵。雅典中军虽退，厚重的两翼却撕碎敌翼并向内合围波斯中坚；米太亚德破敌后急行回防雅典，逼退达提斯舰队。"],"history":"公元前四九〇年九月，波斯统帅达提斯率远征军登陆马拉松平原，雅典诸将战和不一，熟谙波斯战法的将军米太亚德力主出城迎敌，与普拉提亚盟军据山扼守。轮值主帅之日，米太亚德减薄中军、厚集两翼疾奔冲锋，两翼包抄击溃波斯军，随后强行军回防雅典逼退波斯舰队。","sources":"希罗多德·历史·第六卷；科尔奈利乌斯·奈波斯·米太亚德传"},
    "gen_parmenion": {"strategic":["公元前三三四年，马其顿大举东征波斯，辅佐两代君主的老帅帕曼纽此前已率前遣军在小亚细亚立足，主力渡海会师后出任全军副帅。波斯诸总督拒纳客将门农清野退守之策，纠集铁骑与门农所部雇佣步卒重防格拉尼库斯河渡口，帕曼纽遂辅佐国王整军东进。"],"tactical":["格拉尼库斯河底多乱石、东岸高耸泥泞，波斯骑队密布河沿，门农雇佣步卒列于后岗。帕曼纽审视地势进言次日破晓济河，国王决意即日强攻，命帕曼纽统左翼色萨利铁骑与左部方阵。开战后右翼猛攻吸引敌主力，帕曼纽沉着调度色萨利骑队结菱形阵涉急流抢登东岸，压垮当面敌骑，配合右翼合歼雇佣步阵，旗开得胜。"],"history":"公元前三三四年五月，马其顿元勋老帅帕曼纽以全军副帅随亚历山大渡海伐波斯。格拉尼库斯河畔对阵波斯诸总督与门农时，帕曼纽建议次日拂晓济河未果，受命统率全军左翼色萨利及盟邦骑步兵涉水强攻，稳健压制波斯右翼，配合右翼合击大破波斯军。","sources":"阿里安·亚历山大远征记·第一卷；西西里的狄奥多罗斯·历史丛书·第十七卷"},
    "gen_parmenion@-331": {"strategic":["公元前三三一年秋，马其顿远征军渡过底格里斯河，在高加米拉原野迎来与波斯王大流士三世的总决战。年近七旬的副帅帕曼纽俯瞰无边波斯营火，进言夜袭未获采纳；天明列阵，帕曼纽披甲登上左翼帅位，在无遮无拦的平畴上独迎波斯右翼铁骑洪流。"],"tactical":["高加米拉尘土蔽日，随右翼右移寻机，帕曼纽左翼独自承受大流士三世右翼重骑正面与侧包的双重猛压；更有敌骑乘方阵脱节穿插劫掠后营。老帅帕曼纽临危不乱，调预备步卒回清后营并遣骑告急，亲率色萨利铁骑浴血死守防线；直至波斯王败逃、右翼回援合击破敌，写就戎马生涯最后辉煌。"],"history":"公元前三三一年十月高加米拉决战前夜，老帅帕曼纽虑敌众建议夜袭未果。决战日帕曼纽统率马其顿左翼，独抗波斯右翼优势重骑包抄及敌骑穿阵劫营之乱；年届七旬的帕曼纽浴血苦撑并遣骑告急，稳住左翼直至右翼击败大流士三世后回援合击破敌。","sources":"阿里安·亚历山大远征记·第三卷；普鲁塔克·亚历山大传"},
    "gen_parmenion@-333": {"strategic":["公元前三三三年深秋，波斯王大流士三世率王师翻越北山插至马其顿后方重镇伊苏斯，截断远征军退路。前锋老帅帕曼纽急与北返主力会合，进抵伊苏斯滨海走廊；国王自领右翼，把紧贴大海、直面波斯主力铁骑的左翼重任托付给宿将帕曼纽。"],"tactical":["伊苏斯海滩逼仄，大流士三世因山麓难展马队，将披甲重骑尽调临海右翼猛扑马其顿左翼。帕曼纽严守紧贴海浪不留空隙之令，沉着调度色萨利铁骑反复反冲；左翼步骑寸土不让，硬将汹涌波斯骑潮死死钉在海滩。待右翼吓走大流士三世，敌骑惊溃，帕曼纽当即挥骑追杀，铸就稳如泰山的铁砧之功。"],"history":"公元前三三三年十一月伊苏斯会战中，波斯王大流士三世将精锐重骑集中于临海右翼，企图踏碎马其顿左翼。马其顿副帅帕曼纽统率左翼紧贴海岸列阵，督色萨利与盟邦骑兵顶住优势波斯铁骑轮番猛冲，稳作全军铁砧，直至右翼击走大流士三世回师夹击，共创大捷。","sources":"阿里安·亚历山大远征记·第二卷；西西里的狄奥多罗斯·历史丛书·第十七卷"},
    "gen_philip_ii": {"strategic":["公元前三三八年，马其顿王腓力二世练成强悍方阵与骑队，借调停神庙纷争越温泉关南下，进占中希腊咽喉。面对征服危机，雅典与底比斯捐弃前嫌结盟；底比斯猛将特阿格尼斯统圣队会合联军封锁喀罗尼亚平原，腓力二世遂挥师迎上决战。"],"tactical":["喀罗尼亚平原北临河泽、南倚高丘，联军左翼雅典兵靠山，右翼特阿格尼斯统底比斯军贴河严守。腓力二世坐镇右翼，看准雅典兵急躁贪功，故意整队后退；雅典兵果真盲追，致联军防线豁开缺口。马其顿左翼骑队乘隙刺入包抄底比斯侧背，腓力二世亦反冲溃雅典军；特阿格尼斯率圣队死战殉国，希腊诸邦尽皆俯首。"],"history":"公元前三三八年八月，马其顿王腓力二世率军南下中希腊，雅典与宿敌底比斯结盟迎抗，底比斯名将特阿格尼斯统圣队居联军右翼。决战于喀罗尼亚平原时，腓力二世右翼佯退诱雅典左翼脱节，王子亚历山大乘隙突破缺口，合围全歼特阿格尼斯所率底比斯圣队，确立马其顿全希腊霸权。","sources":"西西里的狄奥多罗斯·历史丛书·第十六卷；普鲁塔克·亚历山大传"},
    "gen_philip_ii@-352": {"strategic":["公元前三五二年，福基斯统帅奥诺马库斯强占德尔斐神庙熔金募兵，北上介入色萨利战事，前一年曾凭石弩两挫马其顿王腓力二世。腓力二世退归蓄力后重整南下，团结色萨利诸邦进逼帕加塞海港，迫使北救的奥诺马库斯在番红花原决战。"],"tactical":["番红花原紧邻帕加塞海湾，原野平阔。腓力二世命全军头戴象征神罚的月桂冠列阵，以长矛方阵正面咬住敌阵，同时投入伙伴骑队与色萨利铁骑猛击两翼。优势铁骑迅速撕碎敌翼席卷后背，奥诺马库斯麾下雇佣军崩溃，争相弃甲跳海游向外海盟舰；奥诺马库斯溺亡海中，马其顿自此执掌色萨利。"],"history":"公元前三五二年，第三次神圣战争中，福基斯统帅奥诺马库斯熔德尔斐神庙金银募军，前一年曾两败马其顿王腓力二世。腓力二世重整再入色萨利，命全军头戴阿波罗月桂冠，会合色萨利骑兵在帕加塞湾畔番红花原包抄击溃福基斯军，奥诺马库斯投海溺亡，腓力二世遂掌色萨利霸权。","sources":"西西里的狄奥多罗斯·历史丛书·第十六卷；查士丁·腓力史概要"},
    "gen_seleucus_i": {"strategic":["公元前三〇一年，老对手安提柯一世企图独吞亚历山大遗产，西方盟友向东方国王塞琉古紧急求援。塞琉古果断与印度孔雀王朝缔约，换回庞大印度战象群，冒严寒穿越高原与盟军会合于伊普苏斯平原，同安提柯一世主力展开决战。"],"tactical":["伊普苏斯原野无遮无拦，塞琉古与盟军并列方阵，将大批机动战象与东方轻骑留作预备杀招。交锋未久，敌右翼重骑冲退联军左翼后策马远追；塞琉古精准抓住空隙，挥战象群横切入场，惊骇敌马使其无法回救。紧接着塞琉古令弓骑环绕失翼的敌方阵反复驰射动摇军心，终在乱箭中击毙安提柯一世，尽收叙利亚膏腴之地。"],"history":"公元前三〇一年，东方国王塞琉古与印度孔雀王朝议和换得大批战象后，西进小亚细亚会合盟友利西马科斯，于伊普苏斯平原决战安提柯一世父子。塞琉古调度战象群横截战场隔断敌父子联系，再以轻骑环射瓦解敌本阵，击毙安提柯一世，尽收叙利亚疆土。","sources":"普鲁塔克·德米特里传；阿庇安·叙利亚战记"},
    "gen_seleucus_i@-281": {"strategic":["公元前二八一年，亚历山大诸继业者仅剩东方霸主塞琉古与兼领色雷斯、马其顿的利西马科斯两位白发老王在世。因利西马科斯听谗冤杀贤明王储，小亚细亚重镇纷纷叛投东方；塞琉古见一统旧疆良机降临，统军西越山脉直入吕底亚，与利西马科斯对决于库鲁佩迪安。"],"tactical":["库鲁佩迪安平原寒风凛冽，两位年逾古稀的马其顿宿将各自披挂，统同源长矛方阵与铁骑正面相撞。利西马科斯麾下因王储冤死而人心离散，在塞琉古挟大义之师与战象精骑猛冲下防线迅速崩解。利西马科斯虽挥剑死战不退，终在乱军中被标枪刺穿胸膛倒毙沙场；塞琉古一举囊括小亚细亚，为继业者混战时代画上句号。"],"history":"公元前二八一年二月，亚历山大最后两位在世老帅塞琉古与色雷斯兼马其顿王利西马科斯决战。因利西马科斯听谗杀害贤长子，小亚细亚诸城纷纷叛投塞琉古；塞琉古率军西入吕底亚，在库鲁佩迪安平原击败并击杀利西马科斯，赢下继业者时代终章之战。定值：敌将取利西马科斯。","sources":"阿庇安·叙利亚战记；查士丁·腓力史概要·第十七卷"},
    "gen_seleucus_i@-309": {"strategic":["公元前三〇九年，重返巴比伦复国的塞琉古收复米底与苏萨；西亚霸主安提柯一世震怒，亲统主力杀回两河，双方围绕巴比伦苦战累年。盛夏两军主力再度对垒于巴比伦郊野，首日血战至暮难分高下，决定东方归属的奇谋在夜色中悄然酝酿。"],"tactical":["巴比伦郊野河网纵横、白昼酷热，首日罢战后安提柯一世麾下士卒疲惫卸甲酣睡。塞琉古深知正面难胜强敌，暗令全军披甲执兵就地假寐，夜半悄然饱餐列队；趁破晓晨雾未散，塞琉古率精兵无声逼近敌营，抵门骤然呐喊猛冲。敌卒赤身惊醒措手不及，全营大溃；安提柯一世狼狈西撤，塞琉古自此稳掌东方疆土。"],"history":"塞琉古自埃及率轻骑重返巴比伦复国，引发与西亚霸主安提柯一世长达三年的巴比伦战争。双方拉锯至公元前三〇九年夏，塞琉古在巴比伦郊野决战中命士卒夜间带甲假寐，黎明前突然猛扑尚未披甲的敌军大营，大败安提柯一世，迫其放弃东方诸省，奠定塞琉古帝国基业。","sources":"巴比伦继业者编年史；波利亚努斯·战略·第四卷"},
    "gen_themistocles": {"strategic":["公元前四八〇年，波斯水陆大军越海峡南下侵希，北希腊望风归附。雅典将领地米斯托克利早年力主用银矿收益大造战舰，此时更谦让海军名义帅位以团结诸邦。依水陆联防之策，陆军守温泉关，地米斯托克利则率联合舰队进驻阿尔特米西昂，迎堵阿凯门尼斯的波斯舰队。"],"tactical":["阿尔特米西昂扼优卑亚岛北端水道，风急礁多。阿凯门尼斯所在的波斯舰队规模占优，并遣分舰队绕航外海包抄。地米斯托克利稳住军心，先结环形阵诱敌围拢再四向猛撞重创敌舰，当夜风暴又摧毁波斯绕航船队；次日波斯排半月阵强攻，双方浴血平分秋色。闻温泉关失陷，地米斯托克利遂有序南撤保存主力。"],"history":"公元前四八〇年夏末，波斯水陆大军侵希，雅典领袖地米斯托克利率希腊联合舰队配合温泉关陆军，扼守优卑亚岛北端阿尔特米西昂水道，与阿凯门尼斯等统率的波斯舰队连日激战。波斯绕航分舰队遇风暴覆没，正面海战互有损伤；因温泉关失守，地米斯托克利率舰队有序南撤萨拉米斯。定值：战场定为阿尔特米西昂。","sources":"希罗多德·历史·第八卷；普鲁塔克·地米斯托克利传"},
    "gen_themistocles@-480": {"strategic":["公元前四八〇年秋，波斯王薛西斯一世突破温泉关焚毁雅典空城，退泊萨拉米斯岛的盟邦诸将惊惶欲撤往地峡。雅典统帅地米斯托克利深知退入外海必遭吞没，力逼盟军留守；他又暗遣家仆向薛西斯一世诈报希腊人内讧将逃，诱波斯舰队连夜驶入萨拉米斯海峡。"],"tactical":["萨拉米斯海峡曲折逼仄，薛西斯一世登山观战，波斯水手连夜封锁出口疲惫不堪。天明后地米斯托克利令战舰佯退，引敌深入最窄湾口；待晨风掀浪使笨重的波斯船群摇晃纠缠，希腊灵巧战舰乘风猛冲，以铜角撞碎敌船侧舷。波斯前舰欲退而后舰前挤，全军惨败，薛西斯一世被迫率主力退回小亚细亚。"],"history":"公元前四八〇年九月，温泉关失陷、雅典被焚后，希腊联合舰队退集萨拉米斯海峡。盟邦诸将欲退守科林斯地峡，雅典统帅地米斯托克利力争留战，密遣仆人向波斯王薛西斯一世诈报希腊人将逃，诱波斯舰队连夜驶入狭窄水道，天明借涌风与地形大破波斯海军，扭转希波战局。","sources":"希罗多德·历史·第八卷；埃斯库罗斯·波斯人"},
    "guangwu_xinwuxian": {"strategic":["公元前六一年，河湟先零与罕开诸羌冰释前嫌结盟寇边，渡湟水威逼汉朝金城塞防。酒泉太守辛武贤慷慨上书，主张趁盛夏水草丰美发河西精骑分道直击罕开羌腹地，夺其畜产以寒敌胆；汉廷拜辛武贤为破羌将军，驰赴金城允吾前线督师。"],"tactical":["允吾控扼湟水与大河交汇河谷，乃进兵诸羌枢纽。辛武贤抵营后虽与老帅方略相异，及奉诏并进讨羌，即率酒泉敦煌精锐轻骑昼夜疾进；汉军以凌厉兵威压迫罕开牧地，并宣朝廷宽赦招抚之恩。罕开羌首领靡忘慑于锋芒率部归降，获封还故地；诸羌同盟就此瓦解，河湟边患顺遂平息。"],"history":"公元前六一年，河湟先零羌与罕开诸羌解仇结盟犯汉边塞，酒泉太守辛武贤上书力主盛夏分道出击罕开羌夺其畜产，获汉宣帝拜为破羌将军。辛武贤进驻金城允吾，后奉诏率轻骑与赵充国子赵卬等并进，攻威结合招抚迫使罕开羌首领靡忘率众归附，瓦解诸羌同盟。","sources":"汉书·赵充国辛庆忌传；资治通鉴·汉纪十八"},
    "guyashu_shamushi": {"strategic":["约公元前一七九六年，两河流域城邦林立，诸王竞逐商道与沃土。沙姆希阿达自底格里斯河上游崛起，唯西南方向受制于控扼幼发拉底河商路的马里王国。马里王亚赫敦林屡与亚述争锋，未几马里宫廷突发变乱。沙姆希阿达乘机亲统亚述大军顺河南下，兵锋直逼幼发拉底河畔马里。"],"tactical":["马里城背倚幼发拉底河干流，凭人工运河与厚重土砖城垣构筑防线，亚赫敦林一方据城待援。沙姆希阿达进抵外围后，先分兵弹压沿河诸镇，截断游牧援军通道，随即沿运河堤岸合围猛攻。孤城人心瓦解，亚述军破城而入，亚赫敦林败亡；沙姆希阿达留子镇守马里，上两河自此联为一统。"],"history":"约公元前一七九六年，上美索不达米亚霸主沙姆希阿达乘幼发拉底河中游重镇马里内乱之机，进军占领马里，置幼子镇守，构建起横跨上两河的古亚述疆域。异说与史料不足：马里泥板载马里王亚赫敦林先死于宫廷侍从刺杀，其子短暂继位后亚述夺取马里，定稿表取名王亚赫敦林为守方代表；攻城具体细节泥板阙载。","sources":"马里王室泥板文书；亚述王表"},
    "guyashu_tigelate": {"strategic":["公元前七三二年，新亚述帝国凭常备军制大举经略地中海东岸。亚兰国王利汛不甘纳贡，联以色列结成反亚述同盟，出兵围攻拒不入盟的犹大王国。亚述王提格拉特应犹大求援南下，先扫荡沿海断埃及外援，再席卷以色列北境剪除羽翼，回师合围孤立无援的大马士革。"],"tactical":["大马士革坐落反黎巴嫩山东麓绿洲，巴拉达河环绕，城坚林密，利汛败退入城闭门死守。提格拉特不急于蚁附硬攻，先扫平周边属邑、砍伐果园断其生计，再筑围墙土山以攻城槌反复猛撞。久困之下城内粮尽防溃，亚述军破城擒杀利汛，废亚兰改置行省，叙利亚诸邦尽数俯首。"],"history":"公元前七三二年，新亚述国王提格拉特应犹大王亚哈斯求援，继扫荡腓尼基与以色列北境后，主力合围反亚述同盟首脑亚兰国王利汛的都城大马士革。经严密围困与摧毁城外园林属邑，亚述攻破大马士革，处死利汛，将亚兰故地改置为亚述行省，终结了亚兰大马士革王国。","sources":"提格拉特帕拉沙尔三世铭文；列王纪下·第十六章"},
    "guzhu_tianyu": {"strategic":["公元二二四年，鲜卑雄主轲比能攻掠东部大人素利，塞上告急。魏护乌丸校尉田豫率骑步出塞赴援，乘虚掩击其别部，素利得全；轲比能耻其来救，收合追骑自后邀击，将田豫孤军合围于代郡马城故垒，围之十重，断其归路。"],"tactical":["马城残垣孤悬塞外，田豫兵少不能野战，遂闭垒示弱而密授方略。先令司马建旌旗、鸣鼓吹，自南门大张声势而出以诱敌，鲜卑竞赴南门；田豫自率精锐潜启北门，纵骑突其阵后，两门夹击呼声动地，鲜卑前后不能相顾，阵乱大溃，魏军追讨二十余里，斩获甚众而还。"],"history":"东汉黄初五年，鲜卑轲比能攻掠东部大人素利，魏护乌丸校尉田豫率军出塞救援，乘虚掩击鲜卑别部，素利得全。班师还至代郡马城，轲比能耻其来救，收合追骑自后邀击，将田豫孤军围于马城故垒十重。田豫闭垒示弱，令司马建旌旗鸣鼓吹自南门出诱敌，自率精锐自北门潜出，两门夹击大破鲜卑追骑，追讨二十余里。","sources":"三国志·魏书·田豫传；三国志·魏书·乌丸鲜卑东夷传"},
    "guzhu_tianyu@233": {"strategic":["公元二三三年，东吴为联结辽东割据势力夹击曹魏，特遣将军周贺等统船队浮海北赴辽东结盟。曹魏宿将田豫奉命督青州诸军防海，力劝刺史勿劳师远渡；他算准周贺深秋南归必畏海风而贴山东半岛东端成山避风，遂亲率精兵潜伏成山。"],"tactical":["成山角突入黄海惊涛之中，暗礁密布、秋风狂骤，乃南北航海必经险岬。田豫预先在海湾隐蔽处布设伏兵，严禁烟火静待敌帆；深秋九月周贺自辽东海岛满载归航，行至成山洋面果遇海上狂风巨浪，战船失控纷纷撞礁靠岸寻避。田豫一声令下，魏军伏兵自岸崖四面杀出截断退路，周贺措手不及当场被斩，吴国联辽计划破产。"],"history":"三国魏青龙元年，吴王孙权遣太常张弥、执金吾许晏与将军周贺浮海赴辽东册封公孙渊。汝南太守田豫料吴船秋归必惧海风漂流而停靠山东半岛东端成山岛避风，劝青州刺史程喜勿劳师绝海，亲督青州诸军预先潜伏成山。九月公孙渊斩张弥而周贺自登莱海岛归航，果遇大风触岸，田豫伏兵尽擒其众并斩周贺。","sources":"三国志·魏书·满田牵郭传"},
    "han_d_liubang": {"strategic":["公元前二〇六年，受封汉中的汉王刘邦重用韩信整训兵马，决意东出关中争夺天下。昔日刘邦入蜀曾焚毁褒斜栈道以麻痹分封关中的雍王章邯；出兵之际汉军故意派偏师大张旗鼓修复旧栈道，刘邦则亲统主力潜循偏僻故道翻越秦岭，暗扑关中门户陈仓。"],"tactical":["陈仓地处秦岭北口、渭水咽喉，城坚险固。章邯见汉军久修褒斜栈道，笑其迟缓而未防西路故道；岂料刘邦主力骤自故道天降，袭占陈仓外围。章邯惊闻有失，仓促调雍地兵马赶来救援，于城下与汉军迎面交锋；刘邦督汉军奋勇冲杀大败章邯，迫其退困废丘，三秦望风归汉，楚汉争霸格局由此奠定。"],"history":"公元前二〇六年夏秋，被贬封巴蜀汉中的汉王刘邦拜韩信为大将决意东出。此前刘邦依张良计烧褒斜栈道麻痹雍王章邯；出师时遣将表面修栈道吸引敌军视线，刘邦统主力循偏僻故道北上，突然袭占秦岭北口重镇陈仓，击败来援的章邯，顺势还定三秦。","sources":"史记·高祖本纪；史记·淮阴侯列传"},
    "han_d_liubang@-202": {"strategic":["公元前二〇二年冬，楚汉相持经年议定鸿沟之约，项羽引饥疲楚师东归；汉王刘邦采纳张良、陈平勿纵虎归山之谏，当机立断撕毁盟约挥师追击。刘邦许以裂土重赏，尽调韩信、彭越、英布诸路兵马四方响应，将项羽主力重重合围于垓下。"],"tactical":["垓下旷野寒风凛冽，汉军连营层叠锁死四方出路。刘邦坐镇中枢统合诸侯，推韩信居中调度正面决战，彭越、英布分扼侧后粮道；汉军以层叠阵法挫败项羽困兽冲锋，将其死死压缩于孤垒之内。入夜刘邦命汉营四面高唱楚歌，攻心瓦解楚军斗志；项羽众叛亲离突围至乌江自刎，刘邦遂一统海内开创大汉基业。"],"history":"公元前二〇三年楚汉议和划鸿沟为界，项羽引兵东归，刘邦纳张良、陈平养虎遗患之谏毁约追击，在固陵受挫后依张良计重划封地，调齐王韩信、梁王彭越南下，会合淮南王英布、刘贾自南截击。公元前二〇二年冬各路汉军合围项羽于垓下，十面埋伏、四面楚歌彻底瓦解楚军，项羽乌江自刎，刘邦平定天下建立汉朝。","sources":"史记·高祖本纪；史记·留侯世家；汉书·高帝纪"},
    "han_d_liubang@-205": {"strategic":["公元前二〇五年春，汉王刘邦暗度陈仓平定三秦后东出函谷，借义帝遇弑之名传檄讨楚，沿途收服魏、赵、韩诸侯。趁西楚霸王项羽主力深陷齐地苦战，刘邦统合诸侯联军长驱攻占楚都彭城；项羽闻老巢有失，亲选精骑星夜南下回扑彭城。"],"tactical":["彭城外环谷、泗、睢诸水，城野开阔无险阻拦骑兵。刘邦入城后以为大局已定，收罗财宝日夜置酒高会，联军各部散漫无备。项羽铁骑拂晓自西侧骤然杀至，半日便冲垮松散的诸侯步阵；汉军争相逃奔，被逼入谷泗与睢水溺毙无数，刘邦家眷遭俘，幸遇狂风飞沙遮蔽楚骑视线，刘邦方携轻骑突围西保荥阳。"],"history":"公元前二〇五年春，汉王刘邦东出函谷渡河定魏殷，在洛阳为被项羽暗杀的义帝发丧，号召天下诸侯讨楚。趁项羽主力深陷齐地未归，刘邦统合五诸侯大军攻占楚都彭城，日夜置酒疏于防范；项羽率精骑星夜自鲁萧县西侧反扑，半日击溃汉联军于谷泗睢水，刘邦父母妻儿被楚军掳获，赖狂风骤起得以率少数随骑脱险西保荥阳。","sources":"史记·高祖本纪；史记·项羽本纪；汉书·高帝纪"},
    "han_zhao_liuyao": {"strategic":["公元三二八年冬，前赵皇帝刘曜在河东重创后赵劲旅，声威大震，乘胜挥师南渡黄河重重围困洛阳，企图一举摧毁后赵南境重镇。后赵主石勒不顾群臣阻拦，亲统河北步骑主力星夜驰援；刘曜骄矜轻敌，竟撤回防守成皋天险的偏师，坐放石勒渡河进抵洛阳城下决战。"],"tactical":["洛阳城西原野背靠洛水，刘曜撤开外围在城西平地列阵；但他平素嗜酒，出营前连饮数斗美酒致神志昏沉，临时改换矮小马匹督阵。石勒看破前赵阵脚移动松散，命精兵自洛阳诸门分道杀出合击；混战中前赵大阵溃乱，醉眼朦胧的刘曜逃至冰渠坠马，身被十余创为后赵兵生擒，雄踞关陇的前赵帝国就此轰然覆灭。"],"history":"公元三二八年冬，前赵皇帝刘曜大破后赵北路军后南渡黄河合围洛阳。刘曜自恃屡胜，既不派兵扼守成皋黄河渡口，又终日在洛阳城西营中纵酒懈怠；后赵主石勒亲统主力偷渡成皋潜入金墉城，乘刘曜临阵醉酒改骑小马之际分门夹击，前赵大军崩溃，刘曜坠马被擒遇害，前赵遂亡。","sources":"晋书·刘曜载记；晋书·石勒载记下；资治通鉴·晋纪十六"},
    "han_zhao_liuyao@316": {"strategic":["公元三一六年秋，洛阳倾覆后西晋宗室在关中拥立晋愍帝司马邺苟延残喘，城孤粮匮。汉赵相国大都督刘曜自河东挥师西进，连破北地屏障扫清关中北路，率大军兵临西晋最后国都长安城下；司马邺急发诏书遍召四方州郡勤王，与刘曜作困兽之争。"],"tactical":["长安外郭辽阔而内城狭促，关中久经战乱早已残破。刘曜一面筑起严密围墙锁死长安粮道，一面分遣铁骑击退安定、新平诸路畏缩援兵；秋九月汉赵军猛攻突破外城，迫晋军退缩内小城苦撑。困至寒冬城中米价腾贵、饿殍遍地，司马邺绝望之下乘羊车肉袒出城向刘曜投降，西晋王朝至此彻底灭亡。"],"history":"西晋建兴四年秋八月，汉赵中山王相国大都督刘曜自河东统大军攻破北地，直扑西晋残喘国都长安。晋愍帝司马邺急召四方勤王，刘曜分兵挫退安定焦嵩、新平竺恢、弘农宋哲诸援军，九月攻陷长安外城迫麹允、索綝退守小城。城内断粮饥荒惨烈，十一月晋愍帝司马邺乘羊车肉袒出降，西晋彻底灭亡。","sources":"晋书·孝愍帝纪"},
    "hekaniya_artabazos": {"strategic":["公元前三三〇年，波斯帝国大厦已倾，东逃的波斯王遭叛臣劫持遇害。累朝白发老臣阿尔塔巴佐斯义不从贼，率诸子与效忠王室的希腊雇佣军脱离叛党，退入里海南岸山林险峻的赫卡尼亚；马其顿王亚历山大旋即翻山追剿，兵指赫卡尼亚首府兹拉卡塔。"],"tactical":["赫卡尼亚北临里海、南障崇山，首府兹拉卡塔坐落山麓谷地。亚历山大分兵穿山并进，自率轻锐攀绝径击破沿途山地部族阻截，会师进驻兹拉卡塔。退保群山的阿尔塔巴佐斯见马其顿军势不可当，且故主已死、逆臣无道，知孤军难挽天命，遂携诸子赴营归附；亚历山大敬其忠义隆礼相待，里海南岸自此平定。"],"history":"公元前三三〇年夏，波斯王大流士三世东逃途中遭叛臣贝苏斯弑杀，唯老臣阿尔塔巴佐斯坚守忠节，携诸子与希腊雇佣兵脱离叛党退入里海南岸赫卡尼亚山地。马其顿王亚历山大翻山平定部族进驻首府兹拉卡塔，阿尔塔巴佐斯见波斯天命已终，赴营体面归附，获隆礼优待。","sources":"阿里安·亚历山大远征记·第三卷；库尔提乌斯·亚历山大大帝史"},
    "helian_helianbobo@418": {"strategic":["公元四一八年，东晋主帅收复长安后匆匆南返建康，仅留年幼的皇族子弟刘义真镇守关中，辅政诸将却在城内互相猜忌残杀。雄踞朔方统万城的大夏天王赫连勃勃闻讯大喜，断言关中唾手可得，先遣铁骑南下咸阳截断粮道，随亲统主力合围孤危长安。"],"tactical":["长安东南蓝田青泥道山谷险狭、泥淖难行，乃退往荆洛的必经咽喉。刘义真在内讧自毁羽翼、外绝粮援之下被迫弃长安东逃，士卒却沿途贪恋掳掠财货，致行军队列拥塞迟缓；赫连勃勃督大夏轻骑昼夜疾追，在青泥狭谷将晋军团团追及截杀。晋军大溃全军覆没，刘义真仅单骑藏身草丛幸免，赫连勃勃遂入主长安筑京观称帝。"],"history":"公元四一七年东晋太尉刘裕攻灭后秦收复长安，年底因刘穆之卒急归建康，留幼子桂阳公刘义真都督雍梁秦三州镇长安，王修、王镇恶、沈田子辅之。大夏天王赫连勃勃闻讯大喜，命赫连璝南下据咸阳断长安粮道。四一八年长安诸将内讧相继残杀王镇恶、沈田子、王修，十一月刘义真弃长安东逃，赫连勃勃追击于蓝田青泥全歼晋军，遂入长安称帝。","sources":"晋书·赫连勃勃载记"},
    "hesitiya_yiasong": {"strategic":["公元前三七四年，中南希腊诸强缠斗正酣，北方费莱僭主伊阿宋已练成精悍雇佣军与铁骑，统一色萨利全境并获举为最高统帅。伊阿宋志在问鼎全希霸权，统劲旅越温泉关南向经略福基斯与圣地德尔斐；雅典等邦震动，福基翁一方依托山地险隘严阵戒备。"],"tactical":["德尔斐外围山峦耸峙，谷道崎岖，不利重骑冲锋，福基翁一方抢占山口高地据险设防。伊阿宋疾行抵近，审知仰攻坚隘必损精锐，遂发挥轻盾步卒与色萨利骑队机动迅捷之长，分兵扫荡外围邑落与要道实施武力慑压。守军困于险隘不敢野战，被迫在通道事务上妥协；伊阿宋打通南下走廊后全师北还，威震希腊。"],"history":"公元前三七四年前后，色萨利最高统帅伊阿宋统一色萨利全境后率精锐骑兵与雇佣军南下经略福基斯与圣地德尔斐周边，震动希腊诸邦。史料不足与定值：色诺芬等载伊阿宋南下经略福基斯并觊觎德尔斐祭典主导权，古典史料未载守方主将，定稿表取雅典将领福基翁为代表，播报概括扼险对峙。","sources":"色诺芬·希腊史·第六卷；西西里的狄奥多罗斯·历史丛书·第十五卷"},
    "heti_muwatali": {"strategic":["公元前一二七四年，赫梯帝国雄踞小亚细亚，视奥龙特斯河流域为南疆屏障。埃及法老拉美西斯即位后经略迦南，诱使赫梯藩属阿穆鲁背盟投埃，率大军北图卡迭石。赫梯王穆瓦塔利深知卡迭石有失则北叙利亚尽摇，遂征集本部与盟邦兵马倾力南下，提前进抵卡迭石城外布阵待敌。"],"tactical":["奥龙特斯河绕过卡迭石城垣，城东平地便于战车藏匿。穆瓦塔利隐主力于城背，遣牧人诈降诱拉美西斯孤军渡河安营；待埃军前后脱节，即令战车涉浅冲散埃军次队并杀入王营。惜车兵贪掠财货致攻势受阻，遭埃军援兵反扑退回东岸。次日拉美西斯引兵南撤，穆瓦塔利乘势收复阿穆鲁，稳固南疆霸权。"],"history":"公元前一二七四年五月，赫梯国王穆瓦塔利纠合帝国与属邦兵力南下叙利亚，在奥龙特斯河畔卡迭石设伏迎击埃及法老拉美西斯。穆瓦塔利遣人诈降诱使埃军前锋孤军深入，发重型战车渡河冲垮埃军队列并围攻法老营垒；因车兵贪掠辎重且埃军援兵赶到未能全歼对手，但成功迫使埃军撤退，稳保叙利亚霸权。","sources":"哈图沙泥板文书；卡迭石铭文"},
    "huaiyang_zhouyafu": {"strategic":["公元前一五四年，汉廷推行削藩之策，吴王刘濞串联楚赵等七国打着清君侧旗号举兵西叛，倾力猛攻梁国重镇睢阳，关东大震。汉景帝急拜名将之后周亚夫为太尉挂帅东征；周亚夫审察敌势，避开正面锐气，引汉军主力疾趋梁东南的要冲昌邑。"],"tactical":["昌邑控扼梁楚侧翼与淮泗咽喉。周亚夫任凭梁王苦求，始终深沟高垒闭营不出，令刘濞求速战不得；暗中却遣轻骑绕出淮泗，彻底截断吴楚粮道。相持月余叛军饥疲，刘濞乘夜声东击西猛扑汉营仍被严阵挡回，无奈拔营东退；周亚夫立纵精骑衔尾追歼，吴楚军土崩瓦解，刘濞败逃被杀，七国之乱三月荡平。"],"history":"公元前一五四年正月，汉景帝削藩引发吴王刘濞联楚赵等七国西叛，猛攻梁国睢阳。汉廷拜周亚夫为太尉东征；周亚夫绕道武关抵洛阳，弃梁不救而南据昌邑深沟高垒，遣轻骑出淮泗绝吴楚粮道。刘濞饥疲夜袭汉营不克，退走下邑遭周亚夫精骑追歼大溃，逃东越被杀，七国之乱三月而平。","sources":"史记·吴王濞列传；史记·绛侯周勃世家；汉书·周亚夫传"},
    "huizhou_zhugeliang": {"strategic":["公元二三一年春，蜀汉丞相诸葛亮造木牛转运粮草，第四度统师北出祁山叩击陇右。曹魏急调老谋深算的大都督司马懿西镇统辖关陇精兵来救；司马懿初欲坚壁疲敌，诸葛亮却抢先一步神速东趋上邽，当着魏军之面尽数收割田间新麦，随即从容退驻卤城据险待战。"],"tactical":["卤城背倚两座险山、前临西汉水河谷，诸葛亮依山分立双营控扼要道。魏营诸将因坐失上邽麦粮羞愤难平，纷纷请战逼司马懿进兵；司马懿只得分遣偏师攻山，亲率主力直扑蜀营中坚。诸葛亮早布严密八阵静候，挥旗令魏延等率精卒自高坡迎头反冲；强弩劲戟撕裂魏军前阵，司马懿大败退回营垒，闭门不敢复出。"],"history":"公元二三一年春，蜀汉丞相诸葛亮以木牛运粮第四次出祁山北伐，曹魏命大都督司马懿代病重的曹真统张郃、郭淮等西御。诸葛亮神速北上抢割上邽熟麦充实军粮，退据卤城依二山扎营；司马懿迫于诸将苦请进逼攻营，诸葛亮命魏延等正面迎战大破司马懿，迫其退保坚壁不敢再出。定值：战场改定为卤城。","sources":"三国志·蜀书·诸葛亮传；晋书·宣帝纪；资治通鉴·魏纪四"},
    "huizhou_zhugeliang@225": {"strategic":["公元二二五年春，蜀汉历经夷陵重创后国步维艰，南方南中诸郡豪帅与夷部乘隙煽乱背叛。丞相诸葛亮深知后方不靖则断难北伐中原，在休养农桑、整饬军备后亲统大军分道南征；击溃外围叛部后，汉军五月渡过泸水，直指夷汉共服的首领孟获与重镇滇池。"],"tactical":["南中群山瘴雾弥漫、水泽深险，孟获收拢残余劲卒凭山川险阻顽强抗拒。诸葛亮牢记攻心为上、攻城为下之策，在盘蛇山谷与滇池原野屡以严整阵法及强弩击破孟获军阵；每次生擒孟获，诸葛亮皆带其观览汉营虚实后从容纵还。屡擒屡纵之下孟获彻底折服，泣誓南人永不复反，南中人力军资自此尽供蜀汉北伐。"],"history":"三国蜀汉建兴三年春三月，丞相诸葛亮为解除北伐后顾之忧，亲统大军分三路南征叛乱的南中四郡。越嶲高定、牂牁朱褒先后败灭，益州郡豪帅雍闿为高定部曲所杀，素为夷汉信服的豪杰孟获代统其众顽抗。诸葛亮采马谡攻心为上之策，渡泸水进抵滇池，连战连擒孟获并屡纵之，终令孟获心悦诚服，南中平定。","sources":"三国志·蜀书·诸葛亮传"},
    "huizhou_zhugeliang@234": {"strategic":["公元二三四年春，蜀汉丞相诸葛亮休兵三年后，统主力由斜谷口再出秦岭北伐，以流马运粮进据渭水南岸五丈原。曹魏大都督司马懿统关陇大军渡渭水背水筑垒阻截；诸葛亮见速战难成，遂分兵与关中百姓杂居渭滨屯田久驻。"],"tactical":["五丈原高耸宽平，北瞰渭水、南依秦岭，控扼关中西门。司马懿抢占渭北原头锁死东进通路，随后深沟高垒闭门不出；诸葛亮屡遣轻兵搦战，更送去巾帼妇人衣饰激将，司马懿仍借魏廷节杖按兵耗敌。相持百余日至秋风骤冷，诸葛亮积劳成疾星陨军帐；蜀军秘不发丧，以木像惊退追来的司马懿，全师安然入谷。"],"history":"三国蜀汉建兴十二年春二月，丞相诸葛亮休兵三年后悉大众由斜谷口第五次北伐，以流马运粮进据武功五丈原，分兵屯田渭滨久驻。曹魏大都督司马懿渡渭水背水筑垒坚拒不战，诸葛亮遗以巾帼妇人饰激战，司马懿上表请战实待辛毗持节制止。相持百余日秋八月诸葛亮积劳病逝军中，杨仪、姜维整军设疑吓退司马懿安然还师。","sources":"三国志·蜀书·诸葛亮传"},
    "jialedi_nibujianisa": {"strategic":["公元前五八七年，新巴比伦与埃及激烈争夺黎凡特走廊。巴比伦王尼布甲尼撒亲手册立的犹大王西底家受亲埃贵族怂恿，撕毁盟誓拒纳贡赋，暗引埃及北援。尼布甲尼撒决不容西南门户失控，统大军扫平犹大外围据点，将主力合围至西底家据守的都城耶路撒冷。"],"tactical":["耶路撒冷雄踞犹大山地脊梁，三面深谷险峻，唯北面稍缓，西底家凭坚厚石墙闭门待援。尼布甲尼撒环城筑垒严密封锁，中途分兵击退北上的埃及援军，断绝守军外援。久困之下城内饥疫交加，巴比伦军撞破北墙缺口杀入城中，追骑擒获夜逃的西底家，拆城墙焚圣殿，犹大王国就此覆亡。"],"history":"公元前五八九年至前五八七年，犹大王西底家背叛新巴比伦转结埃及，巴比伦王尼布甲尼撒亲率大军合围耶路撒冷。期间巴比伦军击退埃及援军，久围绝粮后于前五八七年夏攻破北墙，擒获外逃的西底家，焚毁圣殿王宫，掳其民入巴比伦，犹大亡国。注：任务表敌方标为以色列，实为犹大王国；破城年份另有前五八六年说。","sources":"列王纪下·第二十五章；耶利米书；巴比伦编年史"},
    "jialedi_nibujianisa@-605": {"strategic":["公元前六〇五年，亚述都城虽倾，近东霸权仍未底定。埃及法老尼科二世借扶助亚述残部之名北上，重兵扼守幼发拉底河西岸要塞卡基米什，阻遏新巴比伦西进。年迈的巴比伦王留镇都城，将全国主力交付王储尼布甲尼撒；尼布甲尼撒溯河北上直抵卡基米什对岸。"],"tactical":["卡基米什紧扼幼发拉底河上游渡口，尼科二世集埃及精兵与雇佣步卒重防浅滩。尼布甲尼撒避开正面强渡，密率主力自下游悄然济河，迂回城西截断埃军后路。尼科二世仓促出战，两军自旷野鏖战至街巷火海，埃军防线全面崩盘；尼科二世败逃南归，叙利亚与迦南尽归新巴比伦号令。"],"history":"公元前六〇五年夏，埃及法老尼科二世占据幼发拉底河上游重镇卡基米什，联合亚述残余阻遏新巴比伦西进。巴比伦王储尼布甲尼撒统军北上，绕渡幼发拉底河奇袭卡基米什，内外夹击歼灭埃及主力，尼科二世败逃，新巴比伦尽收黎凡特霸权。定值：敌将取埃及法老尼科二世。","sources":"巴比伦编年史；耶利米书·第四十六章"},
    "jiaodong_tiandan": {"strategic":["公元前二七九年，燕军横扫齐境已历五载，强齐仅余莒与即墨孤城苦撑。即墨守将田单趁燕国新君继位素忌乐毅，密派细作入燕散布反间流言；燕王果真撤换乐毅，改派刚愎轻敌的骑劫接掌围城大军，田单苦候多时的绝地反击良机终于到来。"],"tactical":["即墨城外燕营连绵，田单先设神师振奋人心，诱骑劫割降卒鼻、掘祖坟以激全城死志，再遣富户献金诈降麻痹敌军。入夜田单将耕牛披彩帛、角缚利刃、尾系油苇，凿穿城墙暗洞点火纵牛狂冲燕营，彩绘死士紧随挥刀掩杀，城头击铜声震天地。燕军梦中惊溃自相践踏，骑劫死于乱军，田单乘胜尽复齐国失地。"],"history":"公元前二七九年，齐宗室田单死守孤城即墨五载后，乘燕惠王新立纵反间计，诱燕以躁进的骑劫取代名将乐毅，复设神师与诈降麻痹燕军、激怒守民。田单乘夜集城中耕牛缚刃于角、系油苇于尾点燃冲出城洞，死士随牛掩杀，大破燕军并阵斩骑劫，尽复齐国故地。","sources":"史记·田单列传；战国策·齐策六"},
    "jiluo_d_douxian": {"strategic":["公元八九年，北匈奴遭旱蝗饥疫而国势衰乱，南匈奴上书请乘机北伐并合南北。东汉朝廷拜外戚窦宪为车骑将军挂帅，调集北军与边郡铁骑，会合南匈奴及乌桓羌胡联军分道出鸡鹿塞；各路大军于漠北涿邪山会师，直扑北单于驻牧的稽落山。"],"tactical":["稽落山横亘大漠深处，北单于聚拢草原残存主力依山谷列阵迎战。窦宪分遣精骑自多路并进合围，汉军强弩铁骑与久怀世仇的南匈奴骑群奋勇争先，迎头冲垮北单于本阵；北匈奴大败崩溃，北单于负伤乘夜远遁，诸部纷纷诣营归降。窦宪乘胜追至燕然山，登高临远命班固撰文刻石纪汉威德而还，漠北王庭自此烟消云散。"],"history":"公元八九年夏，东汉车骑将军窦宪与耿秉奉诏北伐，统汉军精骑会合南匈奴、乌桓、西羌分道出塞，会师涿邪山后与北单于主力决战于稽落山。汉军大破北匈奴，北单于遁走，窦宪登燕然山令班固作铭刻石纪功，彻底摧垮北匈奴漠北基业。定值：战场改定为稽落山。","sources":"后汉书·窦融列传；资治通鉴·汉纪四十一"},
    "jin_xianzhen": {"strategic":["公元前六三二年，中原霸主虚位，楚国大举北进，楚令尹子玉统兵围困宋都。晋中军元帅先轸献策，攻破附楚的曹卫两国并激齐秦参战，迫使子玉释宋北上寻战。先轸统晋军主动退避三舍以报旧惠、骄敌致师，将孤军深入的子玉主力引至卫地城濮。"],"tactical":["卫地城濮原野与丘陵相间，外有泽薮阻隔，两军列阵对决。晋下军给战马蒙虎皮直冲楚右翼陈蔡军，敌马惊溃，楚右翼先行瓦解；晋上军竖双旆佯退，诱楚左翼脱离本阵急追。先轸看准战机，率中军精锐拦腰横击，配合上军回身夹攻大破楚师；子玉败归自尽，晋国由此奠定中原霸业。"],"history":"公元前六三二年四月，晋文公以先轸为中军元帅南下救宋，攻曹伐卫致楚师，与楚令尹子玉决战于卫地城濮。晋军退避三舍骄敌，决战时下军蒙虎皮冲溃陈蔡右军，上军设二旆佯退诱敌，先轸率中军横击大破楚左军，子玉败归自尽，晋国践土会盟确立中原霸主地位。","sources":"左传·僖公二十八年；史记·晋世家"},
    "jin_xianzhen@-627": {"strategic":["公元前六二七年，晋文公新丧，秦穆公不听蹇叔苦谏，遣孟明视统兵越晋南远袭郑国。因郑商弦高沿途示警，孟明视见郑有备，袭灭滑国后引军西归。晋中军元帅先轸力斥纵敌之议，说动晋襄公染黑丧服出征，联姜戎星夜赶赴秦军必经的殽山设伏。"],"tactical":["殽山分南北两险峰，谷深林密、栈道狭长，车马穿行进退维谷。孟明视率疲敝秦军入谷，轻视晋丧而未派斥候搜山，队列拉成一线。待秦军尽入袋形谷底，先轸令两侧绝壁伏兵礌石齐下，封死东西谷口断其退路，居高临下四面掩杀。秦军全军覆没，孟明视被擒，秦国东进争霸之路自此锁死。"],"history":"公元前六二七年春，秦穆公违蹇叔之谏，遣孟明视等率军越晋境远袭郑国；因郑商弦高犒师示警，秦军灭滑而还。时晋文公新丧，中军元帅先轸力劝晋襄公墨绖从戎，联姜戎设伏于殽山峡谷，全歼秦军并生擒孟明视等三帅，锁死秦国东进中原之路。定值：敌将取秦军主帅孟明视。","sources":"左传·僖公三十三年；史记·晋世家；史记·秦本纪"},
    "jingzhou_gs_huangfusong": {"strategic":["公元一八八年冬至次年春，凉州叛帅王国纠合韩遂诸部东侵三辅，重兵合围右扶风重镇陈仓，关中震动。东汉朝廷起拜宿将皇甫嵩为左将军督前将军董卓驰援；董卓急请速进解围，皇甫嵩却断言陈仓虽小而城固难拔，按兵不动静待王国师老自敝。"],"tactical":["陈仓背渭水而控散关，城防坚不可摧。王国督凉州精骑猛攻八十余日寸步难进，士卒疲怠沮丧，至春初无奈解围弃城西退。皇甫嵩见战机已熟，不顾董卓以穷寇勿追苦阻，留董卓殿后，亲率本部精兵衔尾急追；敌军本无斗志且行列散乱，皇甫嵩连战连捷大破叛军致王国败亡，关中危局一战得安。"],"history":"公元一八八年冬，凉州叛军首领王国率韩遂、马腾等部合围关中门户陈仓，汉廷拜名将皇甫嵩为左将军督董卓驰援。皇甫嵩拒董卓速战之议，按兵待敌师老；次年春王国围城八十余日不拔解围西退，皇甫嵩独督本部乘疲追击连破之，王国败亡。定值：决战在公元一八九年、战场定为陈仓。","sources":"后汉书·皇甫嵩朱儁列传；资治通鉴·汉纪五十一"},
    "jingzhou_gs_huangfusong@184": {"strategic":["公元一八四年秋，东汉左中郎将皇甫嵩扫平中原黄巾后，奉诏北上接掌河北兵权，进讨盘踞巨鹿广宗的黄巾最精锐主力。此时黄巾首脑张角已病殁，其弟张梁统领河北死忠教众据守广宗，前番已连挫汉军；皇甫嵩抵前线重整营垒，与张梁展开生死较量。"],"tactical":["广宗城壕深阔，河北黄巾悍勇善战，初交锋皇甫嵩亦未能取胜。皇甫嵩审知敌军凭一口锐气死斗，当即下令闭营休兵以示怯弱；张梁见汉军连日不出，戒备日渐松弛。冬夜皇甫嵩密令全军暗中披甲衔枚，赶在鸡鸣破晓时分突袭黄巾大营；汉军鼓噪杀入连战至日暮，彻底击溃黄巾主力并临阵斩杀张梁，黄巾主力就此覆灭。"],"history":"东汉中平元年秋八月，左中郎将皇甫嵩平定颍川、东郡黄巾后，奉诏接替作战失利的董卓北讨盘踞巨鹿广宗的河北黄巾主力。时天公将军张角已病死，弟人公将军张梁统精勇之众死守广宗。皇甫嵩初战不利，闭营休士以骄敌心，冬十月探知张梁松懈，夜勒兵鸡鸣突袭大战至哺大破之，阵斩张梁。","sources":"后汉书·皇甫嵩朱儁列传"},
    "jinling_tandaoji@417": {"strategic":["公元四一七年春，东晋北伐前锋冠军将军檀道济率精兵自洛阳西进，连拔崤陕城池，兵锋直叩关中东大门潼关。后秦朝野大震，特拜威望素著的皇叔太宰姚绍总督中外精锐出镇潼关，企图凭山河雄关将檀道济死死挡在关中门外。"],"tactical":["潼关背靠秦岭陡崖、北临黄河天险，谷道仅容车轨通行。姚绍自恃兵众粮足，一面筑垒扼守关城，一面分遣偏将屯营大道企图断晋粮路；檀道济乘夜率锐卒突袭敌营，一鼓拔寨斩将挫其气焰。随后姚绍倾主力反扑，檀道济督北府精兵正面硬顶，连月血战重创秦军；姚绍忧愤呕血死于军中，潼关防线瓦解。"],"history":"东晋义熙十三年春，冠军将军檀道济偕龙骧将军王镇恶自洛阳西进攻破陕城，直叩关中东大门潼关。后秦幼主姚泓拜宿将太宰鲁公姚绍为大宰大将军总督中外诸军统精锐出守潼关。姚绍分遣姚鸾屯大路绝晋粮道，檀道济与沈林子乘夜奇袭攻拔姚鸾垒斩之，继与姚绍主力连月血战重挫秦军，姚绍愤恚呕血而死，潼关遂克。","sources":"宋书·檀道济列传"},
    "jinling_tandaoji@431": {"strategic":["公元四三一年春，南北朝宋魏争夺河南战局急转直下，北魏名将叔孙建统塞北铁骑重重围困河南孤镇滑台。刘宋征南大将军檀道济奉命统师北救，自清水转战至济上连战皆捷，一路进抵历下；叔孙建避开步阵锋芒，改派轻骑四出抄截焚毁宋军粮道。"],"tactical":["历下至济水原野辽阔，滑台因粮尽失守，檀道济大军亦陷断粮绝境，更有逃卒投魏告密宋军无米。叔孙建率铁骑尾随正欲围歼，檀道济临危命士卒乘夜高声唱筹量沙，将仅存少许白米覆盖沙堆表面；天明魏军见白米成山，深惧中伏斩杀告密逃卒，檀道济从容披白袍乘舆引全军安然南归，名震北魏。"],"history":"刘宋元嘉八年春，征南大将军檀道济奉宋文帝命北救遭北魏叔孙建、安颉重围的河南重镇滑台，自清水进至济上二十余日间三十余战多捷，直抵历城。叔孙建纵轻骑前后抄截焚烧檀道济粮草，滑台粮尽失陷，檀道济军粮亦绝，夜演唱筹量沙奇计骗过魏军，次日着白衣乘舆徐引全军安然南归，威震北魏。","sources":"宋书·檀道济列传"},
    "jiujiang_zhouyu": {"strategic":["公元二〇八年秋，丞相曹操平定河北后挥师南征，兵不血刃收服荆州，旋即统合北军与荆襄水师顺长江浩荡东下，传书威逼江东归降。江东朝野震恐多主迎降，青年统帅周瑜力陈北军不习水战、疾疫将生等必败之理，奉命统精锐水师溯江西进，会合刘备共迎曹操于赤壁。"],"tactical":["赤壁矶头耸立长江南岸，与江北乌林曹军水寨隔江对峙。曹操北军远来染疫、晕船难战，遂将战舰首尾相连结为大营。周瑜初战挫敌后，采老将黄盖诈降奇策，预备满载枯柴膏油的蒙冲斗舰；隆冬东南风骤起，黄盖船队张帆直撞乌林，烈火延烧岸营，周瑜督水陆联军乘势掩杀大破曹操，天下三分大局由此奠定。"],"history":"公元二〇八年秋，丞相曹操南下受荆州之降，兼编荆襄水师顺长江东下威逼江东。孙权采周瑜、鲁肃抗曹大计与刘备结盟，拜周瑜为左督统精锐水军溯江西上，与曹操前锋遭遇于赤壁。曹军不习水战且染疾疫，以铁索连船驻乌林；周瑜纳黄盖诈降火攻之计，借东南风焚毁曹营战舰，大破曹操，奠定三分格局。","sources":"三国志·吴书·周瑜鲁肃吕蒙传；资治通鉴·汉纪五十七"},
    "jiujiang_zhouyu@209": {"strategic":["公元二〇九年，赤壁烈火重挫北军南下锋芒，北方主力引还中原，特留名将曹仁镇守荆州水陆中枢南郡江陵。江东前部大都督周瑜决意乘胜夺取全据长江的战略门户，一面分兵西取夷陵卡死峡口，一面亲统水陆精兵跨江合围曹仁固守的江陵坚城。"],"tactical":["江陵城郭宏固、储粮丰足，北通襄樊驿道，曹仁凭深沟重垣与悍勇骑队屡屡出城反扑。周瑜联结友军截断北面粮援，在城外筑起坚垒层层紧逼；激战中周瑜亲跨战马临阵督攻，右胁不幸被城头飞矢射穿，伤重卧帐。闻曹仁乘隙列阵挑战，周瑜忍痛扶创巡营激励三军，曹仁见江东军容凛然知不可胜，终弃江陵连夜北撤。"],"history":"赤壁大捷后，曹操北还，留征南将军曹仁、横野将军徐晃固守荆州重镇南郡江陵。东吴偏将军周瑜与程普乘胜溯江进逼南郡，遣甘宁奇袭夷陵夺取西面门户，与刘备、关羽配合作战绝北道粮援。建安十四年周瑜亲跨战马督攻江陵，右胁中流矢创甚，仍扶起巡营激励士气，终迫使曹仁弃江陵北退。","sources":"三国志·吴书·周瑜鲁肃吕蒙传"},
    "juqu_d_juqumengxun@420": {"strategic":["公元四二〇年夏，雄踞张掖的北凉君主沮渠蒙逊决意西吞酒泉西凉，实现河西走廊一统。沮渠蒙逊深知强攻耗力，先张扬兴兵南伐西秦，半途潜师折返隐伏川岩，同时密令张掖守臣向西凉主李歆诈降献城；李歆贪功不听母后苦谏，果真亲统主力东扑张掖。"],"tactical":["张掖以西怀城至蓼泉戈壁与绿洲交错，退路狭长无险可守。李歆行近张掖方觉中计，急令全军调头西撤；早待多时的沮渠蒙逊挥北凉精骑衔尾追杀，在怀城先行击破西凉后队。李歆收集散卒退至蓼泉，羞愤回马再与北凉主力死拼；沮渠蒙逊督铁骑四面合围猛攻，临阵斩杀李歆，乘胜直取酒泉攻灭西凉。"],"history":"公元四二〇年即北凉玄始九年夏秋，北凉河西王沮渠蒙逊决意吞并割据酒泉敦煌的西凉后主李歆。蒙逊先佯称南攻西秦浩亹，潜师还屯川岩，更令张掖太守沮渠广宗向李歆诈降诱敌。李歆不听尹太后与宋繇切谏亲统大军东趋张掖，觉诈退军遭蒙逊追败于怀城，李歆复回身死战于蓼泉被蒙逊击斩，北凉乘胜拔酒泉灭西凉。","sources":"晋书·凉武昭王李玄盛传附李士业传"},
    "kongque_zhantuoluo": {"strategic":["公元前三二一年，恒河流域的摩揭陀王国虽兵象强盛，难陀末王达那难陀却暴敛失道、朝野离心。青年豪杰旃陀罗笈多在智者辅佐下自西北印度崛起，建成稳固根基；他随统精兵沿恒河走廊大举东进，连拔边防重镇，直逼都城华氏城。"],"tactical":["华氏城据恒河交汇要冲，深壕与高耸木垣环护，达那难陀聚战象重兵闭城顽抗。旃陀罗笈多采取内外并举之策，在外围水陆要道击败出战之敌、断绝四方粮赋，同时分化城内守军斗志。待时机成熟，旃陀罗笈多挥军强渡深壕猛攻破城，推翻达那难陀统治，于华氏城登基开创孔雀帝国大一统基业。"],"history":"约公元前三二一年，青年豪杰旃陀罗笈多在智者考底利耶辅佐下，先据西北旁遮普积蓄兵力，继而沿恒河东讨摩揭陀难陀王朝末王达那难陀，合围攻克都城华氏城，推翻难陀王朝，建立印度首个大一统帝国孔雀王朝。定值：年份有前三二二至前三一七年诸说，统一取前三二一年。","sources":"往世书；大史；政事论；查士丁·腓力史概要"},
    "kongque_zhantuoluo@-305": {"strategic":["公元前三〇五年，执掌两河与波斯高原的西方霸主塞琉古挥师东征，强渡印度河企图收复西北印度旧省。此时北印度已由孔雀帝国皇帝旃陀罗笈多熔铸为一统强国；闻敌越境，旃陀罗笈多亲统庞大战象军团与车步劲旅西出迎截，东西两大帝国相撞于印度河畔。"],"tactical":["印度河谷滩涂湿热、支流湍急，令远道而来的塞琉古长矛方阵倍受掣肘。旃陀罗笈多凭举国供养的披甲象群与车步弓骑严密协同，在交锋中处处压制西方战马与步阵，并威胁敌军粮道。塞琉古知无力撼动孔雀根基，且西线战云紧迫，遂主动议和；旃陀罗笈多以战象换取兴都库什山南广袤疆土，将帝国版图推向极盛。"],"history":"公元前三〇五年，稳据西亚的塞琉古渡过印度河企图收回西北印度旧省，迎头遭遇已完成北印度大一统的孔雀帝国皇帝旃陀罗笈多。旃陀罗笈多凭庞大战象与严整车步重兵挫败塞琉古东进，迫使其缔结联姻和约，割让犍陀罗、阿拉霍西亚等西境，孔雀回赠战象。","sources":"斯特拉波·地理志·第十五卷；阿庇安·叙利亚战记"},
    "langzhou_zhangfei": {"strategic":["公元二一五年秋，北方曹操攻克汉中震动巴蜀，麾下宿将张郃乘胜统精兵翻越米仓山南侵巴西郡，企图掳掠民众以空蜀境。刘备急命勇冠三军的巴西太守张飞统率精锐北上御敌；张飞疾驰赶赴宕渠山地筑垒设防，迎头挡住张郃南下锋芒。"],"tactical":["宕渠群山环叠，蒙头、荡石诸峰间山道狭窄幽深，大军首尾难救。张郃依山结寨相持五十余日求胜不得；张飞摸透山间樵径脉络，挑选敢死精卒绕僻道悄然插至张郃营阵中段，骤然前后夹攻。曹军困于窄谷无法列阵互援，瞬间被冲成数截大败溃散；张郃仅率随从弃马攀山逃回汉中，巴西全境转危为安。"],"history":"公元二一五年秋，曹操攻取汉中后留夏侯渊、张郃镇守。张郃率军翻越米仓山南下益州巴西郡，企图强迁百姓北徙汉中，进军宕渠、蒙头、荡石一带。刘备命巴西太守张飞统精卒北上迎拒，两军相持五十余日，张飞引精兵自山间僻道奇袭截断张郃首尾，大破张郃迫其弃马攀山逃归。定值：战场改定为宕渠。","sources":"三国志·蜀书·关张马黄赵传；资治通鉴·汉纪五十九"},
    "langzhou_zhangfei@208": {"strategic":["公元二〇八年秋，丞相曹操挥师南征荆州，襄阳不战迎降，屯驻樊城的刘备仓促携军民弃城南奔江陵。因眷恋随行百姓日行迟缓，曹操自宛城精选轻装虎豹铁骑昼夜兼程疾追，在当阳长坂坡追垮刘备后队；危急之际猛将张飞奉命率精骑回身断后拒敌。"],"tactical":["当阳长坂丘陵起伏，木桥横跨湍急河水，扼住追击咽喉。曹操铁骑卷起漫天烟尘掩杀而来，溃兵四散；张飞命随骑砍断河桥，独自跨马横矛立马岸边，令从骑于桥后林间拴枝扬尘伪装疑兵。曹军先锋追至水边，见张飞瞋目怒喝声若惊雷、林间尘头蔽日唯恐中伏，竟与赶到的曹操主力俱不敢逼近，刘备遂得以安然脱险。"],"history":"东汉建安十三年秋九月，曹操南下荆州，刘琮秘密投降，屯驻樊城的刘备仓促携荆襄跟随民众南撤江陵。曹操自宛城简选虎豹精骑一日一夜急驰三百余里追及刘备于当阳长坂。乱军之中赵云护幼主甘夫人脱险，张飞奉命率二十骑断后，据水断桥瞋目横矛大喝拒敌，震慑曹操追骑无敢近者，掩护刘备安抵汉津。","sources":"三国志·蜀书·关张马黄赵传"},
    "lanzhou_zhaochongguo": {"strategic":["公元前六一年，河湟先零羌首领杨玉背盟叛乱，串联罕开诸羌渡湟水寇掠汉境，陇右震动。汉宣帝问谁可挂帅，年逾七旬的老将赵充国慨然自请百闻不如一见；他星夜驰赴金城允吾前线，与杨玉统领的精悍羌骑展开谋略较量。"],"tactical":["允吾至临羌峡谷深险、湟水湍急，杨玉屡遣游骑据险诱战。赵充国夜渡湟水稳筑营垒，严禁将士贪小利浪战；驱羌众离肥美牧地后，赵充国连上屯田奏疏，罢骑兵、留步卒沿河垦田积谷，分化附从羌部。久困之下先零羌内饥外孤、纷纷离散，残部斩首恶杨玉归降，创不战而屈人之兵的屯边典范。"],"history":"公元前六一年，先零羌首领杨玉背汉联诸羌犯金城。年逾七旬的后将军赵充国自请驰赴前线，夜渡湟水筑垒稳守，严禁贪功浪战；继而连上屯田三奏，罢骑兵留步卒于允吾临羌屯田困敌，分化瓦解诸羌，终使孤立饥困的先零羌内溃斩献杨玉首级，不战屈兵。","sources":"汉书·赵充国辛庆忌传；资治通鉴·汉纪十八"},
    "li_s_mayuan": {"strategic":["公元四二年，交趾女子征侧因忿官吏苛法，携妹揭竿反汉，岭南九真、日南诸部纷起响应，连陷城邑自立为王。东汉光武帝拜宿将马援为伏波将军督楼船南征；马援自合浦缘海而进，随山开辟险道克服酷暑瘴疠，水陆并进直抵征侧主力盘踞的交趾浪泊。"],"tactical":["浪泊水泽浩渺、密林环绕，炎瘴熏蒸。征侧聚骆越劲卒依水陆险隘设防，企图借南荒水土拖垮远来汉师。马援治军严整，稳扎营垒，待全军适应水土并摸清敌阵虚实后，指挥楼船水师与精锐步骑水陆协同总攻，正面冲碎骆越军阵。征侧大败溃走峡谷，马援乘胜荡平余党，立铜柱标明汉界，岭南南陲复归安定。"],"history":"公元四〇年交趾雒将之女征侧与妹举兵反汉，略取岭南诸城自立为王。东汉光武帝拜老将马援为伏波将军南征；公元四二年春，马援率水陆大军缘海随山刊道推进至交趾浪泊，与征侧主力会战大破之，次年斩征侧姐妹，复定交州。定值：战场改定为浪泊。","sources":"后汉书·马援列传；资治通鉴·汉纪三十四"},
    "li_s_mayuan@49": {"strategic":["公元四九年春，武陵五溪部族首领相单程再度聚众攻掠荆南郡县，前番征讨失利的汉廷朝议纷纭。年逾六旬的伏波将军马援披甲据鞍慷慨请缨，获光武帝拜帅督诸将南征；为求速破敌巢，马援舍弃平缓远道，统水陆汉军溯沅水径趋险要捷径壶头山。"],"tactical":["壶头山绝壁高耸，山下沅水急流回旋成险滩。相单程抢先聚五溪劲卒据守山巅险隘，阻截汉军粮船，致马援舟师困阻滩下。盛夏酷暑熏蒸、瘴疫大作，马援亦染重疾，仍在岸壁凿窟栖身，每闻敌军鼓噪便强撑观敌督战。马援终裹革殉职军中，而五溪亦被困至粮尽气夺，相单程遂诣汉营乞降，南疆复安。"],"history":"东汉建武二十四年武陵五溪蛮相单程复寇临沅，年逾六旬的新息侯马援慷慨据鞍请缨，光武帝拜其督马武、耿舒等南征。建武二十五年春马援进军沅陵，弃充道远路而择壶头山近途溯水急进，相单程据山顶扼守急湍，盛夏瘴疫流行，马援凿岸为室带病督战挫敌，终病逝军中，促相单程粮尽乞降。","sources":"后汉书·马援列传"},
    "liangzhou_zhanggui": {"strategic":["公元三〇五年，西晋八王同室操戈令中原烽烟四起，远见卓识的名臣张轨早已请调出镇河西，任凉州刺史整饬武备、劝课农桑。盘踞塞外的鲜卑首领若罗拔能见晋室衰乱无暇西顾，遂倾部族控弦铁骑大举南侵河西走廊，一路劫掠直逼凉州治所姑臧郊外。"],"tactical":["姑臧坐落祁连山北麓武威绿洲，城郊原野辽阔，鲜卑游骑势焰嚣张。张轨坐镇姑臧稳定河西大族民心，精选久习胡骑战法的凉州劲卒与良马，命干将统率出城列阵迎击。交锋中凉州铁骑顶住鲜卑弓骑攒射，结锋矢阵直贯敌军中枢，乱军中生斩主帅若罗拔能并尽俘其众；此战威震西陲，河西由此成为乱世桃源。"],"history":"公元三〇五年，中原深陷西晋八王混战，散骑常侍张轨早已远见求任护羌校尉、凉州刺史，抚定河西保境安民。鲜卑大人若罗拔能趁中原板荡率铁骑大举寇掠凉州，兵锋直逼治所姑臧城郊；张轨坐镇州城调度，遣司马宋配督凉州精骑出迎，临阵斩杀若罗拔能，保河西一方安宁。","sources":"晋书·张轨列传；资治通鉴·晋纪八"},
    "liguo_zhaoshe": {"strategic":["公元前二六九年，秦国首次将矛头直指北方强赵，猛将胡阳越过上党山地突然合围太行重镇阏与。赵廷宿将皆认山道险远难救，唯赵奢慨然进言道远险狭恰如两鼠斗于穴中，将勇者胜；赵王遂拜赵奢为将，统赵国劲旅西出邯郸奔援阏与。"],"tactical":["阏与深处太行群山，城北高岭俯瞰全城。赵奢刚出邯郸便筑垒留驻二十八日，斩妄言救他城者，并厚待秦探放归报信；胡阳闻报大笑，断定赵军惜城不敢进山，遂疏于外围戒备。岂料秦探甫离，赵奢即令全军卷甲昼夜疾奔，抢先登顶阏与北山筑垒列厚阵；胡阳仓促仰攻，赵奢居高俯冲合城内守军夹击大破秦师，威震列国。"],"history":"公元前二六九年，秦将胡阳越韩境围攻赵地阏与。宿将廉颇、乐乘皆谓道远险狭难救，唯赵奢以两鼠斗穴将勇者胜请行。赵奢出邯郸即筑垒坚壁二十八日并放归秦探麻痹胡阳，随即卷甲疾趋抢占阏与北山高地，居高俯冲大破秦军，受封马服君。定值：年份统一取前二六九年。","sources":"史记·廉颇蔺相如列传；战国策·赵策三"},
    "liu_yingbu": {"strategic":["公元前二〇七年冬，秦大将王离率长城边军重围赵都巨鹿，另有秦军筑甬道源源输粮，各路救赵诸侯皆慑于秦威筑壁旁观。楚上将军夺掌帅印决意死战救赵，特选军中骁勇冠绝的当阳君英布充任开路先锋，率先统精兵赶赴巨鹿漳水。"],"tactical":["巨鹿城外漳水冰寒，秦营森严，运粮甬道横贯原野连通王离大营。在诸侯壁上屏息注视下，英布率敢死锐卒先行强渡漳水，迎着强弩悍然扑向甬道防线；英布身先士卒反复冲杀，一举截断甬道粮运，初挫王离锐气。随后楚军主力破釜沉舟全军济河，英布乘胜勇冠诸军合围痛击，终生擒王离，扭转亡秦乾坤。"],"history":"公元前二〇七年冬，秦将王离重兵围赵于巨鹿，章邯筑甬道运粮接济，诸侯救兵皆筑壁畏缩旁观。项羽斩宋义夺军后，先遣骁悍无比的当阳君英布与蒲将军率精兵渡漳水，猛击秦军粮运甬道，断王离补给并初挫秦锋，为破釜沉舟全歼王离军打开大门。","sources":"史记·黥布列传；史记·项羽本纪"},
    "liu_yingbu@-202": {"strategic":["公元前二〇二年冬，楚汉鸿沟议和后汉军毁约追击东归楚师，汉廷重申裂土封王之约，急召各路诸侯合兵歼楚。已归汉受封淮南王的骁将英布尽起九江劲卒，诱反楚地守将席卷淮南，自南线疾驰北上截断退路，会同诸路汉军合围项羽于垓下。"],"tactical":["垓下原野沟壁交错，已成楚军孤岛。英布与南路友军封死城父至淮南通道，同北下的主力大军筑起层层围网。白昼决战中英布麾下熟知楚军战法的淮南精兵协力夹击，将项羽突击锋芒压回营垒；入夜四面楚歌四起，楚军思乡溃散，项羽突围南逃至乌江自刎，英布以南线合围殊功稳享淮南王爵。"],"history":"公元前二〇四年受随何说服背楚归汉的淮南王英布，在楚汉决战关头与刘贾入九江诱叛楚大司马周殷，尽收九江兵北上。公元前二〇二年冬，汉王刘邦追击东撤的西楚霸王项羽，韩信、彭越自北南下，英布与刘贾自南截断城父通道会师垓下，四面合围楚军并夜唱楚歌瓦解军心，项羽突围至乌江自刎。","sources":"史记·黥布列传；史记·项羽本纪"},
    "lu_zhangliao": {"strategic":["公元二一五年秋，北方主力远赴汉中作战，江淮重镇合肥守兵单薄；孙权抓住良机亲统江东大军倾国北上，将合肥围得水泄不通。镇守合肥的名将张辽开启主帅临行密函，决意趁敌军初至未稳先发制人挫其锐气；他与同僚捐弃旧嫌，连夜募集敢死锐卒整装待旦。"],"tactical":["合肥控扼巢湖通淮水道，城外肥水津渡狭窄。破晓时分张辽披甲持戟率先冲出城门，直扑江东前锋大营，亲手斩将夺垒杀至孙权帅旗之下，吓得孙权退保高冢，守军士气百倍。孙权围城十余日疫病流行无奈撤军，殿后时大部队已渡过逍遥津；张辽窥准破绽率步骑骤出猛扑断桥，孙权策马跃断桥方才脱险，张辽威震江东。"],"history":"公元二一五年秋，孙权趁曹操远征汉中、淮南兵力空虚，亲统江东大军北围重镇合肥。曹操行前留函教，命张辽、李典出战，乐进守城。张辽与李典捐弃私怨，连夜募得敢死锐士，天明突袭江东前营直扑孙权麾盖挫夺敌气；待孙权久围疫起退兵，张辽复于逍遥津渡口追袭，险些生擒孙权。","sources":"三国志·魏书·张乐于张徐传；资治通鉴·汉纪五十九"},
    "lu_zhangliao@207": {"strategic":["公元二〇七年秋，河北残余势力远奔塞外投靠辽西乌桓单于蹋顿，屡屡引胡骑南下寇边。丞相曹操采纳奇计远征塞北，因滨海大道秋雨泥泞，遂听从乡导改走荒废已久的卢龙塞险谷潜师出奇；荡寇将军张辽随前锋疾进，在白狼山猝遇蹋顿主力大军。"],"tactical":["白狼山峰峦峥嵘，俯瞰柳城要道。当时曹军辎重尚落在后方山谷，前锋兵少，漫山乌桓铁骑蜂拥而来，诸将相顾失色；唯张辽斗志昂扬，力谏趁蹋顿阵形未整迎头决战。曹操壮其胆略，当即将麾下帅旗亲授张辽；张辽挥精骑自山坡雷霆般俯冲直捣中坚，乌桓骑阵大乱，张辽临阵斩杀蹋顿，一战荡平三郡乌桓。"],"history":"东汉建安十二年秋，丞相曹操采郭嘉遗计远征投奔三郡乌桓的袁尚、袁熙，听田畴向导弃滨海泥淖改走卢龙塞险道奇袭柳城。八月曹军前锋登白狼山，猝与乌桓单于蹋顿及袁尚主力相遇，曹军辎重在后兵少，诸将皆惧。荡寇将军张辽慷慨力劝决战，曹操授以帅麾，张辽率虎豹骑猛冲阵斩蹋顿，彻底平定乌桓。","sources":"三国志·魏书·张乐于张徐传"},
    "lulin_liuxiu": {"strategic":["公元二三年，天下纷起反莽，汉军攻克重镇宛城；王莽震恐，命大司徒王寻等尽发州郡重兵携猛兽南下，将汉军前哨昆阳围得水泄不通。城中诸将欲散，偏将军刘秀力陈散必俱灭、守可共全，安抚守军固守，自率轻骑乘夜出城调援。"],"tactical":["昆阳城小而坚，王寻大军连营环绕，攻车地道昼夜猛扑。刘秀星夜收调外县援兵杀回昆阳，亲统精锐前锋屡挫新军外围，随即乘胜直捣王寻本阵；王寻轻敌自领阵兵迎战，当场被刘秀冲垮斩杀。城内守军亦鼓噪杀出合击，恰逢狂风雷雨、滍水暴涨，新朝主力溺毙溃散殆尽，新莽政权旋即倾覆。"],"history":"公元二三年，更始汉军北取宛城震动关中，新朝王莽遣大司徒王寻与王邑尽发州郡精兵驱猛兽南下，合围汉军孤城昆阳。诸将惶惧欲散，偏将军刘秀力劝固守待援，乘夜突围调集郾城、定陵援兵回救，亲率敢死前锋直冲王寻中坚阵斩王寻，借狂风骤雨大破新军，新朝遂亡。","sources":"后汉书·光武帝纪上；资治通鉴·汉纪三十一"},
    "lulin_liuxiu@24": {"strategic":["公元二四年春，河北风云骤变，卜者王郎诈称汉成帝遗嗣在赵都邯郸称帝，幽冀豪强纷起响应，持节北渡的刘秀一度陷于孤危南奔信都。刘秀沉着收拢信都、和戎义兵反击，更得上谷、渔阳精锐突骑南下会师，声势复振，遂挥师直指王郎盘踞的邯郸。"],"tactical":["邯郸乃战国名都，城垣高厚、粮械充盈，王郎见外围郡县尽失，困守孤城遣使乞降遭拒。刘秀督汉军与幽州突骑四面筑围，昼夜急攻二十余日；城中王郎心腹少傅看透败局，暗开城门内应迎入汉师。刘秀大军潮水般涌入邯郸，王郎乘夜仓皇突围出逃，在半途被汉骑追及斩杀；河北大定，刘秀由此奠定东汉帝业根基。"],"history":"更始元年冬十二月，邯郸卜者王郎诈称汉成帝子子舆，在赵豪刘林拥立下于邯郸称帝建赵，幽冀州郡多望风响应，持节北渡的刘秀一度困迫自蓟南奔信都。更始二年春刘秀发信都、和戎精兵连克巨鹿郡县，并纳耿弇之援会合上谷、渔阳突骑，五月进围邯郸，攻拔城池斩杀王郎，奠定河北王业。","sources":"后汉书·光武帝纪上"},
    "lulin_liuxiu@27": {"strategic":["公元二七年春，曾攻入长安的赤眉军统帅樊崇因关中赤地饥荒、又遭汉将屡挫，遂拥立傀儡幼帝弃长安引大军东归山东故土。东汉光武帝刘秀算定赤眉必走洛阳南路，一面令前线大将在崤底重创其锋，一面亲统六军精锐进屯宜阳，迎头锁死樊崇归路。"],"tactical":["宜阳控扼洛水河谷与崤函东口，群山夹束、无路可绕。樊崇率刚在崤底惨败、饥寒交迫的赤眉余部踉跄东出山谷；抬眼望见刘秀亲督的汉军甲光耀日、旌旗蔽野，严整大阵已将河谷出口堵得水泄不通。赤眉将士胆裂魂飞再无战心，樊崇穷途末路，只得肉袒率众奉上传国玉玺请降；刘秀受降不杀，赤眉大乱自此平定。"],"history":"东汉建武二年冬，攻灭更始政权入据长安的赤眉军统帅樊崇等因关中饥荒且受冯异打击，拥刘盆子弃长安引大军东归山东。光武帝刘秀预遣诸军分屯新安、宜阳塞其归路。建武三年春闰正月，冯异大破赤眉于崤底，刘秀亲统六军严阵迎截赤眉余众于宜阳，赤眉震怖穷蹙，樊崇偕刘盆子肉袒奉传国玺绶出降。","sources":"后汉书·刘盆子列传"},
    "maqidun_craterus": {"strategic":["公元前三二二年，亚历山大骤逝引发希腊诸邦起义，雅典统帅安提菲卢斯率联军北上围困马其顿摄政。奉遗命率东方退伍老兵返乡的名将克拉特罗斯闻讯渡海驰援；他与友军会师并谦让帅位，两部精锐南下色萨利克兰农平原，迎战安提菲卢斯。"],"tactical":["克兰农平原开阔起伏，南倚高丘，安提菲卢斯知公民步兵难敌老兵，将胜算押于色萨利骑队。开战后希腊骑队果在平原占优；克拉特罗斯毫不动摇，督厚重的长矛方阵全线推进，迎面碾退希腊步阵迫其逃上山丘，希腊骑队只得撤回护阵。安提菲卢斯孤立乞和，克拉特罗斯坚持逐邦单独议和拆散同盟，稳固了马其顿统治。"],"history":"公元前三二三年亚历山大逝世，雅典联诸邦发动拉米亚战争围困马其顿本土摄政安提帕特。正率退伍老兵西归的名将克拉特罗斯渡海驰援，于前三二二年八月会合安提帕特，在色萨利克兰农平原以重装方阵击退雅典统帅安提菲卢斯步阵，拆散希腊同盟并终结雅典民主政体。","sources":"西西里的狄奥多罗斯·历史丛书·第十八卷；普鲁塔克·福基翁传"},
    "maqidun_craterus@-326": {"strategic":["公元前三二六年，马其顿军踏入印度河流域，海达斯佩斯河东岸的波罗婆王波鲁斯拒不臣服，集步骑与战象严守渡口。时值盛夏雨季河水暴涨，战马畏象难行正面强渡；大将克拉特罗斯受命执掌西岸主营重兵，连日隔河喧嚣佯动，牢牢吸住波鲁斯主力视线。"],"tactical":["海达斯佩斯河宽水急，波鲁斯列战象于东岸正对克拉特罗斯大营。上游偷渡得手后，波鲁斯果真调走战象主力北上迎战，仅留偏师守滩。克拉特罗斯见对岸巨象北移，立督蓄锐已久的骑队与重装方阵乘船强渡激流，冲垮滩头守敌后直插主战场背后；苦战力竭的印军腹背受击大溃，波鲁斯被俘，旁遮普遂告平定。"],"history":"公元前三二六年五月，马其顿军抵海达斯佩斯河西岸，波罗婆国王波鲁斯率战象与步骑严守东岸。大将克拉特罗斯受命统大营留守正面渡口张扬旗鼓，牵制波鲁斯视线以掩护上游夜渡；待波鲁斯倾军北迎亚历山大之际，克拉特罗斯挥生力军强渡大河自背后痛击印军，铸就完胜。","sources":"阿里安·亚历山大远征记·第五卷；普鲁塔克·亚历山大传"},
    "mi_chu_xionglv": {"strategic":["公元前五九七年，晋楚围绕中原枢纽郑国激烈争锋，楚庄王熊旅亲统楚师围迫郑国降楚。晋中军元帅荀林父救郑行至黄河，闻郑已服楚本欲引还，副帅先縠却违命擅渡黄河，迫使晋军全师南渡屯于邲地。熊旅侦知晋军将帅失和、进退狐疑，当即挥师北上进逼郑郊邲地。"],"tactical":["郑郊邲地北靠黄河，荀林父背水扎营，诸将战和不一、戒备松懈。恰逢晋将擅赴楚营挑衅，晋营发车接应扬起漫天尘土；熊旅登车望见晋营纷乱，断定其号令分裂，立挥楚军分路突击。晋军未及成列便遭楚车骑席卷，荀林父慌令抢渡黄河，溃兵争舟自相斫指；熊旅饮马黄河，一战确立楚国中原霸业。"],"history":"公元前五九七年夏，楚庄王熊旅围郑迫其降楚，晋中军元帅荀林父救郑迟至黄河欲还，中军佐先縠违命独渡，晋军被迫全军南渡屯于郑郊邲地。和谈之际晋将挑衅破局，熊旅乘晋军将帅失和、未及成列发动突袭，晋军大溃争舟渡河，楚国一战夺得中原霸权。","sources":"左传·宣公十二年；史记·楚世家"},
    "murong_murongke@356": {"strategic":["公元三五六年，割据青州的段部鲜卑首领段龛依附东晋，公然致书非议前燕称帝，挑衅河北霸权。前燕朝廷特命百战百胜的大司马太原王慕容恪挂帅东征；段龛不听胞弟拒守黄河渡口之谏，坐放燕军安然济河，慕容恪遂连克外城直逼青州坚城广固。"],"tactical":["广固依托尧山、四周深涧阻隔，城高池深难于急拔。慕容恪先在淄水原野一战击溃段龛出迎主力，将其残众锁入广固孤城；随即不贪强攻之功，在城外高筑重墙、深挖长壕，一面从容农耕招抚齐地百姓，一面击败赶来救援的东晋偏师。长期铁桶围困至寒冬城中粮尽绝望，段龛被迫开门面缚出降，齐鲁大地尽入前燕版图。"],"history":"前燕元玺四年冬，割据青州受东晋封齐公的段部鲜卑首领段龛致书非议前燕帝慕容隽称帝，慕容隽命太原王大司马慕容恪统兵渡河讨段龛。段龛不听弟段羆拒守黄河之谏，慕容恪安渡济河于淄水大破段龛主力，进围险城广固。元玺五年秋慕容恪击败东晋荀羡援军，高墙深堑困至十一月城中人相食，段龛出降，齐地悉平。","sources":"晋书·慕容隽载记"},
    "nabatai_aleitasi": {"strategic":["公元前六五年，犹太哈斯蒙尼王朝兄弟争位；被少弟阿里斯托布鲁斯二世废黜的兄长逃往佩特拉，许割边城恳请纳巴泰王国助战。纳巴泰王阿雷塔斯抓住北扩良机，亲统沙漠驼骑劲旅北上，直扑阿里斯托布鲁斯二世据守的耶路撒冷。"],"tactical":["耶路撒冷山城险峻，圣殿山壁垒森严。阿雷塔斯先在野战中凭迅捷骑兵击溃敌军；众多犹太士卒倒戈，阿里斯托布鲁斯二世仅率亲信祭司退锁圣殿山固守。阿雷塔斯合城中拥长派民众将圣殿山团团围困，断绝粮水；孤垒垂破之际罗马东征军介入威逼退兵，阿雷塔斯遂撤军归国，犹太自此渐入罗马控制。"],"history":"公元前六五年，犹太哈斯蒙尼王朝兄弟争位，长兄希尔卡努斯二世被弟阿里斯托布鲁斯二世废黜后逃奔佩特拉，许割边城换取纳巴泰王阿雷塔斯助战。阿雷塔斯亲统骆驼与轻骑大军北上击败阿里斯托布鲁斯二世，将其围困于耶路撒冷圣殿山数月，直至罗马干涉方解围。定值：年份取前六五年。","sources":"约瑟夫斯·犹太古史·第十四卷；约瑟夫斯·犹太战记·第一卷"},
    "najie_minande": {"strategic":["约公元前一五五年，统治西北印度的印度希腊国王米南德锐意开疆，统合希腊长矛方阵与本土战象沿恒河谷地大举东进。新兴的巽伽王朝震动，遣皇孙统帅婆苏密多罗率重兵西向反击，两强主力围绕旁遮普重镇萨迦拉与河谷防线展开激烈交锋。"],"tactical":["萨迦拉外围平畴辽阔、五河支流纵横，极利大军团骑步展开。婆苏密多罗率巽伽车骑猛攻希腊边防，企图夺回西北旧疆；米南德依托萨迦拉坚固后方，以严密长矛方阵正面顶住敌军冲击，同时挥动巴克特里亚精骑自两翼高速包抄。双方激战互有进退，米南德牢牢守住旁遮普富庶疆域，将印度希腊王国的声威推向极盛。"],"history":"约公元前一五五年，统治巴克特里亚与旁遮普的印度希腊国王米南德统马其顿式长矛方阵、战象与轻骑沿恒河东征，回固西北大本营萨迦拉及印度河支流一带时，与取代孔雀王朝的巽伽帝国统帅婆苏密多罗激战，稳固印度希腊王国对旁遮普的统治。定值：年份估算取前一五五年。","sources":"斯特拉波·地理志·第十一卷；弥兰王问经；摩罗维迦与火友王"},
    "nanyue_zhaotuo": {"strategic":["公元前二一四年，秦军初征岭南百越受挫，西瓯部族首领桀骏诱敌深入山林断粮反击，秦前任主帅战死。秦廷开凿灵渠打通湘漓水运粮道，增遣任嚣与猛将赵佗统军再下五岭；赵佗进据东江上游要冲龙川，与桀骏统领的西瓯部众展开决战。"],"tactical":["岭南龙川至番禺间崇山密林交错、瘴疠湿热，桀骏率西瓯劲卒凭溪谷丛林设伏袭扰。赵佗依托灵渠源源水运稳扎营寨，一面抚纳越人熟悉山径，一面分遣轻装锐士配强弩水陆搜剿，诱出西瓯主力正面合击。激战中秦军阵斩西瓯首领桀骏，一举荡平岭南置设郡县；赵佗坐镇龙川继迁番禺和辑百越，奠定日后南越立国根基。"],"history":"秦始皇初遣屠睢南征百越，遭西瓯首领译吁宋即桀骏入丛林夜袭断粮击杀。秦廷凿通灵渠运粮，增遣任嚣与赵佗再征岭南；公元前二一四年秦军击斩西瓯首领桀骏，平定岭南置南海、桂林、象郡，赵佗镇龙川并经营番禺，秦末创立南越国。定值：年份取前二一四年。","sources":"史记·南越列传；淮南子·人间训；资治通鉴"},
    "pajiama_oumainisi": {"strategic":["公元前二六二年，小亚细亚山城帕加马在新主欧迈尼斯治下谋求摆脱宗主自立，暗通埃及。急于重振西疆威权的塞琉古国王安条克一世决不容附庸背离，亲统大军推进至吕底亚重镇萨第斯欲荡平帕加马；欧迈尼斯拒坐困孤城，重赏雇佣精兵主动南下迎战。"],"tactical":["萨第斯城外河谷与丘陵相接，安条克一世仗兵众列开重装方阵，然塞琉古军久疲于战事且宫廷新乱，锐气已衰。欧迈尼斯麾下雇佣劲旅粮足操熟，依起伏地形避开敌正面锋芒，集精骑与轻盾步卒高速迂回，猛冲安条克一世侧翼接合部。塞琉古军侧翼崩乱全线惨败，欧迈尼斯凯旋扩土，正式确立帕加马独立强邦之位。"],"history":"公元前二六二年，新继位的帕加马统治者欧迈尼斯谋求脱离塞琉古宗主自立，塞琉古国王安条克一世亲率帝国大军进至吕底亚首府萨第斯讨伐。欧迈尼斯不待敌军压境围城，重赏常备雇佣精兵主动南下，在萨第斯城下野战击败安条克一世，确立帕加马独立地位。","sources":"斯特拉波·地理志·第十三卷；阿庇安·叙利亚战记"},
    "pulei_dougu": {"strategic":["公元七三年，东汉历经明章休养国力充盈，面对北匈奴连年铁骑南下寇掠河西城邑，汉明帝决意大举出塞反击。名门良将窦固受拜奉车都尉，统领酒泉、敦煌、张掖精锐甲骑出塞北进，跨越瀚海直扑北匈奴呼衍王游牧的天山蒲类海。"],"tactical":["天山北麓蒲类海雪峰倒映、水草丰茂，乃北匈奴控扼西域东门的战略牧场。呼衍王未料汉军竟敢在初春越漠远袭，仓促聚拢控弦骑群迎战。窦固督率久习塞外骑战的河西铁骑与羌胡义从迎面猛冲，铁蹄雷鸣撕裂敌阵，一路追奔逐北重创呼衍王主力；窦固乘胜夺占膏腴重地伊吾卢筑城留兵屯田，自此重开东汉经营西域之门。"],"history":"公元七三年春，东汉明帝决意反击连年寇边的北匈奴，命四路大军出塞。奉车都尉窦固率河西甲骑与羌胡兵出酒泉塞，长驱至天山蒲类海击败北匈奴呼衍王，追斩甚众，乘胜进占西域门户伊吾卢并置宜禾都尉屯田，重开东汉通西域之路。","sources":"后汉书·窦融列传；资治通鉴·汉纪三十九"},
    "pulei_dougu@74": {"strategic":["公元七四年冬，东汉明帝决意彻底斩断北匈奴控驭西域的触角，再命奉车都尉窦固总统诸军出敦煌昆仑塞远征。车师国扼守天山南北孔道，后王安得久恃匈奴奥援与北道山险拒不归附；窦固先在蒲类海畔击破匈奴援骑，随挥铁骑翻越天山直扑安得驻地。"],"tactical":["车师后部深藏东天山北麓务涂谷地，雪岭重重、道途幽险，安得原以为汉军断难越山远袭。窦固与副帅督汉家铁骑冒严寒强越雪山隘口，旌旗鼓角骤然出现在山谷之前，先声夺人击溃外围阻截游骑，重兵直压后王庭帐。安得见匈奴外援已绝、汉骑兵威压顶，惊骇之下肉袒迎降；东汉遂复置西域都护与戊己校尉镇抚天山。"],"history":"东汉永平十七年冬十一月，汉明帝命奉车都尉窦固总统驸马都尉耿秉、骑都尉刘张率铁骑出敦煌昆仑塞再征西域。窦固先于蒲类海畔击破北匈奴白山部，随即挥师翻越东天山进讨依附匈奴的车师国。窦固与耿秉径趋车师后王安得所居务涂谷，大震军威迫降车师后王安得与前王，复置西域都护与戊己校尉。","sources":"后汉书·窦融列传"},
    "qi_tianji": {"strategic":["公元前三四二年，魏国倾师猛攻弱韩以图独霸中原，齐王深知唇亡齿寒，复拜功臣田忌挂帅出征。田忌统齐国精锐西出临淄，避开韩境攻坚，轻装疾插魏国要害大梁；魏帅庞涓被迫放弃攻韩战果火速回师，田忌遂按方略引军移向齐魏边境马陵道。"],"tactical":["马陵道山路蜿蜒、谷深林幽，乃天然伏兵绝地。田忌严整约束齐军东撤，沿途逐日减灶示弱，诱轻敌冒进的庞涓撇下步阵孤军追入隘口。田忌早已督齐军主力在谷道尽头与两侧高坡伐木断路、张弩待敌；当夜庞涓入伏举火看字，田忌令四周伏弩齐鸣，步骑掩杀全歼敌前锋，庞涓自刎，田忌乘胜俘魏太子，齐国雄踞东方。"],"history":"公元前三四二年，魏国攻韩，齐威王拜田忌为主帅、孙膑为军师直趋大梁救韩。田忌配合减灶诱敌之策严整东撤，将魏帅庞涓诱入马陵道伏击全歼，乘胜再破魏后续大军并俘魏太子申，摧毁魏国霸业。定值：同场三行统一取前三四二年、战场马陵道。","sources":"史记·田敬仲完世家；史记·孙子吴起列传"},
    "qi_tianji@-353": {"strategic":["公元前三五三年，魏国四面征伐，大将庞涓久围赵都邯郸，齐国西境亦受威胁。齐王拜宗室名将田忌挂帅救赵；田忌从善如流，采纳军师避实击虚奇谋，舍赵境而挥师直插魏国腹心大梁。前线庞涓惊闻老巢告急，果撤赵围南返，田忌遂统齐师提前移屯桂陵待敌。"],"tactical":["桂陵横锁南北驿路，林丘起伏，极利阻击运动之敌。田忌将战车重步布于大道高地，分遣劲卒潜伏两翼沟林，严令全军寂然待命。未几庞涓督奔波疲惫的魏师赶抵，行军队列散乱脱节；田忌看准敌军喘息未定，亲擂战鼓挥中坚猛压、两翼合围，一举冲垮魏武卒并活捉庞涓，奠定齐魏平分秋色之势。"],"history":"公元前三五三年，齐宗室名将田忌挂帅救赵，虚心采纳门客军师孙膑围魏救赵之计，挥师西击魏国腹地诱魏帅庞涓回师。田忌统齐军主力抢占桂陵设伏截击，击溃疲敝魏军并生擒庞涓，扭转魏国独霸中原之局。定值：同场三行年份统一取前三五三年。","sources":"史记·田敬仲完世家；史记·孙子吴起列传"},
    "qiliqiya_pangpei": {"strategic":["公元前六六年，罗马共和国授名将庞培东方最高兵权，以终结本都战事。庞培先结好安息锁死亚美尼亚外援，随统优势军团步步紧逼；本都王密特里达梯避战东退至河谷，庞培抄近道抢占周遭险要高地，将其困于尼科波利斯谷地。"],"tactical":["尼科波利斯群山环锁，密特里达梯误率全军扎营于狭窄洼谷。入夜皓月西斜，庞培督罗马军团自西面高坡背月向下奇袭；低悬月光将罗马兵身影长长投至谷底，惊醒的本都弓手误将黑影当作敌兵纷纷提前射空箭矢，转瞬罗马重步兵已贴身杀入。本都军在狭谷暗夜中大溃，密特里达梯北逃黑海，小亚细亚尽归罗马。"],"history":"公元前六六年，获授东方全权的罗马统帅庞培结盟安息牵制亚美尼亚，亲率大军东进追剿本都王密特里达梯。密特里达梯退入利库斯河险狭山谷夜营；庞培绕道抢占周边高地，乘月落西山背月发起夜袭，月光拉长罗马兵身影致本都军射空溃败，密特里达梯北逃黑海，庞培建胜利城尼科波利斯。","sources":"普鲁塔克·庞培传；阿庇安·密特里达梯战争史"},
    "qiliqiya_pangpei@-48": {"strategic":["公元前四八年，罗马共和国内战进入白热关头，元老院统帅庞培在海岸重创恺撒后，统领兵力与骑兵皆占优的大军追入色萨利。庞培本欲凭海权断粮将对手活活困死，怎奈随营元老权贵骄狂催战，庞培被迫在法萨卢斯平原列开大阵与恺撒决一雌雄。"],"tactical":["法萨卢斯平原南依埃尼佩乌斯河，庞培以右翼依托河岸，将精锐骑兵尽集左翼企图包抄敌阵。开战后庞培铁骑果然压退敌骑，正欲转向卷击之际，突遭恺撒隐蔽在右后的斜列步兵端重标枪迎面猛刺面门；贵族骑兵惊骇溃散，致使庞培左翼彻底暴露，面对敌军三面合击大阵崩溃，庞培败逃埃及遇害。"],"history":"公元前四八年八月九日，罗马内战期间，在都拉基乌姆重创恺撒并断其海路补给的元老院统帅庞培率优势大军追入色萨利法萨卢斯平原。庞培本欲继续断粮困死恺撒，怎奈随军元老权贵骄狂催战；决战中庞培右翼靠河，将绝对优势骑兵尽集左翼企图包抄恺撒右翼，不料遭恺撒预设的第四线斜列步兵持重标枪迎面捅刺溃散，侧背失守全军败溃，庞培逃往埃及遇害。","sources":"恺撒·内战记·第三卷；普鲁塔克·庞培传；阿庇安·内战史"},
    "qiliqiya_pangpei@-63": {"strategic":["公元前六三年，罗马统帅庞培荡平叙利亚后进驻大马士革，裁处犹太哈斯蒙尼王朝兄弟争位之乱。少弟阿里斯托布鲁斯二世不满罗马偏向其兄，表面虚与委蛇，暗中退回耶路撒冷整军备战；庞培洞悉其诈，当即统罗马军团南下进逼耶路撒冷城下。"],"tactical":["耶路撒冷圣殿山三面深谷绝壁，唯有北侧稍通陆路。阿里斯托布鲁斯二世出营被扣后，其死党拆毁石桥据守圣殿山顽抗，城内拥兄派则开外城迎入罗马军。庞培察知守军恪守安息日不主动出击的宗教旧规，每逢安息日便从容填谷筑台；随后运来攻城槌与投石机轰塌北塔强攻入殿，犹太自此归入罗马版图。"],"history":"公元前六三年，进驻大马士革经略叙利亚的罗马统帅庞培裁决犹太哈斯蒙尼兄弟王位之争，阿里斯托布鲁斯二世因不满庞培偏向其兄希尔卡努斯二世，屡次首鼠两端，虽在兵临城下时出营被扣，其死忠党羽仍闭圣殿山拒守并毁桥断路。庞培入外城后利用犹太人安息日不主动进攻的习俗在北面填深谷筑高台，运来推罗重型投石机与攻城槌轰塌塔楼强攻破殿，犹太自此沦为罗马附庸。","sources":"约瑟夫斯·犹太古史·第十四卷；狄奥·卡西乌斯·罗马史·第三十七卷"},
    "qin_hengyi": {"strategic":["公元前二三三年，前岁刚在平阳破赵斩将的秦国猛将桓齮乘胜再举；他避开邯郸南面坚防，率师自上党翻越太行险道插向赵都东北，连拔赤丽、进逼宜安与肥下。赵廷震恐，急从抗匈前线召回名将李牧拜大将军，赶赴前线迎堵桓齮。"],"tactical":["肥下毗邻滹沱河原野，背靠太行丘陵。桓齮挟胜威屡赴赵垒搦战速决，李牧却深沟高垒严禁出战；桓齮久攻无果，认其怯战，遂亲率主力离宜安大营东攻肥下，欲逼赵军分救。岂料李牧乘虚奇袭攻陷秦军空虚老营、尽夺辎重，并在肥下张开两翼口袋；桓齮急返救应撞入重围全军溃败，仅率亲随突围逃归。"],"history":"公元前二三三年，秦大将桓齮乘平阳大胜之势东越太行山再攻赵国，拔赤丽、逼宜安。赵王急调北边名将李牧拜大将军南下御敌；李牧筑垒坚守不出麻痹秦军，桓齮久攻不下遂分兵东取肥下，大营空虚遭李牧奇袭攻破，回救途中于肥下中两翼合围惨败，仅以身免。","sources":"史记·廉颇蔺相如列传；史记·秦始皇本纪；战国策·赵策"},
    "qin_hengyi@-234": {"strategic":["公元前二三四年，秦王亲政后掀起东并六国之势，北方赵国适逢国丧，幼主嗣位、奸臣弄权，宿将或流亡或远戍北疆。秦大将桓齮奉命统虎狼之师北渡漳水，猛刺赵南门户平阳；赵廷惊惶命将领扈辄率军南下迎堵，两军主力对撞于平阳原野。"],"tactical":["平阳位于邯郸以南漳水原野，无险可凭。扈辄缺乏统御大军野战之略，既未依漳水筑垒挫敌锐气，反驱赵军在城外旷野与秦师硬拼。桓齮看准赵阵呆板、侧翼单薄，亲擂战鼓催铁骑锐士猛冲扈辄中军，配合两翼包抄瞬间撕裂敌阵；赵军大溃，扈辄战死沙场，桓齮踏平平阳，逼赵廷急召北边名将救亡。"],"history":"公元前二三四年，秦王嬴政乘赵悼襄王新丧、少主初立且名将不在朝之机，命大将桓齮率主力攻赵，渡漳水进逼平阳与武城。赵王派宠臣郭开举荐的扈辄统军南援，桓齮在平阳城外野战击溃赵军主力，阵斩赵帅扈辄，洞开邯郸南门。定值：敌将取赵帅扈辄。","sources":"史记·秦始皇本纪；史记·赵世家；资治通鉴"},
    "qin_simacuo": {"strategic":["公元前三一六年，秦岭以南古蜀内乱，蜀王芦子霸王兴兵攻弟苴侯，巴蜀竞相向秦求援。秦廷议兵，大将司马错力排伐韩之议，指出取巴蜀既得广土富国，又可顺水东下拊楚之背；秦王纳策，命司马错统秦师循石牛栈道南下，直扑蜀北锁钥葭萌关。"],"tactical":["葭萌关雄踞崇山急水之间，栈道高悬，蜀王芦子霸王闻秦军南下，急统蜀军主力北上据关迎敌。古蜀久安盆地，甲兵战阵远逊久历关中血战的秦国锐士；司马错出栈道后乘苴巴倒戈接应之机，集强弩锐卒猛攻关防，连战连捷夺下葭萌关。芦子霸王南逃途中被追兵击杀，司马错顺势兼并巴蜀沃野，筑牢秦并天下之基。"],"history":"公元前三一六年，古蜀王芦子霸王与弟苴侯相攻，巴蜀苴皆求救于秦。秦廷廷议，司马错力驳张仪伐韩之议，主张先取富庶巴蜀以资国力、占对楚上游。秦惠文王遣司马错等率军循石牛道南下，攻破葭萌关，击杀芦子霸王，灭蜀兼巴。定值：守方国号定为古蜀。","sources":"战国策·秦策一；史记·张仪列传；华阳国志·蜀志"},
    "qin_simacuo@-280": {"strategic":["公元前二八〇年，秦经营巴蜀已成富饶后方，楚顷襄王虽重兵防范秦军北线通道，西南武陵黔中山地却恃险空虚。秦王决意兑现得蜀则得楚之略，诏元勋老帅司马错再度挂帅；司马错合陇西与巴蜀劲旅造楼船载粮，避开三峡险滩，循涪水南插武陵水道直扑楚国黔中。"],"tactical":["黔中群峰叠嶂，沅酉急流穿谷而过，楚顷襄王在西南边郡仅置常戍，未料秦军竟携大船翻山自上游天降。司马错统水陆劲旅顺流疾下，势若高屋建瓴；正面楼船抢滩夺渡，巴蜀锐士攀崖绕袭山寨后背，水陆夹击连破沿江防线，一举攻拔黔中全郡。郢都侧翼洞开，楚顷襄王惶惧割汉北上庸乞和，为日后秦破郢都铺平道路。"],"history":"公元前二八〇年，秦昭襄王启用灭蜀元勋老将司马错，发陇西与巴蜀水陆大军造大船载粮，自涪水、乌江越武陵山脉顺沅水奇袭楚国西南屏障黔中郡。楚顷襄王猝不及防，黔中陷落，被迫割汉北及上庸之地向秦求和，兑现了司马错早年得蜀即得楚之策。定值：敌将取楚顷襄王。","sources":"史记·秦本纪；史记·楚世家；华阳国志·蜀志"},
    "qingqiang_jiangwei": {"strategic":["公元二五五年秋，曹魏权臣新死、洛阳政局动荡；蜀汉卫将军姜维力排廷臣阻议，统诸军自枹罕挥师北伐，兵锋直指陇西重镇狄道。曹魏雍州刺史王经驻节狄道，不听主帅按兵待援的训令，自恃精兵在握，贸然率军西渡洮水主动迎击姜维。"],"tactical":["狄道城西洮水奔腾湍急，西岸故关背靠陡山，一旦战败则退路全阻于大河。王经孤军渡水求战，姜维看准魏军背水无退的死地态势，先稳住阵脚顶住敌锋，随即亲督蜀汉精锐自高坡全力反冲猛压。魏军阵线崩裂争相向东逃奔，在洮水渡口自相践踏溺毙蔽河；王经仅携残部狼狈退锁狄道孤城，姜维创下北伐最辉煌大捷。"],"history":"公元二五五年秋，蜀汉卫将军姜维乘曹魏大将军司马师病亡之机，率夏侯霸、张翼出枹罕北伐狄道。曹魏雍州刺史王经违背主帅陈泰合兵固守之令，擅率主力西渡洮水迎战；姜维于狄道城西故关背山列阵大破魏军，王经军争渡溺亡洮水无数，仅率残骑逃入狄道孤城。定值：战场改定为狄道。","sources":"三国志·蜀书·蒋琬费祎姜维传；三国志·魏书·诸夏侯曹传"},
    "qingqiang_jiangwei@256": {"strategic":["公元二五六年夏，新晋蜀汉大将军姜维志在克复中原，自钟题拔营北伐；原定出祁山直取麦熟粮丰的上邽，并与汉中友军约期会师。岂料曹魏安西将军邓艾早已算破蜀军行止，预先抢占武城山与上邽诸险，迫使姜维改道东趋南安段谷。"],"tactical":["段谷位于渭水支流峡谷，群山夹峙、溪谷狭窄，北山高阜俯控全谷通路。姜维督师长途转战至此，约期会合的友军却失期未至，孤军顿陷被动；邓艾早已派精兵抢占段谷两侧山岭设伏，趁蜀军行进队列拉长、人困马乏之际居高四面猛扑。姜维奋力搏战仍难挽败局，蜀军伤亡惨重败退汉中，姜维痛心上表自请贬官谢罪。"],"history":"三国蜀汉延熙十九年夏秋，刚升任大将军的姜维自钟题再举北伐，原拟出祁山趋天水上邽，与镇西大将军胡济相约会师。曹魏安西将军邓艾精准预判姜维进军路线，预先抢占武城山与上邽诸险，姜维被迫改道东出董亭趋南安，胡济失期不至，七月姜维于天水西南段谷遭邓艾居高伏击大败，上表自贬后将军。","sources":"三国志·蜀书·蒋琬费祎姜维传"},
    "qingqiang_jiangwei@263": {"strategic":["公元二六三年秋，曹魏大举兴兵伐蜀，汉中关城因守将变节迅速陷落，魏镇西将军钟会统主力长驱入汉中，蜀汉朝野震动。远在沓中屯田的蜀汉大将军姜维临危不乱，在阴平桥头巧设疑兵甩脱魏军围堵，星夜收拢汉中退兵，赶在钟会前头抢据天险剑门关。"],"tactical":["剑门关大小剑山绝壁中断如门，栈道悬于深涧之上。钟会统优势魏军追抵关下，先传檄招降遭拒，随即督重兵轮番仰攻关门；姜维会合诸将凭险列弩、滚木礌石如雨，把钟会大军死死钉在绝壁之外月余寸步难进。钟会粮尽正拟撤军，不料西路奇兵偷渡阴平迫降成都；投降敕令传至，姜维将士拔刀砍石含泪受命。"],"history":"三国蜀汉景耀六年秋，司马昭遣钟会、邓艾、诸葛绪大举伐蜀，汉中阳安关失守。身在沓中的大将军姜维巧破邓艾牵制，于阴平桥头虚张北出之势骗开诸葛绪，神速南撤与廖化、张翼、董厥会师退保剑阁天险。钟会统曹魏主力猛攻剑阁月余寸步难进，粮尽欲退，直至成都降邓艾敕至，姜维将士拔刀斫石含泪假降图复。","sources":"三国志·蜀书·蒋琬费祎姜维传"},
    "qu_d_quyi": {"strategic":["公元一九一年，汉末群雄并起，幽州公孙瓒挟平定乌桓之威南下冀州攻讨袁绍，郡县望风披靡。袁绍亲率主力进至清河界桥迎战；他命熟习凉州羌胡骑战的骁将麴义领精选先登死士与强弩居前，迎击公孙瓒前锋主将严纲。"],"tactical":["界桥横跨清河故道，两岸原野平旷。严纲统公孙瓒精锐白马义从与两翼铁骑呼啸冲向袁绍步阵，自认步卒见骑必溃。麴义严令先登死士尽数蹲伏于大盾之下纹丝不动，待敌骑逼至咫尺，麴义一声号令，士卒持戟狂呼跃起、强弩齐发攒射。白马义从人仰马翻，严纲当场被斩，麴义乘胜夺桥破营，一战折断幽州铁骑锋芒。"],"history":"公元一九一年冬，幽州公孙瓒借弟死之名大举南攻袁绍，冀州郡县多望风响应。袁绍自屯广川界桥南，命久习凉州战法的部将麴义领精选先登死士与强弩手居前；公孙瓒纵白马义从精骑冲阵，麴义伏盾牌后待敌逼近骤起攒射破骑，阵斩公孙瓒冀州刺史严纲，击溃瓒军。","sources":"后汉书·袁绍刘表列传；三国志·魏书·袁绍传"},
    "qu_d_quyi@195": {"strategic":["公元一九五年，幽州军阀公孙瓒残杀深得胡汉民心的州牧刘虞，激起幽州旧部与乌桓鲜卑联兵复仇，南迎袁绍大军共讨暴虐。袁绍特派曾在界桥大破白马义从的名将麴义统河北精兵北上，会合幽州复仇联军进抵渔阳，与亲率主力迎战的公孙瓒会猎鲍丘水。"],"tactical":["鲍丘水自塞外穿行燕山南流入海，水岸开阔宜于骑步决战。公孙瓒欲凭幽州劲骑一战打垮复仇联军以稳后方，挥军猛扑南岸；麴义久谙公孙瓒骑战路数，统河北强弩与长戟精卒稳守正面挫敌冲势，再与熟习骑射的乌桓鲜卑义骑两翼反包掩杀。公孙瓒主力大败溃散，自此胆寒不敢复出野战，退缩易京高筑重楼坐困待毙。"],"history":"东汉兴平二年，前将军公孙瓒攻杀深得幽州胡汉人心的幽州牧刘虞，刘虞旧部从事鲜于辅、齐周等推阎柔招集乌桓、鲜卑义从起兵复仇，迎刘虞之子刘和南联袁绍。袁绍遣大将麴义统河北劲旅北上与鲜于辅、刘和合兵，于渔阳鲍丘水南迎击公孙瓒主力，大破之，迫使公孙瓒退缩易京筑围自守。","sources":"后汉书·刘虞公孙瓒陶谦列传"},
    "quli_chentang": {"strategic":["公元前三六年，匈奴郅支单于杀害汉使后西奔康居，借康居兵威屡侵乌孙，于都赖水畔筑起郅支城妄图称霸西域。西域副校尉陈汤深知久延必致西域诸国动摇，趁长官卧病果断矫诏调发西域城郭诸国兵与屯田吏士，翻越葱岭万里远征郅支城。"],"tactical":["郅支城外立重木城栅、内筑坚厚土城，郅支披甲登城迎战。陈汤严整汉胡联军四面合围，命持大盾步卒居前、强弩手在后仰射压灭城头守兵，先拔外木城并击退来援的康居骑兵；入夜汉军四面堆柴纵火焚烧土城，冒烟焰登城搏杀，冲入内室斩下负伤的郅支首级。此战威震绝域，写就明犯强汉者虽远必诛的千古壮篇。"],"history":"公元前三六年，北匈奴郅支单于杀汉使西走康居，筑郅支城称霸西域北道。汉西域副校尉陈汤趁都护甘延寿卧病，果断矫制发西域诸国兵与屯田汉兵，分南北两道越葱岭会师康居，合围都赖水畔郅支城；汉军以盾弩破木城、纵火焚土城，斩郅支首级传诣长安，留下明犯强汉者虽远必诛名言。","sources":"汉书·傅常郑甘陈段传；资治通鉴·汉纪二十二"},
    "ranwei_d_ranmin": {"strategic":["公元三五〇年冬，猛将冉闵在邺城铲除后赵石氏自立为帝建立冉魏，河北局势剧震。残存襄国的后赵势力不甘覆亡，纠集后赵宿将张贺度与鲜卑、匈奴诸路渠帅会师昌城，浩浩荡荡逼向邺都东境；新朝初立四面受敌，冉闵披甲跨马亲统精锐东出，疾趋黄河古渡苍亭迎战张贺度。"],"tactical":["苍亭津控扼东郡黄河要渡，冬日河滩开阔，张贺度所统各族联军虽众却互不统属。冉闵素以勇力威慑胡羯，抵阵毫不迟疑，执双刃长矛亲率冉魏百战精骑直插敌阵中枢，以雷霆攻势先行斩杀联军悍将。后赵联军见冉闵神勇无匹顿失战心，阵线土崩瓦解，张贺度仓皇败逃，冉闵尽散其众，一战震慑河北群雄。"],"history":"公元三五〇年冬，冉闵于邺城诛除石氏建立冉魏，在襄国称帝的后赵主石祗联络旧将张贺度、段勤、刘国等会师昌城，合重兵南逼邺都。冉闵毫无惧色，亲统冉魏精锐步骑东渡迎击，于东郡黄河渡口苍亭津大破张贺度联军，阵斩大将，尽散其余众，稳固冉魏初立局面。定值：战场改定为苍亭。","sources":"晋书·石季龙载记下；资治通鉴·晋纪二十"},
    "ranwei_d_ranmin@351": {"strategic":["公元三五一年春，在邺城称帝建立冉魏的猛将冉闵为彻底铲除后赵残余，亲统大军北上重兵围攻后赵末主石祗据守的旧都襄国。围城百余日襄国旦夕将破，石祗不惜自去帝号，割地重赂向前燕与关陇羌帅急求外援；各路胡骑蜂拥赶至襄国城外合击冉闵。"],"tactical":["襄国西倚太行余脉，城外平原无险可凭，极利塞外骑兵包抄。面对前燕与羌胡援骑压境，谋臣力劝先固营垒挫其锐气，连胜骄狂的冉闵却执意倾营出战；交战方酣，城内石祗开门杀出，与城外铁骑对冉魏步阵形成内外夹击。冉闵虽勇猛冲杀仍难挡四面合围，全军惨败溃散，冉闵仅率随骑突围奔回邺城。"],"history":"公元三五〇年冬至三五一年春，冉魏皇帝冉闵亲统大军自邺城北围后赵末主石祗于旧都襄国即邢台百余日。石祗危急去帝号称赵王，向前燕慕容隽与羌帅姚弋仲乞师。三五一年三月前燕悦绾、羌将姚襄与石琨三路援军合逼襄国，冉闵不听王泰勿战之谏，出营遭内外夹击大败，仅十余骑奔还邺城。","sources":"晋书·石季龙载记下"},
    "ranwei_d_ranmin@352": {"strategic":["公元三五二年春，冉魏经历襄国重创后河北赤地千里、邺城粮尽，皇帝冉闵亲率步多骑少的精干主力北上常山、中山一带就粮。此时前燕名将慕容恪正统鲜卑铁骑主力南下经略冀州，闻讯兼程追截；两军主力在魏昌廉台原野迎面遭遇，生死决战一触即发。"],"tactical":["廉台林木与平畴相交，冉闵麾下多为百战步卒，慕容恪则全系塞外精骑。初交锋冉闵依傍丛林避敌骑冲，十战十捷挫败燕军前锋；慕容恪遂改用连环马奇策，用铁锁连马结成厚阵居中，先诱冉闵离林追入平地，再挥两翼铁骑合围。冉闵浴血突围，奈何胯下名马力竭暴毙，被燕骑生擒送往龙城就义。"],"history":"公元三五二年春，冉闵攻灭襄国刘显后因邺城周边饥荒，率步骑北上常山、中山一带征粮，与南下的前燕辅国将军慕容恪主力遭遇于魏昌廉台。冉闵初依丛林步战十战十胜，慕容恪以铁锁连马结方阵诱冉闵入平地两翼合围，冉闵顺风斩燕骑三百余级，突围东奔二十里战马朱龙暴毙被擒，慷慨就义于龙城。","sources":"晋书·石季龙载记下"},
    "ruo_wangjian": {"strategic":["公元前二二四年，秦军前番轻兵伐楚受挫，秦王亲赴频阳向告老宿将王翦谢罪，倾全国精兵交其统领南征。楚国亦尽起全境之师，由名将项燕统率迎战。王翦深知楚人剽悍利在速战，入楚境即扎下连绵坚营闭门不出，与项燕主力在淮北展开耐心较量。"],"tactical":["蕲县蕲南原野平阔，王翦每日优厚饮食抚慰将士，任项燕百般挑衅始终坚壁不战。相持逾年，王翦探知秦卒在营中投石超距、锐气盈溢，恰逢项燕粮乏拔营东撤；王翦看准战机尽发精兵全速追击，在蕲县蕲南趁敌行军未列猛冲楚阵。楚军主力土崩瓦解，项燕兵败自尽，秦一统天下之势自此无可阻挡。"],"history":"公元前二二五年李信伐楚败归，秦王亲赴频阳向宿将王翦谢过，倾全国精兵托付王翦再度南征。公元前二二四年，王翦屯兵淮北深沟高垒逾年不出，抚养士卒至投石超距思战；待楚大将军项燕粮乏东移之际，王翦尽发精锐尾击，于蕲县蕲南大破楚军逼死项燕，次年灭楚。","sources":"史记·白起王翦列传；史记·秦始皇本纪"},
    "ruo_wangjian@-227": {"strategic":["公元前二二七年，秦灭赵后大军进屯中山直逼燕南，燕太子丹惊惧之下遣刺客荆轲入咸阳行刺秦王未遂。秦王政震怒，增兵命老将王翦统师大举北伐；燕王与太子丹急合代地残军，倾举国之兵南下陈师于易水西岸迎战。"],"tactical":["易水横贯燕南原野，水寒岸阔，乃拱卫燕都蓟城的天然防线。太子丹与燕代诸将背水列阵，欲凭死志阻遏秦师北渡；王翦治军沉稳老辣，先以强弩战车压住燕军前锋锐气，待敌久战力竭，挥动秦军精锐强渡易水正面击穿中坚。燕代联军全线溃败，王翦乘胜长驱围拔蓟城，迫使太子丹与燕室残部远遁辽东。"],"history":"公元前二二八年王翦灭赵后屯军中山以临燕境，燕太子丹恐惧，于公元前二二七年遣荆轲携樊於期首级与督亢地图入秦刺秦王嬴政未遂。秦王大怒，命王翦与辛胜统大军北伐燕国；燕王喜与太子丹合逃亡代地的代王嘉联军于易水之西迎战，王翦正面大破燕代联军，次年十月攻拔燕都蓟城。","sources":"史记·秦始皇本纪；史记·刺客列传；史记·燕召公世家"},
    "ruo_wangjian@-228": {"strategic":["公元前二二八年，秦王政倾国伐赵，上将军王翦统主力下井陉与赵军相持经年。见赵将李牧壁垒难破，王翦密施反间买通赵王宠臣，诱赵廷自毁长城冤杀李牧、改命庸将赵葱代掌帅印；换将令下，王翦当即挥秦军进逼漳水东阳。"],"tactical":["东阳地处太行东麓与漳水冲积平原交界，失却良帅的赵军防线松动、士气低迷。赵葱仓促催动赵师迎战，企图稳住邯郸外围屏障；王翦看准敌军号令不一，集中秦军锐士正面猛扑撕裂赵阵，两翼车骑疾进合围。秦军一战阵斩赵葱、击溃赵师主力，旋即乘胜攻克邯郸生擒赵王，三晋强藩赵国主体自此覆亡。"],"history":"公元前二二九年秦大旱后兴兵灭赵，王翦统上地主力下井陉，杨端和围邯郸，赵派李牧、司马尚抵御相持。王翦施反间计重金收买赵王迁宠臣郭开，诬陷李牧谋反致其遇害，赵改以赵葱与齐将颜聚代掌兵权。公元前二二八年王翦猛攻大破赵军于漳水东阳一带，阵斩赵葱，攻克邯郸俘赵王迁，赵国主体覆灭。","sources":"史记·秦始皇本纪；史记·白起王翦列传；战国策·赵策四"},
    "ruzhou_sunjian": {"strategic":["公元一九一年春，董卓挟天子暴虐朝堂，关东诸侯结盟讨卓却多畏缩观望，唯破虏将军孙坚率军孤身北进河南。孙坚历经险战收拢部众进屯梁县阳人聚；董卓大惊，急遣胡轸、吕布与猛将都督华雄统西凉劲旅东出迎截，兵锋直扑阳人聚。"],"tactical":["阳人聚北通洛阳南门大谷关，形势冲要。西凉军主将与骑督素有嫌隙，抵城外时内部流言惊扰，士卒弃甲奔乱。孙坚在城中察知敌阵骚动，当即整肃部伍出城反击，先挫敌锋，随乘乱挥军全线掩杀；西凉军溃不成军，都督华雄混战中被孙坚生擒枭首。此战吓得董卓焚掠洛阳西遁长安，孙坚遂挺进汉室旧都。"],"history":"公元一九一年春，破虏将军孙坚率豫州兵北讨董卓，收散卒进屯梁县阳人聚。董卓遣胡轸为大督护、吕布为骑督，率都督华雄等进击阳人；胡轸与吕布失和内讧致军心大乱，孙坚据城严阵迎击大破西凉军，临阵枭杀都督华雄，逼董卓焚洛阳西迁长安。定值：战场定为阳人聚。","sources":"三国志·吴书·孙破虏讨逆传；资治通鉴·汉纪五十二"},
    "ruzhou_sunjian@184": {"strategic":["公元一八四年夏，南阳黄巾攻杀太守，推渠帅赵弘为主占据重镇宛城，声势震动荆豫。东汉朝廷命右中郎将朱儁统兵围剿，佐军司马孙坚亲募淮泗少年与江东子弟随军助战；因宛城坚厚久攻不下，朝议欲罢免主帅，孙坚遂请命担当先锋急攻赵弘。"],"tactical":["宛城乃南阳都会，城高池深，赵弘聚荆南黄巾精锐凭堞死守，矢石如雨。总攻令下，孙坚身披重甲、手执利刃，冒着密集飞矢礌石身先士卒攀梯蚁附，率先跃上宛城女墙砍翻守敌；城下汉军见孙坚孤身登城浴血搏杀，士气大振，争相攀城涌入缺口。黄巾防线土崩瓦解，孙坚在巷战乱军中亲手斩杀赵弘，一举克复南阳首邑。"],"history":"东汉中平元年夏，南阳黄巾杀太守褚贡，推赵弘为帅据守宛城，众盛势张。右中郎将朱儁合荆豫兵及佐军司马孙坚所募淮泗精兵围攻宛城，自六月相持至八月未拔。朝议欲征还朱儁，朱儁急攻，孙坚亲披甲执刃率先登城，众军继进大破黄巾，临阵斩杀主帅赵弘，为平定南阳黄巾首功。","sources":"三国志·吴书·孙破虏讨逆传"},
    "ruzhou_sunjian@191": {"strategic":["公元一九一年冬，关东讨卓联盟分裂，袁术与袁绍南北争锋；荆州刺史刘表暗附袁绍截断南阳粮道，袁术遂遣破虏将军孙坚统兵南征荆州。刘表急命江夏太守黄祖率水陆重兵北上樊城、邓县迎截，孙坚挥精兵渡淯水南下，直指黄祖防线与重镇襄阳。"],"tactical":["襄阳南倚岘山、北临汉水，形势险固。孙坚先在樊邓旷野正面击溃黄祖大军，乘胜渡过汉水将襄阳团团围困；刘表闭门不出，乘夜密遣黄祖潜出城外收拢各县援兵反扑。黄祖归城再战复遭孙坚痛击，弃军败逃窜入岘山；孙坚乘夜单骑疾追黄祖入山中竹林，不料暗处伏兵冷箭骤发，一代江东猛虎中箭殒命，留下未竟霸业。"],"history":"东汉初平二年冬，袁术与袁绍争锋，袁绍连结荆州刺史刘表断袁术粮路，袁术遂遣破虏将军孙坚南征刘表。刘表命江夏太守黄祖逆战于樊城、邓县之间，孙坚大破黄祖，渡汉水进围襄阳。刘表闭门不战，夜遣黄祖出城调集援兵，黄祖归战复败走入岘山，孙坚乘夜单骑轻追于竹林中暗箭殒命。","sources":"三国志·吴书·孙破虏讨逆传"},
    "sailiugu_antiaoke": {"strategic":["公元前二〇〇年，塞琉古国王安条克结束东方远征，趁埃及幼主嗣位朝局动荡，挥师南下争夺柯里叙利亚走廊。托勒密王朝急命雇佣军名将斯科帕斯统埃及主力北上反击，两军在赫尔蒙山麓要冲帕尼翁迎面相遇。"],"tactical":["帕尼翁峡谷溪流横穿，两岸山地起伏。斯科帕斯率托勒密方阵渡溪猛压塞琉古中路，一度逼退当面步阵；安条克沉着列披甲战象于阵前稳住阵脚，同时命右翼铁甲重骑居高俯冲，击溃埃及左翼骑兵后迂回敌方阵背后。腹背受敌又遭战象冲击的托勒密军全面崩溃，斯科帕斯逃困西顿投降，柯里叙利亚永归塞琉古。"],"history":"公元前二〇〇年，塞琉古雄主安条克完成东征归来，趁埃及幼主初立发动第五次叙利亚战争南夺柯里叙利亚。托勒密名将斯科帕斯统埃及主力北上反扑，两军决战于约旦河源赫尔蒙山麓的帕尼翁峡谷。安条克以铁甲圣骑冲垮敌骑翼并包抄方阵后背，辅以战象碾压全歼斯科帕斯主力。","sources":"波利比乌斯·通史·第十六卷；约瑟夫斯·犹太古史·第十二卷"},
    "sailiugu_antiaoke@-190": {"strategic":["公元前一九〇年冬，塞琉古君主安条克远征希腊失利退回小亚细亚；丧失制海权后，他收拢各族精锐与镰刀战车，在吕底亚重镇马格尼西亚筑营备战。罗马共和国执政官卢基乌斯西庇阿首次统罗马军团跨海踏上亚洲，联盟邦进逼河谷寻战。"],"tactical":["马格尼西亚平原晨雾弥漫，安条克布下深厚长矛方阵并以战象填塞间隙。卢基乌斯西庇阿阵中轻兵先用密集标枪射伤拉车马匹，受惊的镰刀战车掉头冲乱塞琉古左翼；安条克虽亲统右翼重骑击破罗马左翼直扑敌营，中路方阵却被自家受惊狂奔的战象踩踏瓦解，安条克惨败求和，尽失小亚细亚霸权。"],"history":"公元前一九〇年冬，在温泉关受挫退回亚洲并丧失制海权的塞琉古大帝安条克三世，于吕底亚西皮卢斯山下的马格尼西亚平原迎战首次踏上亚洲土地的罗马执政官卢基乌斯西庇阿及盟友帕加马王欧迈尼斯二世联军。安条克左翼镰刀战车受惊反冲本翼，右翼安条克亲率具装铁骑虽击破罗马左翼直逼敌营，中路高深长矛方阵却被战象惊乱瓦解，塞琉古大败割让托罗斯山以西全境。","sources":"李维·自建城以来·第三十七卷；阿庇安·叙利亚战记"},
    "sailiugu_antiaoke@-217": {"strategic":["公元前二一七年，塞琉古帝国青年君主安条克锐意收复南叙利亚失地，统率多族大军与印度战象一路南下连克要塞。久享安逸的埃及国王托勒密四世紧急扩编本土埃及人组建马其顿式方阵，倾国北上迎截，两军主力在加沙西南门户拉菲亚列阵对决。"],"tactical":["拉菲亚地处海滨沙丘与荒漠走廊之间，两军皆以厚重长矛方阵居中、战象与精骑分列两翼。安条克右翼高大的印度象猛冲压倒托勒密四世左翼畏缩的非洲象，安条克更亲率铁骑击溃敌左翼乘胜远追；岂料中路塞琉古步阵被托勒密四世亲督的埃及新训方阵正面击垮，安条克回救不及痛失胜局，只得议和北还。"],"history":"公元前二一七年六月，第四次叙利亚战争期间，年轻的塞琉古国王安条克三世南征夺回塞琉西亚与巴勒斯坦大部，在加沙西南的拉菲亚与埃及国王托勒密四世展开古典世界罕见的超大规模会战及唯一一场亚洲象与非洲象正面搏杀。安条克三世以体型庞大的印度象击溃埃及左翼非洲象并亲率骑兵远追，不料中路塞琉古方阵被新训埃及本土方阵击垮，功败垂成。","sources":"波利比乌斯·通史·第五卷"},
    "sashan_aerdaxier": {"strategic":["公元二二四年，统治伊朗高原四百余载的安息帝国日趋衰朽；崛起于波斯发祥地法尔斯的萨珊雄主阿尔达希尔兼并南方诸省，高举复兴古波斯正统大旗公开抗命。安息皇帝阿尔达班四世震怒，亲统北方精锐铁骑南下讨叛，双方约期赶赴荷姆兹甘平原展开决定波斯皇冠归属的生死决战。"],"tactical":["荷姆兹甘平原燥热干旱，唯有一处甘泉可供饮马。阿尔达希尔先机赶抵战场独占水源，挖掘深沟拱卫侧翼；阿尔达班四世远来缺水，麾下贵族暗中动摇。决战打响，阿尔达希尔顶住安息弓骑箭雨，披重甲亲统萨珊具装铁骑猛冲敌军中坚；他在白刃血搏中亲手击毙阿尔达班四世，安息覆亡，萨珊波斯帝国自此崛起。"],"history":"公元二二四年春，兴起于波斯法尔斯故地的萨珊家族领袖阿尔达希尔兼并南方诸省，公开举旗推翻安息帝国统治。安息末代君主阿尔达班四世亲统帝国铁骑南下平叛，两军在胡齐斯坦荷姆兹甘平原决战；阿尔达希尔抢占唯一水源，诱使安息王子变节，并亲率具装重骑冲阵斩杀阿尔达班四世，开创萨珊波斯帝国。定值：战场改定为荷姆兹甘平原。","sources":"塔巴里·历代先知与帝王史；卡西乌斯·狄奥·罗马史·第八十卷"},
    "sengjialuo_dutugamo": {"strategic":["公元前一六一年，南方罗诃那青年君主杜图伽摩尼整军蓄锐，立志光复被朱罗君主埃拉拉久据四十余载的北方故土。杜图伽摩尼亲乘王家战象挥师北伐，沿大河连拔重镇据点，扫清外围屏障，率僧伽罗大军直逼埃拉拉坐镇的北境王都阿努拉德普拉。"],"tactical":["阿努拉德普拉城垣坚固、水池环护，埃拉拉尽起城中精兵与战象出南门迎战。初交锋僧伽罗前阵一度受挫后退，杜图伽摩尼稳住阵脚，催动王家巨象猛冲敌阵撞开缺口，直趋埃拉拉座象之前。两王于城门下驱象相搏，杜图伽摩尼奋力掷出标枪刺毙埃拉拉；守军立溃，杜图伽摩尼克复王都，一举实现全岛首次一统。"],"history":"公元前一六一年，楞伽岛南部罗诃那国王杜图伽摩尼携王家战象挥师北伐，连破沿河诸堡进逼北方古都阿努拉德普拉，迎战统治北境四十余载的朱罗老王埃拉拉。城外决战中杜图伽摩尼击溃守军前锋，在南门骑象与埃拉拉单挑将其刺杀，攻克王都首次统一全岛。定值：年份取前一六一年。","sources":"大史·第二十五章；岛史"},
    "shang_weiwuji": {"strategic":["公元前二五七年，秦将王龁重兵久困赵都邯郸，城内析骨而炊，危在旦夕；魏王却慑于秦廷恫吓，令救赵大军停驻邺城观望。信陵君魏无忌苦谏不听，纳隐士侯嬴秘计，请宠姬如姬夜盗虎符，携力士朱亥星夜驰赴邺营夺军，誓赴邯郸城下救赵存魏。"],"tactical":["邯郸城外秦军连营密布，王龁昼夜急攻。魏无忌抵邺营令朱亥椎杀狐疑的旧帅，颁令遣归父子兄弟同军者与独子，精选效死锐卒疾趋北进。抵邯郸城下后，魏无忌会合南来楚师自西面猛冲王龁围城本阵，城内平原君亦开门杀出响应；久困疲敝的秦军腹背受创大溃，王龁败逃西归，魏无忌一战威震天下，为六国续命。"],"history":"公元前二五七年，秦大将王龁久围赵都邯郸，城中垂危，魏王惧秦恐吓令援军驻邺不动。魏信陵君魏无忌纳侯嬴奇计，请如姬自王宫盗出虎符，赴邺营令朱亥椎杀晋鄙，选精锐北上会合楚军与城内平原君里应外合，于邯郸城下大破王龁秦军，解邯郸之围。","sources":"史记·魏公子列传；史记·赵世家；战国策"},
    "shang_weiwuji@-247": {"strategic":["公元前二四七年，秦大将蒙骜连年东进蚕食三晋，攻城略地直逼魏都大梁，魏师屡败难支。魏王遣使赴赵迎回客居十载的信陵君魏无忌，拜为上将军；诸侯感念魏无忌威义纷纷发兵来会，魏无忌遂统合纵联军西进河外，迎击蒙骜主力。"],"tactical":["河外地处大河南岸通往函谷关的走廊，背水依山，蒙骜统秦军劲旅据险设防。往昔合纵诸军每多推诿，此番在魏无忌统御下却号令如一、人人奋勇。交锋打响，魏无忌督魏武卒正面强压，诸侯铁骑劲弓自两翼包抄突击，一举冲垮蒙骜防线；联军乘胜追至函谷关下猛攻，迫蒙骜残部闭关不敢出，创晚周合纵绝响。"],"history":"公元前二四七年，秦大将蒙骜连年东伐三晋，连拔城邑进逼魏都大梁。魏王迎回留赵十载的信陵君魏无忌拜上将军；魏无忌传檄诸侯，率魏赵韩楚燕五国联军在黄河南岸河外大破蒙骜秦军，追至函谷关叩关攻秦，秦军闭关不敢出。定值：敌将取秦帅蒙骜。","sources":"史记·魏公子列传；史记·秦本纪；资治通鉴"},
    "shanyue_sunce": {"strategic":["公元一九五年，少年英主孙策向袁术索回亡父旧部，决意渡江开拓东南基业。当时汉扬州刺史刘繇坐镇吴郡曲阿，遣将沿江设防堵截；孙策渡江连拔历阳、横江与牛渚尽收精械，随即挥师东指曲阿，与聚拢各路兵马据守大本营的刘繇展开决战。"],"tactical":["曲阿地处江南水陆中枢，城池连营相望，刘繇合诸部重兵严守。孙策军纪严明、秋毫莫犯，江东民众争献牛酒劳军；交战中孙策先以诈退诱破敌营守将，继而亲跨战马督程普、周瑜诸将猛扑刘繇曲阿大营。孙策军锐不可当、呼声动地，刘繇主力一触即溃，弃曲阿仓皇西奔；孙策席卷吴郡丹阳，江东基业自此奠定。"],"history":"公元一九五年，孙策索还亡父孙坚旧部东渡长江进图江东，连破汉扬州刺史刘繇横江、牛渚防线并击破笮融、薛礼。孙策旋即挥师东进刘繇治所吴郡曲阿，设计诱敌并亲冒矢石猛攻，大破刘繇主力迫其出奔豫章，一举奠定江东基业。定值：战场定为曲阿。","sources":"三国志·吴书·孙破虏讨逆传；资治通鉴·汉纪五十三"},
    "shanyue_sunce@196": {"strategic":["公元一九六年，平定丹阳与吴郡的孙策威震江南，决意东渡钱塘江进取浙东富庶大郡会稽。汉会稽太守王朗不纳属下避锋保境之谏，调发郡兵屯驻钱塘江对岸要津固陵，依凭大江风涛阻截江东师船；孙策亲督水陆劲旅抵达江岸，谋破王朗防线。"],"tactical":["会稽西阻钱塘大江，固陵渡口潮急岸陡，王朗沿堤密布营栅，孙策数次强渡皆被挡回。孙策采纳叔父奇谋，入夜命士卒在固陵对岸燃列火瓮疑住王朗守军；暗中却选精兵南趋查渎连夜抢渡登陆，直插王朗侧后重镇高迁屯。王朗闻后路失守大惊分兵回救，被孙策迎头痛击大溃，王朗弃会稽浮海逃亡旋即投降。"],"history":"东汉建安元年，孙策平定丹阳、吴郡后挥师东渡钱塘江进取会稽郡。汉会稽太守王朗不听功曹虞翻避让之谏，发兵屯据固陵阻水拒守，孙策数渡不利。叔父孙静献声东击西之计，夜燃火瓮于固陵疑敌，分精兵南趋查渎奇袭王朗后方，王朗大惊分兵迎救惨败，弃会稽乘船浮海走东冶被追降。","sources":"三国志·吴书·孙破虏讨逆传"},
    "shanyue_sunce@199": {"strategic":["公元一九九年冬，已据有江东诸郡的讨逆将军孙策袭取庐江皖城后，决意溯长江西讨杀父仇敌江夏太守黄祖，打通进窥荆襄的水路门户。荆州牧刘表闻警大震，急派从子率南阳长矛精兵赶赴夏口助战，与黄祖水陆大军合屯夏口沙羡迎击孙策。"],"tactical":["夏口沙羡控扼汉水入江咽喉，江阔洲多，黄祖凭高大蒙冲战舰封锁江面，岸上荆州步骑连营相望。孙策与周瑜、吕范等分统水陆精锐逆流猛扑敌船，江东轻捷快艇贴靠斩缆纵火焚毁黄祖水师；岸上孙策亲跨战马督精兵冲入荆州长矛大阵。黄祖水陆俱溃单骑仓皇逃命，孙策尽收其船械军资，声威震动荆楚。"],"history":"东汉建安四年冬，讨逆将军吴侯孙策袭取庐江皖城击走刘勋后，乘胜溯长江西讨杀父仇人江夏太守黄祖，进至夏口沙羡。荆州牧刘表急遣从子刘虎与南阳韩晞率长矛精兵助黄祖迎战。建安五年春正月孙策同周瑜、吕范、程普、黄盖等水陆并进大破黄祖联军，斩刘虎、韩晞，黄祖单骑仅免。","sources":"三国志·吴书·孙破虏讨逆传"},
    "shizhao_d_shihu": {"strategic":["公元三三八年，后赵天王石虎与辽东前燕王慕容皝密约南北夹击辽西段部鲜卑。岂料慕容皝抢先出兵掠走段部人口畜产便自行班师，未赴会师；石虎平定辽西后暴怒异常，决意顺势吞灭前燕，统后赵水陆重兵浩荡东进，沿途收降叛城，将慕容皝困在国都棘城之内。"],"tactical":["棘城坐落大凌河畔丘陵，乃前燕立国重镇。石虎自恃兵势如山、燕境诸城倒戈，驱后赵步骑四面昼夜猛扑城垣；怎奈慕容皝用忠臣死守，滚石强弩严密阻截，后赵军仰攻十余日寸步难进。初夏粮运不继，石虎只得下令解围西撤；不料城门骤开，燕军精锐铁骑乘晨雾猛冲后队，石虎大军惊溃惨败，无力再窥辽东。"],"history":"公元三三八年夏，后赵天王石虎与前燕王慕容皝约期合讨辽西段部鲜卑；慕容皝提前掠取实利引还，石虎大怒，移师东进合围前燕国都棘城，燕境诸城多叛降后赵。慕容皝据棘城死守十余日挫尽赵军锐气，石虎粮乏拔营撤退，遭前燕精骑趁晨雾突袭追杀，后赵大军惨败溃归。","sources":"晋书·石季龙载记上；晋书·慕容皝载记；资治通鉴·晋纪十八"},
    "shizhao_d_shihu@323": {"strategic":["公元三二三年秋，后赵平定冀兖之后决意东吞齐鲁，命凶悍善战的车骑将军石虎统精锐步骑东征青州。割据青州的东晋刺史曹嶷原拟退保海外孤岛未果，仓促派兵扼守黄河渡口与重镇临淄阻截；石虎摧枯拉朽连破河防，直逼曹嶷新建的险固治所广固。"],"tactical":["广固四面绝涧深谷环绕，阻水依山，乃青州第一坚城。曹嶷失却外围羽翼后退入广固闭门死守，指望凭深沟高垒拖退赵师；石虎督铁骑肃清齐地外援，在城外筑起高垒长围四面昼夜急攻，断绝一切生路。困守日久城中粮竭心散，曹嶷力屈开门出降旋遭诛杀；石虎一战荡平青州全境，后赵疆域直抵东海。"],"history":"公元三二三年秋，后赵王石勒平定徐兖后，命车骑将军中山公石虎统精锐步骑东讨割据青州的东晋青州刺史曹嶷。曹嶷欲退保海中根余山因疾未果，遣兵守渤海河津被石虎击破，临淄亦失，曹嶷退守新建天险都城广固。石虎四面急围困迫，曹嶷力屈出降被送往襄国诛杀，后赵尽收齐鲁之地。","sources":"晋书·石勒载记下"},
    "shizhou_liucong": {"strategic":["公元三一一年夏，西晋朝政彻底崩解，执政权臣携野战主力弃京外逃途中全军覆没，唯剩晋怀帝司马炽困居断粮已久的孤都洛阳。定都平阳的汉赵皇帝刘聪见覆灭晋室时机成熟，倾发各路胡汉劲旅自南北合围洛阳，决心一举踏破这座百年帝京。"],"tactical":["洛阳城垣虽广，城内却饥荒惨烈、禁卫离散，司马炽欲乘船东走亦被乱民劫阻。刘聪所遣前锋先行焚毁城外舟船断其退路，待诸路汉赵铁骑会齐，四面架云梯冲车猛攻，一鼓撞破南面正门宣阳门。汉赵甲士涌入宫禁纵火焚掠，司马炽逃入华林园被追兵生擒押送刘聪帐下，中原衣冠大举南渡，史称永嘉之乱。"],"history":"公元三一一年夏，西晋太傅司马越病亡、东归主力于宁平城覆灭，晋怀帝司马炽困守洛阳空城。汉赵昭武帝刘聪抓住时机，遣大都督呼延晏偕刘曜、王弥、石勒诸路大军会师猛攻洛阳；六月汉赵军攻破洛阳宣阳门，焚毁宫庙，生擒晋怀帝司马炽押回平阳，酿成震动史册的永嘉之乱。","sources":"晋书·孝怀帝纪；晋书·刘聪载记；资治通鉴·晋纪九"},
    "shizhou_liucong@309": {"strategic":["公元三〇九年秋，西晋历经八王内乱山河破碎；崛起平阳的汉赵政权决意问鼎中原，命楚王刘聪统精骑南下直取西晋京师洛阳。西晋太傅司马越坐镇洛阳城内统辖禁军御敌；刘聪一路摧垮外围晋军阻截，铁骑长驱直抵洛阳西明门外。"],"tactical":["洛阳北依邙山、南临洛水，高垣重门拱卫帝阙。刘聪屯营西明门外连挫出战晋将，因屡胜滋生骄轻之心，不听属下严防夜袭之谏，率偏师进逼洛水而留大营疏于戒备。司马越在城中采纳凉州勇将之策，乘暗夜开城门突遣精锐死士猛劫汉赵西明门大营；营中大乱主将被斩，刘聪闻变回救不及，退屯洛水后奉父诏北归。"],"history":"西晋永嘉三年秋，汉赵光文帝刘渊命楚王刘聪偕王弥、刘曜、刘景统精骑自平阳南攻西晋京师洛阳，太傅东海王司马越坐镇城中御敌。刘聪击败平北将军曹武，长驱屯于洛阳西明门外，杀晋冠军将军梁巨，进逼洛水；因连胜骄轻不听呼延翼谏，遭凉州将北宫纯率勇士乘夜突营斩呼延颢，刘聪退屯洛水后奉诏班师。","sources":"晋书·刘聪载记"},
    "shu_liubei": {"strategic":["公元二一九年春，刘备在定军山一战斩杀北方守帅，震动关陇；魏王曹操深恐汉中失守危及三辅，亲统倾国重兵自长安翻越秦岭斜谷南下，进抵南郑一带寻战复仇。面对曹操亲临的赫赫兵锋，刘备胸有成竹，断言汉中必归己有，下令诸营敛众据守险隘，与曹操展开持久消耗。"],"tactical":["南郑盆地北依秦岭绝壁、南凭巴山，曹军远越百里褒斜栈道运粮极艰。曹操屡次列阵求速战，刘备始终高垒深沟拒不出战，暗遣精兵猛将频频出奇截断曹军北山粮道，令敌士卒饥疲逃亡日增。相持至盛夏酷暑，曹操见山险难拔、粮饷枯竭，发出鸡肋口令黯然引全军北退长安；刘备遂全据汉中重镇，自立为汉中王。"],"history":"公元二一七年至二一九年，刘备采法正之策北争益州门户汉中，于定军山命黄忠斩杀曹军主帅夏侯渊。公元二一九年春，魏王曹操自长安亲统大军出斜谷南下争夺汉中；刘备断言曹操必不能得志，敛众据险绝不与曹军正面野战，分遣黄忠、赵云截夺北山粮运，耗至盛夏迫曹操弃南郑全境北撤。","sources":"三国志·蜀书·先主传；资治通鉴·汉纪六十"},
    "shu_liubei@202": {"strategic":["公元二〇二年，官渡战后曹操主力正北渡黄河追剿袁氏诸子，许都南门空虚。客居荆州新野的左将军刘备受命统兵北进，前锋直抵叶县与博望一带窥伺许都；曹营大将夏侯惇奉命督诸军南下迎击，两军在南阳北境博望坡隔野相持。"],"tactical":["博望坡山冈起伏、草木茂密，南通新野官道两侧溪谷幽深。刘备见夏侯惇兵精粮足难以正面力敌，遂预先将精锐步骑隐伏于山谷两侧，某日清晨突然自行放火焚烧大营，率军循大道仓皇南撤。夏侯惇见汉营起火以为刘备惧怯败逃，不顾部将有伏勿追的苦劝，亲率轻兵深入窄道急追；刘备伏兵四起截杀，一举大破夏侯惇追兵。"],"history":"东汉建安七年，曹操主力北征河北袁谭、袁尚，刘表使客居新野的左将军刘备北侵至叶县、博望以窥许都。曹操命大将夏侯惇督于禁、李典等拒刘备。相持间刘备设伏山谷，某朝自烧屯营佯装败逃，夏侯惇不听李典有伏勿追之谏，与于禁率精锐深入窄道中伏，刘备突起逆击大破夏侯惇。","sources":"三国志·蜀书·先主传"},
    "shu_liubei@222": {"strategic":["公元二二二年，蜀汉昭烈帝刘备为夺回荆州并雪关羽败亡之痛，力排群臣谏阻，亲统倾国之师东出三峡讨伐东吴。蜀军水陆并进突破巫峡、招纳五溪部众，进逼长江出山门户夷陵；东吴大都督陆逊统兵据险坚守避其初锐，两军在峡口相持经年。"],"tactical":["夷陵至猇亭崇山峻岭连绵，山路崎岖狭长。陆逊深沟高垒坚守半年，任凭蜀军百般挑战始终不出；盛夏酷暑难耐，刘备遂舍弃水师，将沿途诸营移入深山密林依溪结寨避暑，战线拉长首尾难顾。陆逊看准时机下令顺风纵火猛攻，漫山林木烈焰冲天，蜀汉连营接连崩溃；刘备仅率残骑夜遁白帝城，蜀汉元气自此大伤。"],"history":"三国蜀汉章武元年七月，昭烈帝刘备为复荆州并雪关羽之恨，不听赵云等谏阻，亲统大军东出三峡伐吴，进驻秭归并招抚武陵五溪蛮。章武二年春刘备进逼夷陵、猇亭，与东吴大都督陆逊相持至盛夏；因舍舟依山林结连营兵势分散，闰六月遭陆逊顺风火攻连破诸营，刘备败退白帝城托孤。","sources":"三国志·蜀书·先主传"},
    "shuofang_weiqing": {"strategic":["公元前一一九年，汉朝历经河南与河西大捷后国力鼎盛，汉武帝决意彻底铲除北方边患，命大将军卫青统主力出定襄横绝大漠。匈奴伊稚斜单于纳降将之策，将老弱辎重远移北地，亲率草原精锐主力隐伏于瀚海之北，静待远途疲敝的汉军深入漠北。"],"tactical":["漠北原野荒寒苍茫，卫青跨越瀚海刚出沙碛，便与待劳的伊稚斜单于主力迎面遭遇。面对汹涌胡骑，卫青临危不乱，速令武刚车环列结营，以强弩挫住敌骑冲势，再发轻骑对攻。战至日暮狂风骤起、飞沙蔽目，卫青乘风势挥左右精骑合围夹击；伊稚斜单于见汉军势盛，乘夜弃军溃围北遁，漠南自此再无王庭。"],"history":"公元前一一九年春，汉武帝命大将军卫青出定襄、霍去病出代郡分道横绝大漠直捣匈奴王庭。匈奴伊稚斜单于采赵信计远徙辎重，亲统精骑于漠北以逸待劳。卫青穿瀚海骤遇伊稚斜单于主力，以武刚车环结成营阻敌冲锋，顶狂风飞沙鏖战至暮，乘风纵两翼铁骑合围大破敌军，伊稚斜单于乘夜北遁。","sources":"史记·卫将军骠骑列传；汉书·卫青传"},
    "shuofang_weiqing@-124": {"strategic":["公元前一二四年春，新立的匈奴伊稚斜单于不甘丧失河套沃土，连岁遣右贤王铁骑南下寇掠朔方、代郡，企图迫汉弃塞。汉武帝决意先发制人粉碎敌谋，命卫青统领精骑自高阙塞潜师北出，会合诸路边骑深入漠南，直捣伊稚斜单于西翼重镇右贤王庭。"],"tactical":["漠南草原夜色苍茫，右贤王自认汉军绝不敢远涉塞外，在帐中饮酒酣醉毫无戒备。卫青督轻骑昼伏夜行疾驰深入，乘暗夜疾风般将右贤王庭团团合围；汉骑火炬齐明、鼓角震天，匈奴营帐大乱，右贤王惊骇之下仅携爱妾单骑溃围北逃。卫青尽俘其麾下裨王与部众振旅还塞，汉武帝特遣使者至军前拜卫青为大将军。"],"history":"公元前一二六年匈奴军臣单于死，弟伊稚斜单于夺位，连岁大举犯代郡、雁门、朔方杀都尉以图夺回河南地。公元前一二四年春，汉武帝命卫青统率精骑自高阙塞出击，李息、公孙贺等分道配合。卫青急行军六七百里，乘黑夜突袭酣醉无备的伊稚斜单于麾下右贤王王庭，右贤王仅携爱妾单骑夜逃，汉军俘裨王十余人及大批部众，汉武帝派使至塞上军中拜卫青为大将军。","sources":"史记·卫将军骠骑列传；资治通鉴·汉纪十一"},
    "shuofang_weiqing@-127": {"strategic":["公元前一二七年，匈奴军臣单于挥骑入寇上谷、渔阳，而河套水草丰美的河南地仍由匈奴白羊王、楼烦王盘踞，铁骑旦夕可逼汉都长安。汉武帝施声东击西之策，东线牵制军臣单于主力，密命车骑将军卫青统精骑自云中出塞，西趋高阙奇袭河南地。"],"tactical":["河南地北依阴山、三面环黄河，地势形如袋囊。卫青未从正面强渡黄河仰攻，而是率汉骑沿阴山南麓神速西进直抵高阙塞；随即骤然折向南方，一举切断河南匈奴北逃大漠的归路，对白羊、楼烦二王形成反包围。匈奴骑群腹背受敌仓皇溃逃，卫青席卷河套全境；汉廷遂筑朔方城屯田设郡，彻底解除长安北面心腹之患。"],"history":"公元前一二七年，匈奴军臣单于大举入寇上谷、渔阳杀辽西太守，汉武帝采用声东击西之略，仅遣韩安国、李广在东路牵制，命车骑将军卫青与李息率精骑自云中出发，不南进正面硬攻而沿阴山南麓西趋高阙，突然折而向南切断盘踞河套河南地的匈奴白羊王、楼烦王北逃退路，一举全歼敌部收复河套，筑朔方城解除长安北面威胁。","sources":"史记·卫将军骠骑列传；史记·匈奴列传"},
    "sima_d_simayi": {"strategic":["公元二三一年春，蜀汉丞相诸葛亮再举主力围攻祁山，曹魏西线统帅病危，魏明帝急诏大将军司马懿赶赴长安接掌关陇帅印。面对治军如神的劲敌诸葛亮，司马懿深知蜀师翻越秦岭运粮维艰；他遂统魏军精锐西进天水上邽，定下凭险固守、以静制动的大略。"],"tactical":["上邽地处天水沃野中枢，群山环拱麦田连片，乃陇右粮赋根本。司马懿率军抵上邽依险抢筑高垒，诸葛亮虽抢收部分新麦并在野战占得上风；司马懿一旦受挫便立即收拢全军锁死营门，任凭蜀军百般搦战绝不再给决战良机。两军僵持至盛夏淫雨连绵，蜀道栈阁断绝、诸葛亮粮尽退师，司马懿终以坚韧保住陇右。"],"history":"公元二三一年春，蜀汉丞相诸葛亮再围祁山，曹魏大司马曹真病笃，魏明帝调大将军司马懿西赴长安都督关陇诸军迎战。司马懿看透蜀军远越蜀道粮运难继的软肋，自天水上邽一线步步据险筑垒，以持久韧性拖住诸葛亮主力，直至盛夏连雨蜀军粮尽东退，稳保陇右不失。","sources":"晋书·宣帝纪；三国志·蜀书·诸葛亮传；资治通鉴·魏纪四"},
    "sima_d_simayi@234": {"strategic":["公元二三四年春，蜀汉丞相诸葛亮倾国出斜谷进逼关中，抢占武功五丈原并开垦屯田作持久之计，关陇大震。曹魏大将军司马懿奉诏统大军西御，断定蜀军远道翻越秦岭利在速战，遂率军渡过渭水背水扎营，与诸葛亮隔原展开耐力与定力的较量。"],"tactical":["五丈原台地开阔，北隔渭水与北原相望。司马懿采纳部将之策抢筑北原壁垒，彻底堵死诸葛亮跨渭断绝陇道之谋，随后严令诸营坚壁勿出；面对诸葛亮馈赠巾帼妇人饰物的奇耻大辱，司马懿外作愤慨上表请战，实则静候朝使持节弹压躁动部将。硬撑百余日终耗至诸葛亮病逝军中，司马懿追击遇整阵而止，兵不血刃保全关陇。"],"history":"三国魏青龙二年春，蜀相诸葛亮悉众出斜谷进据五丈原屯田久驻。曹魏大将军司马懿统关陇大军渡渭水背水筑垒阻击，先依郭淮策抢占北原断蜀军跨渭东进之路，继任凭诸葛亮馈赠巾帼百般激怒，借辛毗持节弹压本营请战诸将，坚持耗敌百余日，终耗至诸葛亮病卒五丈原，解除曹魏西顾大患。","sources":"晋书·宣帝纪"},
    "sima_d_simayi@238": {"strategic":["公元二三八年春，割据辽东的军阀公孙渊公然背魏自立为燕王，诱动北方鲜卑寇掠幽冀边郡。曹魏太尉司马懿奉诏统步骑精锐万里北征，向魏帝算定往返百日必破敌巢；大军进抵辽水，公孙渊急遣主力南屯辽隧深掘长壕，企图凭河阻挡司马懿。"],"tactical":["襄平坐落辽河东岸平原，外有辽水环护。司马懿看穿敌主力尽聚南线辽隧而都城空虚，遂多张旗帜佯攻东南；暗率主力自北路潜渡辽水直扑襄平，逼敌仓皇回救并于城外连破之。盛夏暴雨平地水深数尺，司马懿顶住众议严禁移营，待水退立即筑土山、凿地道急攻，一举破襄平斩公孙渊，辽东重归中原。"],"history":"三国魏景初二年春正月，太尉司马懿奉魏明帝诏统牛金、胡遵等步骑远征自立为燕王的辽东公孙渊，算定往返百日必克。六月抵辽水，公孙渊遣大将卑衍、杨祚屯辽隧筑长围拒守。司马懿声东击西佯向东南，乘虚潜渡辽水直趋国都襄平，破卑衍回救军后冒暑雨大水按兵待霁，八月急攻拔城斩公孙渊父子，平定辽东四郡。","sources":"晋书·宣帝纪"},
    "sumeier_nabopalasa": {"strategic":["公元前六一二年，曾称霸西亚的亚述帝国因连年内耗走向衰颓。新巴比伦国王那波帕拉萨在南方起兵逐走亚述驻军，并与东方米底王国缔盟夹击。亚述王伊什昆节节败退，收缩残部退保都城尼尼微；那波帕拉萨遂统巴比伦大军溯底格里斯河北上，与米底盟军合围尼尼微。"],"tactical":["尼尼微矗立底格里斯河东岸，双层巨垣高耸，科斯尔河穿城而过，伊什昆督残存禁卫闭门死守。那波帕拉萨与米底军合围猛攻累月，适逢雨季山洪暴涨冲软临水城基；联军趁势掘毁墙垣缺口，顺河床突入内城展开巷战。伊什昆于王宫自焚，尼尼微化为废墟，两河霸权自此转归新巴比伦。"],"history":"公元前六一二年夏，新巴比伦国王那波帕拉萨与米底国王基亚克萨雷斯会师底格里斯河东岸，合围亚述都城尼尼微。联军围攻三月，借雨季河水暴涨冲毁城垣缺口杀入内城，亚述王伊什昆自焚于王宫，尼尼微化为废墟，亚述帝国覆亡。注：任务表我方势力标为迦勒底，播报按当时国号称巴比伦或新巴比伦。","sources":"巴比伦尼尼微陷落编年史；希罗多德·历史"},
    "suzhou_huoqubing": {"strategic":["公元前一二一年，匈奴浑邪王与休屠王久据河西走廊，既隔绝汉朝通往西域之路，又南连诸羌威逼陇右。汉武帝决意斩断匈奴右臂，破格拔擢年方弱冠的骠骑将军霍去病统领精骑自陇西北地出塞，长驱直指河西腹心焉支山。"],"tactical":["焉支山水草丰美，乃河西匈奴蓄牧根本。霍去病摒弃缓进成规，轻装简从不携重辎，取食于敌；春战疾风骤雨般转战河西诸部夺获祭天金人，夏战更远绕居延大漠自北向南反插焉支与祁连侧背。浑邪王麾下骑群猝不及防，连遭汉骑闪电分割重创；穷蹙之下浑邪王率河西全境部众举地归汉，丝绸大道自此畅通。"],"history":"公元前一二一年春夏，汉武帝为断匈奴右臂、打通西域并隔绝羌胡，命年轻的骠骑将军霍去病两度率精骑出击河西。春战越焉支山连破诸部落，夺休屠祭天金人；夏战绕居延大漠南插祁连山与焉支山侧后，重创浑邪王与休屠王部，迫浑邪王率河西匈奴部众举地降汉，汉置河西四郡。","sources":"史记·卫将军骠骑列传；汉书·霍去病传"},
    "suzhou_huoqubing@-119": {"strategic":["公元前一一九年春，汉武帝决意深入瀚海犁庭扫穴，与大将军卫青分道出塞，特命骠骑将军霍去病统领精选铁骑与归义胡骑出代郡北征。匈奴伊稚斜单于移帐备战，东路左贤王主力横亘漠北草原；霍去病不带笨重辎重，轻骑绝漠直插敌巢。"],"tactical":["漠北草原广袤无垠、风沙凛冽，孤军远征全赖速度与胆魄。霍去病孤师深入大漠腹地，取食于敌，迎头撞上伊稚斜单于东翼仰仗的左贤王主力大阵；汉骑毫无迟疑，短兵相接贴身肉搏，以雷霆攻势彻底击溃并歼灭匈奴东路主力，生擒诸王贵人。霍去病乘胜北追至狼居胥山筑坛祭天，饮马瀚海凯旋，匈奴自此远遁西北。"],"history":"公元前一一九年春，汉武帝发动漠北决战，原拟由骠骑将军霍去病出定襄击伊稚斜单于，后闻单于东移遂改令霍去病率精选铁骑与归义匈奴骑出代郡北进，卫青出定襄。霍去病携少许轻粮横穿大漠两千余里，迎头遭遇匈奴左方主力左贤王大军，浴血恶战全歼敌主力，生擒屯头王、韩王等，一路追杀至狼居胥山筑坛祭天、禅姑衍山，兵临瀚海凯旋。","sources":"史记·卫将军骠骑列传；汉书·霍去病传"},
    "tuoba_tuobagui@397": {"strategic":["公元三九七年春，代北崛起的北魏道武帝拓跋珪大举南下河北，攻克信都重镇直逼后燕国都中山。后燕惠愍帝慕容宝不甘坐困，出屯深泽后收拢大军退伏于滹沱水北岸柏肆坞；他企图趁拓跋珪渡河未稳发动致命夜袭，挽回燕国颓势。"],"tactical":["柏肆紧临滹沱水岸，冬春河冰初泮、夜黑风急。拓跋珪驻营河南岸，慕容宝果在半夜募死士偷渡过河顺风纵火猛扑御帐，魏营一度惊散；拓跋珪临变镇定，移出营外击鼓收众，命将士遍燃火炬虚张四面合围之势反击。夜袭燕军见四野火光冲天自相惊践落水无数，拓跋珪天明渡河追溃慕容宝，乘胜直捣中山。"],"history":"北魏皇始二年春，道武帝拓跋珪攻拔信都，后燕惠愍帝慕容宝自中山出屯深泽，遣慕容农屯安喜，旋撤回滹沱水北柏肆坞潜伏。拓跋珪进营滹沱水南，慕容宝乘夜募死士渡河突袭纵火逼近魏主御帐，魏军一度惊散；拓跋珪沉着移营外击鼓收众、多举火炬四面反击，大破燕军于滹沱水岸，遂进克后燕国都中山。","sources":"魏书·太祖纪"},
    "tuoba_tuobagui@402": {"strategic":["公元四〇二年夏，关中后秦因属部遭袭，倾重兵东渡黄河伐魏；前锋主帅姚平攻陷河东乾壁，后秦君主亲统主力继进蒲坂助威。北魏道武帝拓跋珪毫不示弱，亲统塞北铁骑南下迎敌，先遣前锋挫敌锐气，将姚平主力追逼入汾水东岸柴壁。"],"tactical":["柴壁西临湍急汾水、三面冈原环绕，姚平据垒固守待河西主力来救。拓跋珪沿柴壁外围筑起三重长围，并在汾上架设浮桥；待后秦君主来援，拓跋珪亲渡汾水在蒙坑击溃援师，更用长钩水栅截获上游顺水漂送的救命粮囊。姚平困至深秋粮绝箭尽，率众夜投汾水覆没，北魏自此稳控河东霸权。"],"history":"北魏天兴五年夏，后秦文桓帝姚兴因北魏袭破高平没弈干而兴师伐魏，遣义阳公姚平、尚书右仆射狄伯支统步骑四万渡河攻陷乾壁，后秦主姚兴亲统主力继进蒲坂。北魏道武帝拓跋珪亲征，先遣毗陵王拓跋顺挫敌前锋，追逼姚平退入汾水东岸柴壁筑三重长围锁死，渡汾水大破姚兴蒙坑救兵并截沉浮水粮囊，十月姚平投汾水败没。","sources":"魏书·太祖纪"},
    "tuolemi_tuolemi": {"strategic":["公元前三二一年，亚历山大身后帝国暗流汹涌，埃及总督托勒密一世截留先王灵柩聚拢威望，并联合诸将抗衡摄政佩尔狄卡斯。佩尔狄卡斯震怒，挟幼主亲统王家方阵与战象穿越西奈沙碛南征问罪，直逼托勒密一世设防的东门佩鲁西姆。"],"tactical":["佩鲁西姆至尼罗河东支水网密布，托勒密一世遍筑塞堡桩栅严防。佩尔狄卡斯在佩鲁西姆浚渠损粮后溯河强攻骆驼堡；托勒密一世亲跃墙垛持长矛刺瞎领头战象，激励守军血战挡住攻势。佩尔狄卡斯夜移浅滩强渡再遭湍流与鳄群重创，全军哗变将其刺杀于帐中；托勒密一世抚纳降众，自此稳坐埃及基业。"],"history":"公元前三二一年，帝国摄政佩尔狄卡斯为惩埃及总督托勒密一世劫走亚历山大灵柩并结盟抗命，亲率王家主力与战象南征埃及。佩尔狄卡斯攻佩鲁西姆受阻后转攻尼罗河渡口要塞，托勒密一世身先士卒死守，攻军强渡溺亡惨重引发哗变，部将刺杀佩尔狄卡斯。定值：年份取前三二一年。","sources":"西西里的狄奥多罗斯·历史丛书·第十八卷；阿里安·继业者史残篇"},
    "tuolemi_tuolemi@-312": {"strategic":["公元前三一二年，安提柯王朝称雄西亚，留年轻王子德米特里一世驻重兵于叙利亚南门加沙，时刻威胁埃及。在流亡来投的塞琉古力劝下，埃及统治者托勒密一世乘敌主力远在小亚细亚，统军越西奈荒漠北上加沙；德米特里一世不听劝阻，执意出城决战。"],"tactical":["加沙滨海沙原平阔，德米特里一世将重骑与战象尽压左翼，企图碾碎敌军右翼。托勒密一世侦知虚实，集精骑于右翼针锋相对，更预制铁链尖刺钉障铺于阵前。德米特里一世催战象猛冲，巨象踏刺剧痛狂乱，遭标枪攒射后反冲本阵；托勒密一世乘势率骑迂回击溃敌骑攻占加沙，并助塞琉古东返重夺巴比伦。"],"history":"公元前三一二年，埃及统治者托勒密一世在流亡来投的塞琉古鼓动下，率军穿越西奈进逼叙利亚南门加沙，迎战留守王子德米特里一世。托勒密一世以铁刺钉障配标枪手重创敌左翼战象群，继而迂回击溃德米特里一世骑兵，攻占加沙并助塞琉古东返巴比伦复国。定值：敌将取德米特里一世。","sources":"西西里的狄奥多罗斯·历史丛书·第十九卷；普鲁塔克·德米特里传"},
    "wang_d_liuyu@404": {"strategic":["公元四〇四年春，权臣桓玄废黜东晋皇室在建康自立称帝建立桓楚，江左士庶离心。出身北府旧将的刘裕与志士在京口密谋举义匡复晋室，率精悍义兵渡江连斩桓楚骁将，一路进抵建康城东北门户覆舟山；桓玄大惧，倾发都城重兵陈于覆舟山下迎截。"],"tactical":["覆舟山俯瞰建康外郭与玄武湖岸，草木丛密。桓玄所遣守军虽众却各怀观望；刘裕针对敌众我寡之势，先命老弱登高张旗设疑，亲率北府敢死猛士乘东北劲风顺风纵火，高呼猛冲敌阵中坚。烟焰蔽天中刘裕身先士卒斩将夺旗，桓楚大军溃不成军，桓玄仓皇弃建康乘舟西逃，刘裕一举光复晋都。"],"history":"公元四〇三年冬桓玄迫晋安帝禅让于建康即金陵称帝建桓楚。次年即元兴三年二月，北府旧将刘裕与何无忌、刘毅于京口及广陵举义讨桓，连斩吴甫之、皇甫敷进抵建康东北覆舟山。桓玄遣桓谦、卞范之陈重兵拒守，三月刘裕令老弱登高张旗设疑，亲率死士乘东北急风纵火猛冲大破楚军，桓玄弃都西逃，刘裕收复建康。","sources":"宋书·武帝纪上"},
    "wang_d_liuyu@417": {"strategic":["公元四一七年秋，东晋太尉刘裕倾师北伐后秦，亲统水师溯黄河北上；在河畔以却月车阵击退北魏铁骑阻截后，一举攻克潼关与陆路前锋会师。后秦末主姚泓退守长安惶惧无策，刘裕命水军先锋乘蒙冲战舰由渭水逆流直插长安北门。"],"tactical":["长安北临渭水，渭桥直通东门禁苑。先锋舟师乘急流驶抵渭桥，将士下船后任战舰随水漂走，背水列阵昭示有进无退的死志；后秦末主姚泓亲率禁卫铁骑出东门迎击，却被抱必死之心的晋军步卒正面冲垮反杀入城。待刘裕统主力抵城下，穷途末路的姚泓率百官诣垒出降，后秦覆灭，故都重归王师。"],"history":"东晋义熙十三年春至秋，太尉刘裕统北伐主力水师溯黄河北上，于河畔以却月阵车弩大破北魏长孙嵩阻截铁骑，进克潼关会师檀道济。八月刘裕命龙骧将军王镇恶率蒙冲小舰自渭水逆流直抵长安渭桥，弃船登岸死战大破后秦末帝姚泓禁军攻入东门，姚泓迎刘裕大军出降，后秦灭亡，东晋收复关中。","sources":"宋书·武帝纪中"},
    "wazhai_zhanghan": {"strategic":["公元前二〇八年，秦少府章邯临危受命武装骊山刑徒，连破陈胜及齐魏反秦诸军，唯在东阿与濮阳遭楚帅项梁挫锋，遂引水环营敛兵自守。及至秦廷尽发关中援兵赶赴前线，章邯兵威复振，侦知项梁进驻定陶后连胜骄怠，当即定下奇袭毒计。"],"tactical":["定陶原野秋雨连绵，驻城下的楚军因轻视秦师而疏于巡哨。章邯借风雨掩护行踪，严令全军衔枚疾走、偃旗息鼓，冒泥泞星夜直插定陶城外。半夜秦军铁骑锐卒四面撞破楚营栅垒，纵兵掩杀措手不及的楚卒；楚军大溃，主帅项梁混战中阵亡，章邯一战扫平心腹大患，旋即渡黄河挥师北击赵国。"],"history":"公元前二〇八年，秦大将章邯扑灭陈胜政权后，于东阿、濮阳初遇项梁楚军受挫，退保濮阳环水。秦二世尽起关中兵增援章邯，军威复振；章邯侦知项梁连胜骄怠不设严防，遂冒秋雨昼夜潜行，在定陶夜间突袭攻破楚营，阵斩反秦盟主项梁，挥师北渡黄河击赵。","sources":"史记·项羽本纪；史记·高祖本纪；资治通鉴"},
    "wazhai_zhanghan@-207": {"strategic":["公元前二〇七年，秦将章邯定陶斩项梁后北渡黄河击赵，命副帅围困巨鹿，自统主力驻南侧棘原筑甬道输粮。各路救赵诸侯畏秦势盛闭壁不敢进；楚将项羽夺掌兵权，先遣偏师进袭秦军甬道，率楚师渡漳水直扑巨鹿秦营，章邯急调兵马应对。"],"tactical":["巨鹿南临漳水，棘原与北营全赖狭长甬道相通。项羽前部悍然截断甬道粮运，主力破釜沉舟渡河死战，秦军北营在楚师狂猛冲击下连战皆溃、主将就擒。章邯在棘原救应不及，退保壁垒与项羽隔水相持；内畏权臣赵高猜忌诛戮，外迫楚军凌厉兵威，章邯终在洹水之南率秦军主力投降项羽，秦廷根基彻底崩塌。"],"history":"公元前二〇八年末至前二〇七年，章邯定陶斩项梁后北渡黄河破邯郸，命王离、涉间围赵王歇于巨鹿，自率主力驻巨鹿南棘原筑甬道为王离供粮。楚次将项羽杀宋义夺军权，遣英布先断甬道，自率全军破釜沉舟渡漳水九战破王离。章邯救应不及退守棘原与项羽相持，因畏赵高专权诛杀功臣，遂于洹水南殷墟率秦军向项羽投降。","sources":"史记·项羽本纪；史记·秦始皇本纪"},
    "wazhai_zhanghan@-209": {"strategic":["公元前二〇九年秋，大泽乡烽火席卷关东，张楚大将周章沿途收拢海量义军西破函谷关，兵屯距咸阳咫尺的戏水，秦廷朝野骇然。危急关头少府章邯挺身献策，请秦二世赦免骊山陵园大批刑徒与奴产子，发武库精械整编成军，疾驰戏水迎击周章。"],"tactical":["戏水紧邻骊山北麓，西屏秦都咸阳，周章义军连营漫野却缺乏严格操练。章邯以重获自由之恩激励骊山刑徒，将士人人奋死争先；秦军凭精良甲弩正面猛冲义军松散营阵，一举打垮周章前锋并席卷连营。周章大败弃关东逃，章邯乘胜出函谷关衔尾急追，连破敌军逼得周章自刎，暂挽大秦倾覆危局。"],"history":"公元前二〇九年秋，陈胜立张楚政权后，命蔡人周文即周章佩将军印西击秦；周章沿途收兵车骑浩大，破函谷关长驱进驻临潼东侧戏水，咸阳大震。秦二世惊惶问计，少府章邯献策赦免修筑骊山皇陵的大批刑徒与奴产子，发武库精兵武装出战，在戏水大破周章大军，乘胜追出函谷关，于曹阳、渑池连败周章迫其自刎。","sources":"史记·陈涉世家；史记·秦始皇本纪；汉书·陈胜项籍传"},
    "wei_wuqi": {"strategic":["公元前三八九年，魏国经变法强兵称雄战国，西河郡守吴起连年西进夺占河西沃土，扼住秦国东出咽喉。适逢魏文侯卒、武侯新立，秦惠公以为有机可乘，倾发全国兵马东攻河西门户阴晋；西河告急，吴起主动请缨，统魏武卒赶赴阴晋迎敌。"],"tactical":["阴晋南依华山余脉，北控渭洛原野，秦惠公亲督秦师压境筑垒。西河士卒素感吴起恩信，纷纷披甲请战；吴起特设分等酒食飨士，将未曾立功者置于次席以激其耻，编为前锋锐卒配车骑出击。交锋之际，求功心切的魏卒奋死直捣秦阵中坚，冲垮仓促征集的秦军前锋；秦惠公大败西遁，魏国由此久据河西。"],"history":"公元前三八九年，秦惠公倾发大军东进，猛攻魏国河西门户阴晋。魏西河郡守吴起平日治军恩信兼备，奏请魏武侯抽调尚未立功受赏的士卒为突击骨干，配以战车骑兵鼓行迎击，在阴晋城外以少击众大破秦师，稳固了魏国对河西之地的长期控制。","sources":"吴子·励士；史记·孙子吴起列传"},
    "wu_fuchai": {"strategic":["公元前四九四年，吴越因槜李之战结下死仇，吴王夫差铭记杀父之痛，督舟师步卒日夜备战将南下伐越。越王勾践探知吴军将动，不听范蠡劝阻，决意先发制人率水师北入太湖；夫差闻讯倾发精锐楼船出迎，两军主力会战于太湖夫椒山。"],"tactical":["太湖烟波浩渺，夫椒山孤峙湖中，勾践率越国舟师抢占水域严阵待敌。夫差见越阵稳固，趁入夜北风大作分遣翼舟环绕越寨张火鸣鼓，彻夜诈攻惊扰，令越军疲于奔命。破晓时分，夫差亲擂战鼓，统大翼楼船顺风全线猛撞敌阵；越水师大溃，勾践退困会稽山请降，吴国一时称雄东南。"],"history":"公元前四九四年春，吴王夫差为报父仇日夜练兵将伐越，越王勾践不听范蠡劝阻抢先发水师北上迎战于太湖夫椒山。夫差乘夜风设火炬疑兵惊扰越军水寨，次日顺风全线猛攻大破越水师，追困勾践于会稽山，迫越称臣入质。","sources":"左传·哀公元年；国语·越语；史记·越王勾践世家"},
    "wu_fuchai@-473": {"strategic":["公元前四七三年，曾威震中原的吴王夫差已入穷途。因连年远征齐晋耗尽精壮，又在笠泽夜战中丧尽野战主力，北方昔日盟友皆坐视不救；越王勾践倾发水陆大军合围吴都姑苏，筑垒断道步步紧逼，夫差唯有收拢残存军民据守孤城，作最后一搏。"],"tactical":["姑苏城池水门相通、重垣环抱，夫差屡遣精锐出城突击，企图打通太湖粮道。勾践严令越军深沟高垒不与硬拼，于城外筑越城锁死水陆通道，久困消耗城内积储。重围经年，城中粮绝兵疲，越军终发起总攻破城；夫差突围退据姑苏山遣使乞和，勾践不许留国，夫差愧见伍子胥于九泉，掩面自刎，霸业成空。"],"history":"公元前四七五年至前四七三年，吴王夫差历经笠泽惨败后野战主力丧尽，退保都城姑苏。越王勾践筑城断水长围姑苏三年，吴军粮尽援绝，公元前四七三年冬城破，夫差退奔姑苏山乞和遭拒，掩面自刎而死，吴国灭亡。","sources":"左传·哀公二十二年；史记·吴太伯世家"},
    "wu_fuchai@-484": {"strategic":["公元前四八四年，吴王夫差自夫椒破越后志得意满，开凿邗沟一心北上争霸中原。适逢齐国侵凌鲁国，鲁侯遣使联吴抗齐；夫差拒纳伍子胥先除越患之苦谏，倾发吴国精锐北渡淮泗会合鲁师入齐，与齐国上卿国书统率的齐军主力对阵于艾陵。"],"tactical":["艾陵山谷开阔，控扼齐鲁要冲，国书自恃本土车广兵足列阵迎战，夫差则亲领精锐坐镇吴中军。初战齐上军死命猛扑，一度击退吴国右翼；夫差稳居中坚亲自擂鼓，督吴国剑士奋勇反冲，一举凿穿齐军中阵，配合左翼合围包抄。齐师全线崩溃，主帅国书力战阵亡；夫差虽威震北方，却令吴国精锐远耗于外。"],"history":"公元前四八四年五月，吴王夫差不顾伍子胥先防越国之谏，志在北上争霸，应鲁国之约经邗沟北伐齐国，与齐上卿国书决战于艾陵。夫差亲领中军，先挫后胜全歼齐中军，阵斩齐帅国书及高无丕等将，威震齐鲁，但亦远耗吴国国力。定值：敌将取齐军主帅国书。","sources":"左传·哀公十一年；史记·吴太伯世家"},
    "wu_sunwu": {"strategic":["公元前五〇六年，吴国经孙武练兵与疲楚之策国力日盛；宿敌楚国则因令尹子常贪贿扣留蔡唐二君，致汉东屏藩背楚联吴。吴王与孙武决意大举伐楚，避开江淮旧路，溯淮水舍舟登陆；吴军会合蔡唐向导穿越大别山险隘直插汉水，与赶来堵截的子常主力逼近柏举。"],"tactical":["柏举位于大别山西麓通往汉水与郢都的原野门户。子常不听同僚凭汉水固守并断吴船后路之策，贪功渡水求战，连挫后退屯柏举。交锋当日，吴军看准子常治军无恩、楚卒离心，以精锐猛冲楚国中军，孙武挥全军压上掩杀；楚阵崩溃，子常奔郑，吴军五战五捷攻入郢都，威震诸侯。"],"history":"公元前五〇六年冬，吴王阖闾以孙武为将、伍子胥辅之，联蔡唐两国自淮汭舍舟登陆，越大别山奇袭楚国。楚令尹子常违沈尹戌夹击之议，渡汉水迎战连败，退屯柏举。吴军乘楚卒怨怠率先突击，大破子常主力，五战五捷攻入楚都郢城。","sources":"左传·定公四年；史记·孙子吴起列传"},
    "wudu_dengai": {"strategic":["公元二六三年秋，曹魏大军伐蜀受阻于剑阁雄关；征西将军邓艾毅然挑精兵走阴平绝径，攀木悬崖穿行荒山七百里，裹毡滚下摩天岭奇袭江油，突现成都平原北端。蜀汉朝廷惊骇，急拜卫将军诸葛瞻督禁军北御；诸葛瞻未抢占险隘，退保绵竹筑阵迎战邓艾。"],"tactical":["绵竹扼守成都北来坦途，城关之外平畴开阔。邓艾孤军深入绝地无路可退，先遣使劝降被诸葛瞻怒斩，遂激励三军有死无生。初战邓艾之子与前锋被蜀军击退，邓艾立斩畏缩欲逃者亲督中坚反攻，同时密遣偏师自侧翼迂回包抄绵竹阵后；蜀军腹背受击防线崩溃，诸葛瞻父子力战阵亡，邓艾乘胜兵临成都迫降蜀主，一举灭蜀。"],"history":"公元二六三年秋，曹魏大举伐蜀，姜维退保剑阁挡住钟会主力。征西将军邓艾献奇谋自阴平无人险道偷渡，凿山裹毡滚崖突抵江油，长驱南下。蜀汉卫将军诸葛瞻督羽林军自涪城退守成都北门重镇绵竹，邓艾激励将士背水死战，分翼包抄攻破绵竹，斩诸葛瞻父子，蜀汉遂降。定值：战场改定为绵竹。","sources":"三国志·魏书·王毌丘诸葛邓钟传；三国志·蜀书·诸葛亮传"},
    "wudu_dengai@256": {"strategic":["公元二五六年夏，蜀汉大将军姜维再举重兵北伐陇右，企图趁麦熟时节夺取天水上邽粮仓，并与东路蜀军合兵席卷陇西。曹魏安西将军邓艾胸有成竹，提前摸透姜维每一步进军算计，抢先派兵卡死武城山与上邽险要，逼得求战不得的姜维改走东道趋段谷。"],"tactical":["段谷山高谷深、道路崎岖，两侧山脊居高临下锁住行军咽喉。邓艾料定蜀汉两路援军山阻难通、姜维孤师转进必疲，预先调精锐步骑抢占段谷高坡张网待敌；待姜维大军踏入狭谷立足未稳，邓艾挥旗令魏军自山巅全线俯冲掩杀。蜀军首尾被截大败溃散，姜维狼狈南遁；邓艾一战重创蜀汉北伐元气，因功晋封邓侯稳镇陇右。"],"history":"三国魏甘露元年夏六月，蜀汉大将军姜维自钟题再出祁山北伐，约镇西大将军胡济会师上邽。曹魏安西将军邓艾料敌于先，预先抢占武城山及上邽要地坚壁拒之。姜维攻武城山不克，改道出董亭趋南安，胡济失期未至，七月邓艾于天水西南段谷抢占山头居高痛击，大破姜维，因功进封邓侯。","sources":"三国志·魏书·王毌丘诸葛邓钟传"},
    "wuling_xiangdancheng": {"strategic":["公元四七年，武陵五溪部族不堪郡县赋役侵迫，共推头领相单程举兵反抗，下山攻掠临沅一带城邑。东汉朝廷遣武威将军刘尚调集荆南诸郡兵马与江夏船师，由临沅溯沅水西上进剿；相单程见汉军船坚甲利，遂主动敛众退入崇山深谷诱敌。"],"tactical":["临沅以西沅水与支流穿行绝壁之间，滩多水急、纤道险仄。刘尚恃胜轻敌，不察虚实便督舟师逆流深入险谷，致粮运难继、进退维谷。相单程早已率五溪健卒隐伏两岸悬崖密林，待汉军船队困于急滩散乱之际，骤然伐木塞水断其归路，居高乱石毒矢齐发；汉军无处登岸全军覆没，刘尚战死，五溪声势震动荆南。"],"history":"公元四七年冬，武陵五溪蛮首领相单程等不堪赋役聚众反汉，寇掠郡县。东汉遣武威将军刘尚发荆州诸郡兵及船师溯沅水进讨；刘尚轻敌深入武溪险谷，粮运不继，相单程率部据两岸高山断流夹击，全歼汉军并击杀刘尚。","sources":"后汉书·南蛮西南夷列传；后汉书·马援列传"},
    "wuling_xiangdancheng@49": {"strategic":["公元四九年春，东汉朝廷为平定武陵五溪部族反抗，起用威震南疆的宿将马援挂帅，调集诸军沿沅水西上进逼五溪腹地。面对汉军精甲楼船，五溪渠帅相单程深知平地野战难以争锋，遂统合诸溪健卒抢先退守沅水咽喉壶头山高寨，据天险迎击马援。"],"tactical":["壶头山崖壁陡峭如削，山脚急滩狂澜翻涌，舟船逆水寸进极艰。相单程依托山顶坚固木石寨垒，俯控狭窄水道与山径，以滚石劲弩死死锁住汉军仰攻之路，并派轻兵频频袭扰粮船。两军自春至夏相持数月，酷暑瘴疠在谷底蔓延，汉军疫病惨重、主帅马援病卒营中；相单程趁汉营监军传檄招抚之机顺势受降，保全五溪部众。"],"history":"东汉建武二十五年春，汉廷宿将伏波将军马援统马武、耿舒等大军进讨武陵五溪蛮，舍弃充县陆道而自沅水直趋壶头山险隘。五溪渠帅相单程统合诸溪精锐抢先据守壶头山巅高寨，俯控山下漩涡急滩阻遏汉军舟师达八月之久，借炎夏瘴疠拖垮汉师，待马援病卒后与汉监军宋均订约受抚保全族众。","sources":"后汉书·南蛮西南夷列传"},
    "wuwu_d_lvmeng": {"strategic":["公元二一九年冬，荆州主帅关羽北围襄樊威震中原，却在长江南线留置重兵严防江东。江东大都督吕蒙深知强攻必损，遂密献攻心奇谋，对外宣称重病返回建业休养；同时改派后起儒将驻陆口致信谦卑推崇，果诱关羽放松戒备撤走沿江守军。"],"tactical":["江陵乃荆州根本重镇，沿江遍设烽火候望。吕蒙侦知南线空虚，秘密赶赴寻阳，将精锐甲士尽藏大船舱底，挑士卒身着白衣扮作商贾摇橹逆江疾行；沿途戍卒毫无防备，尽被吕蒙奇兵登岸一网打尽，竟无一处烽火燃起。大军神兵天降直抵江陵城下，吕蒙厚待守军家眷瓦解斗志，守将开门出降，关羽后方瞬间崩塌。"],"history":"公元二一九年秋冬，关羽倾荆州精锐北攻襄樊，留偏将守公安与江陵，仍防备江东。大都督吕蒙定下骄敌奇谋，上表称病返回建业，举荐名不见经传的陆逊代镇陆口谦辞麻痹关羽；待关羽抽调沿江守兵北上，吕蒙率精锐伪作商船白衣摇橹潜溯大江，尽缚烽火戍卒，兵不血刃袭取江陵。","sources":"三国志·吴书·周瑜鲁肃吕蒙传；资治通鉴·汉纪六十"},
    "wuwu_d_lvmeng@213": {"strategic":["公元二一三年春，平定关中的丞相曹操亲统北方劲旅大举南征，破江北前哨直逼江东淮南水门濡须口。江东诸将面对北军浩大声势多有惧色，偏将军吕蒙随主帅赶赴前线，献策夹濡须水两岸赶筑坚固船坞作为水师依托，严阵迎战曹操大军。"],"tactical":["濡须水沟通巢湖与长江，新筑濡须坞两翼控水、壁垒相连。曹操督北军乘船抢滩设营，吕蒙每次皆趁曹军未稳抢先猛击挫其锐气；更在船坞墙头密排层层强弩封死水陆近路，配合友军乘夜劫营扰乱敌心。相持月余春雨绵绵、江水暴涨，曹操见吕蒙布防滴水不漏，叹息引军北还。"],"history":"东汉建安十八年春正月，丞相曹操亲统北方大军南攻东吴江淮门户濡须口，破孙权江西营擒都督公孙阳。孙权亲率吕蒙、甘宁等拒守，吕蒙献策夹濡须水口构筑坚固濡须船坞，于坞上密布强弩并乘曹军初至未稳屡破其前锋，配合甘宁夜劫曹营，相持月余春雨江涨，曹操叹服引军北还。","sources":"三国志·吴书·周瑜鲁肃吕蒙传"},
    "wuwu_d_lvmeng@214": {"strategic":["公元二一四年夏，北方庐江太守朱光屯驻重镇皖城，大兴屯田积蓄军粮，并暗中招诱江南山越豪帅里应外合。偏将军吕蒙力陈一旦皖城稻熟兵增必成江东心腹大患，劝主帅趁夏雨涨水大举西征；水师直抵皖城之下，朱光闭城固守急向北军求援。"],"tactical":["皖城外环皖水，夏日暴雨令河水暴涨，船只可直抵城下。帐中众将多主张堆筑土山稳步缓攻，吕蒙断然反对，指出敌方合肥名将援兵已在途中，久攻必腹背受敌，唯有趁三军锐气四面猛扑速克。吕蒙举荐猛将领死士攀城，亲自赤膊在阵前手执槌鼓擂响冲锋号令；将士感奋冒矢石蚁附登城，自晨至午一鼓攻陷皖城生擒朱光。"],"history":"东汉建安十九年夏五月，曹魏庐江太守朱光屯驻皖城大开稻田，又招诱鄱阳贼帅使作内应。吕蒙力陈皖城不除必成心腹大患，劝孙权乘夏雨大水亲征。张昭等主筑土山缓攻，吕蒙力主趁张辽援军未至四面速攻，荐甘宁为升城督，吕蒙亲执桴鼓督阵，自旦至食时一鼓拔城生擒朱光，张辽半途闻城破退还。","sources":"三国志·吴书·周瑜鲁肃吕蒙传"},
    "wuzhou_limu": {"strategic":["公元前二三三年，赵国南线新遭惨败，秦大将桓齮又率虎狼之师东越太行深入赵境，直逼邯郸东北屏障宜安与肥下。举朝无人可当强敌之际，赵王急召久镇雁门的名将李牧入朝筑坛拜大将军；李牧合北边精骑与京师守军昼夜北上，奔赴肥下挽救危局。"],"tactical":["肥下原野坦荡，极利骑兵驰突。面对连胜骄横的桓齮大军，李牧筑坚垒收兵不出，日夜椎牛飨士以激求战死志。桓齮久候不耐，误认李牧怯懦，竟轻率分主力离宜安大营东扑肥下。李牧侦知敌军营虚，骤遣奇兵攻占秦军老营截获粮草，随于肥下张开铁骑双翼，合围击溃仓皇回救的秦师，因功受封武安君。"],"history":"公元前二三三年，赵国平阳惨败后危在旦夕，赵王急从雁门召回名将李牧拜大将军，统南北合军抗击越太行来攻的秦将桓齮。李牧筑垒蓄势挫耗秦军锐气，趁桓齮骄躁分兵攻肥下之际，先袭夺秦空虚大营，再以两翼钳形包抄在肥下全歼回救秦军，因功封武安君。","sources":"史记·廉颇蔺相如列传；战国策·赵策四"},
    "wuzhou_limu@-232": {"strategic":["公元前二三二年，距肥下大捷仅隔一载，秦军卷土重来，由老练统帅王翦等分南北两路钳击赵国；南路威逼邺城，北路东越井陉直插重镇番吾，欲将赵国拦腰夹碎。武安君李牧权衡全局，留偏师固守南境漳水防线，亲统赵军主力星夜北上番吾迎击王翦。"],"tactical":["番吾背倚太行井陉东口，前临滹沱河原野。王翦北路军补给全赖身后狭道，急求速胜；李牧抵番吾后，借河谷丘陵深沟高垒锁住大道，同时纵边骑迂回袭扰秦军山谷粮道与侧翼，伺隙集精兵猛击。北路秦军攻势受挫、粮运难继，王翦知无机可乘遂退回山内，南路秦师亦随之撤还，李牧再保赵国不失。"],"history":"公元前二三二年，秦不甘肥下之败，再发重兵分南北两路攻赵，南逼邺城、北出太原拔狼孟与番吾。赵武安君李牧南设坚防阻遏南路，亲统主力北上番吾迎击秦帅王翦，依太行东麓险要击败秦军，迫南北两路秦师撤退，赵军亦损耗沉重。定值：敌将估算取王翦。","sources":"史记·赵世家；史记·廉颇蔺相如列传；战国策"},
    "wuzhou_limu@-244": {"strategic":["约公元前二四四年，草原匈奴日盛，单于头曼麾下控弦游骑频频南掠赵国雁门边塞。赵将李牧久镇北疆，以边市租税日夜宰牛飨士、习骑练射，却严令见匈奴即入堡自守；待将士求战欲狂而头曼彻底轻视赵军怯懦，李牧终于塞外张开决战巨网。"],"tactical":["雁门塞外黄沙草滩相连，李牧精选铁骑、坚车与强弩编成军团，故意纵放满山畜牧诱敌，并佯败丢弃人畜。头曼闻报大喜，果倾草原主力越塞深入。待匈奴大军尽入谷地，李牧升帐擂鼓，正面重车强弩稳阵齐射，两翼赵国胡服精骑高速迂回锁死退路；匈奴骑群猝不及防死伤蔽野，头曼仅率残骑远遁大漠，十余载不敢南窥赵边。"],"history":"约公元前二四四年，赵名将李牧驻守雁门防备匈奴，厚养士卒而严令遇胡骑即入堡收保，致匈奴与赵王皆以为怯；换将屡败后赵复请李牧出镇。李牧蓄势数载激起全军死志，纵畜牧诱匈奴单于头曼倾部深入，张车骑强弩两翼合围大破匈奴，十余年不敢近赵边。定值：年份取前二四四年、敌将取头曼。","sources":"史记·廉颇蔺相如列传"},
    "xianyu_hanxin": {"strategic":["公元前二〇四年，楚汉相持荥阳，汉大将韩信破魏灭代后挥师东进，欲越太行山天险井陉关攻灭赵国。赵成安君陈馀聚全国重兵扼守井陉东口，谋士李左车献绝粮困敌之奇计，迂腐自负的陈馀却自诩义兵拒不采纳；韩信探得实情大喜，遂引兵径下井陉狭道。"],"tactical":["井陉山道狭仄，出口前临绵蔓水。韩信夜遣轻骑人持赤帜潜伏赵营侧近，天明亲率主力渡水，故意背水列开无路可退的死阵。陈馀嘲笑韩信不知兵，果倾全营出击猛攻；汉卒死战不退，伏骑乘虚突入空营拔赵旗尽换汉赤帜。赵军攻久不克欲返营，惊见满壁红旗顿时大溃，陈馀于泜水上被斩，背水一战遂成千古绝唱。"],"history":"公元前二〇四年冬，汉将韩信统新募之师东下太行井陉关攻赵，赵成安君陈馀聚重兵扼井陉口，拒纳李左车奇兵断粮之策。韩信探知大喜，夜遣轻骑持汉赤帜潜伏赵营侧山间，主力出关背绵蔓水列阵诱敌倾巢来攻；伏骑乘虚拔赵旗立汉帜，赵军回营大乱溃败，陈馀被斩。定值：年份取前二〇四年。","sources":"史记·淮阴侯列传；汉书·韩信传"},
    "xianyu_hanxin@-202": {"strategic":["公元前二〇二年冬，楚汉决战进入最后关头；受封齐王的韩信应汉王之召，统久经锤炼的齐汉精兵自北南下，与各路诸侯会师垓下合围西楚霸王项羽。汉王将全军临阵指挥大权悉数托付韩信，由其正面迎战百战百胜的项羽主力。"],"tactical":["垓下原野广阔平旷，极利大兵团阵列变幻。韩信深知项羽冲锋锐不可当，特设前军、中坚、后备与左右两翼弹性大阵；交战初韩信亲督前中军迎敌后有序后撤，诱使项羽孤军突入腹心，随即挥动左右两翼铁钳斜插夹击，前军回身反冲。楚军主力在这一战中遭彻底重创，项羽困守孤营突围自刎，成就韩信统兵绝唱。"],"history":"公元前二〇二年冬，受封齐王的韩信应汉王刘邦之召，统率精锐齐汉大军自齐地南下，与刘邦、彭越、英布、刘贾诸军会师于垓下合围西楚霸王项羽，被刘邦推为全军临阵总指挥。韩信针对项羽猛冲特点布设前中后与左右翼多层弹性大阵，先以中军佯退吸纳楚军锋芒，再以两翼斜击与中军反冲重创项羽，创下多多益善的统兵巅峰之作。","sources":"史记·淮阴侯列传；史记·高祖本纪"},
    "xianyu_hanxin@-203": {"strategic":["公元前二〇三年冬，汉大将军韩信袭破历下夺占齐都临淄，齐王东逃高密向西楚乞援。项羽急遣麾下头号猛将龙且统重兵赴齐反扑；有人劝龙且深壁持久招抚齐城，龙且却轻视韩信早年微贱，执意速战，率楚齐联军进抵高密潍水东岸与韩信隔河对峙。"],"tactical":["潍水自南向北奔流，冬日水浅可涉。韩信乘夜命士卒赶制大批沙囊堵塞上游河道，拂晓亲率半数汉军涉水猛攻龙且，交锋未久便弃阵佯败退回西岸。龙且狂喜高呼韩信果真怯懦，当即督楚军主力争渡追击；待敌半渡之际，韩信下令决开上游沙囊，暴涨河水瞬间将楚军拦腰截断，韩信回军猛杀阵斩龙且，齐地尽平。"],"history":"汉四年冬即公元前二〇三年前后，韩信袭破历下攻占齐都临淄，齐王田广东走高密求救于楚，项羽遣头号猛将龙且统重兵救齐，与田广合兵高密。或劝龙且深壁招抚齐城，龙且轻视韩信曾受胯下之辱急于立功拒不听从，隔潍水列阵。韩信夜命人以万余沙囊堵塞潍水上游，天明涉水击龙且佯败退回，诱龙且半渡之际决开沙囊，大水冲断楚军，韩信反击斩杀龙且，尽定齐地。","sources":"史记·淮阴侯列传；史记·项羽本纪；汉书·韩信传"},
    "xiayang_d_dengyu": {"strategic":["公元二五年春，刘秀平定河北将图天下，拜年少有谋的邓禹为前将军，分精兵西进经略关河。邓禹越太行下河东，自龙门以南渡河连克要邑，河东震动；盘踞关中的更始政权惊恐万分，急遣大将军樊参渡黄河东来反扑，邓禹遂整师南迎。"],"tactical":["河东解南背倚中条崇山，西控大河津渡，乃进窥关中的门户。樊参自恃兵众气盛，欲一战将邓禹赶出河东；邓禹审察地形沉着列阵，先以严整步弩挫住敌军凶猛前锋，待更始军攻势衰竭、阵脚松动，果断挥精骑自侧翼掩杀突击。更始军大溃，主帅樊参乱军中被斩，河东门户洞开，为邓禹西入长安扫平道路。"],"history":"公元二五年春，刘秀平定河北后遣前将军邓禹统精兵西取关河。邓禹自箕关南下渡河入河东，攻拔皮氏擒河东都尉；更始驻长安诸将大惧，命大将军樊参自大阳渡黄河迎击，两军会战于河东解县之南，邓禹设奇大破更始军并斩杀樊参。定值：决战战场定为解南。","sources":"后汉书·邓禹列传；资治通鉴·汉纪三十二"},
    "xiayang_d_dengyu@25": {"strategic":["公元二五年夏，前将军邓禹渡河入河东斩将夺邑，长安更始政权惊惶失措；急命定国上公王匡会合诸王重兵东渡黄河，进驻河东治所安邑企图围歼汉军。孤师远征的邓禹毫无惧色，整顿精兵主动进逼安邑，与王匡主力展开河东归属之战。"],"tactical":["安邑南临盐池、北控汾河平原，乃河东腹心重镇。两军初战终日，王匡兵多势盛，邓禹前军受挫、部将战殁，诸将皆劝乘夜退避。邓禹审知次日恰逢历家忌讳的六甲穷日，断定迷信的王匡必闭营不出，遂从容休整补装；越日清晨邓禹倾全军猛攻更始大营，王匡猝不及防全线大溃弃城西逃，河东全郡尽入邓禹掌握。"],"history":"公元二五年即建武元年夏，邓禹在河东解南斩更始大将军樊参后，更始政权大震，复遣定国上公王匡、襄邑王成丹、抗威将军刘均等合重兵进驻河东治所安邑共击邓禹。六月两军大战，首日邓禹军不利、部将樊崇战死，明日癸亥王匡以六甲穷日不出，邓禹整军猛攻大破王匡，尽定河东郡。","sources":"后汉书·邓禹列传"},
    "xibolai_dawei": {"strategic":["约公元前一〇二五年，迦南沿海的非利士五城同盟凭冶铁优势向内陆扩张，纠集联军深入犹大边境，意图压服以色列诸支派。两军隔以拉谷相持，非利士猛士歌利亚连日搦战，以色列军无人敢应；奉父命赴营送粮的年轻牧人大卫见状，毅然请缨步向阵前。"],"tactical":["以拉谷两侧丘陵夹峙，谷底横亘干涸溪床，两军分据南北山坡，谁先仰攻便陷被动。披重甲的歌利亚下谷挑战，大卫卸去甲胄，仅携牧杖与机弦拣石入谷；趁歌利亚轻敌逼近尚未及身，大卫疾旋机弦发石击中其额，趋前拔刀斩首。非利士军魂飞魄散弃营西逃，以色列军乘势追杀大获全胜。"],"history":"约公元前一〇二五年，沿海非利士五城同盟进军犹大山地边缘，与以色列军在以拉谷隔谷对峙。非利士巨人勇士歌利亚连日出阵搦战，年轻牧人大卫请缨上阵，弃重甲不用，以机弦甩石击杀歌利亚，以色列军乘势掩杀大败非利士军。史料不足：此战仅见于希伯来圣经撒母耳记上，年份系后世推算。","sources":"撒母耳记上·第十七章"},
    "xibolai_dawei@-995": {"strategic":["约公元前九九五年，大卫合以色列南北诸支派为一国，夺取山地要冲耶路撒冷立为新都。沿海非利士五城唯恐昔日附庸壮大断其商路，由亚吉统领联军东上山地，抢占新都西南门户利乏音谷，企图隔断以色列南北。大卫收拢勇士整备，亲统大军出迎利乏音谷。"],"tactical":["利乏音谷地处耶路撒冷西南走廊，两侧山坡遍生桑林，亚吉率非利士军在谷中广布营阵封锁大道。大卫先率军自高处猛冲，正面击穿敌阵；待敌重整再进，大卫改借桑林掩护迂回敌后，乘山风吹动树梢掩盖声响，骤自侧背奇袭。亚吉大军首尾失顾溃败西逃，以色列联合王国基业自此稳固。"],"history":"约公元前九九五年，大卫统合以色列南北诸支派并定都耶路撒冷，沿海非利士五城深感威胁，两度出兵屯驻耶路撒冷西南的利乏音谷企图扼杀新王国。大卫先正面冲决敌阵，复在再战中绕至桑林背后奇袭大破非利士军。定值：年份依圣经年代推算取前九九五年，敌将估算取同期非利士迦特王亚吉。","sources":"撒母耳记下·第五章；历代志上·第十四章"},
    "xibolai_majiabi": {"strategic":["公元前一六六年，塞琉古帝国强推异俗并亵渎耶路撒冷圣殿，激起犹太民众揭竿反抗，勇烈善战的犹大马加比继掌义军帅印。塞琉古驻军统帅塞隆轻视义军势孤，纠集重兵自沿海东进，攀越通往山地的咽喉要隘伯特和仑，企图一举扑灭起义。"],"tactical":["伯特和仑山道陡峭曲折，两侧岩壁夹束。塞隆督塞琉古大军沿窄径仰攻登山，行军队列被迫拉成冗长一线；犹大马加比早已隐伏于高处岩坡，面对强敌激励部众奋死出击。义军居高临下猛冲敌阵中段，当场阵斩主帅塞隆；塞琉古军首尾失顾，全线惊溃逃回沿海平原，马加比起义自此声威大振。"],"history":"公元前一六六年，塞琉古帝国强推希腊化并亵渎耶路撒冷圣殿，犹大马加比接掌犹太起义军。塞琉古叙利亚驻军统帅塞隆轻视义军，率重兵攀越伯特和仑山隘直扑耶路撒冷；犹大马加比据险设伏，趁敌军攀坡队列拉长骤然突击，阵斩塞隆，击溃塞琉古军。注：任务表我方标以色列，实为犹太马加比义军。","sources":"马加比一书·第三章；约瑟夫斯·犹太古史·第十二卷"},
    "xibolai_majiabi@-164": {"strategic":["公元前一六四年，连遭败绩的塞琉古帝国摄政吕西亚斯恼羞成怒，亲统主力大军南下征讨犹太。吕西亚斯吸取前番西侧险隘受伏的教训，改绕亲塞琉古的南方谷道迂回北进，兵抵耶路撒冷南门要塞伯特夙；犹大马加比毫不退避，统历战义军南出迎击。"],"tactical":["伯特夙高踞犹大南境山脊，锁钥通往圣城的南来大道。吕西亚斯自恃兵精械足，列开方阵与骑队压向山隘；犹大马加比阵前慷慨誓众，率熟谙山地搏杀的犹太义军迎面猛冲塞琉古前锋。义军攻势悍猛，当场重创敌军前队；吕西亚斯见义军抱必死之心难以力屈，被迫收兵北返安条克，犹大马加比遂光复耶路撒冷洁净圣殿。"],"history":"公元前一六四年秋，因以马忤斯惨败，塞琉古帝国摄政吕西亚斯亲自统率大军南征，吸取前番西北山隘受伏教训，绕道南方亲塞琉古的以土买地区北上，进抵耶路撒冷以南重镇伯特夙。犹大马加比率历战成军的犹太义军迎头痛击，重创吕西亚斯前锋；吕西亚斯见义军悍不畏死撤返安条克，犹大马加比遂顺势收复耶路撒冷洁净圣殿，创立光明节。","sources":"马加比一书·第四章；约瑟夫斯·犹太古史·第十二卷"},
    "xibolai_majiabi@-165": {"strategic":["公元前一六五年，塞琉古宫廷为扑灭犹太起义，遣宿将高尔吉亚统重兵进驻山麓要冲以马忤斯；随营甚至跟满携镣铐准备贩俘的商贩。高尔吉亚探知义军驻地，乘夜挑精兵潜入山地搜袭；犹大马加比察知敌谋，决意避实击虚反袭敌巢。"],"tactical":["以马忤斯控扼山麓出口与平原大道，塞琉古大营留守部队自恃无虞酣睡松懈。犹大马加比在山中旧营燃起遍地篝火迷惑高尔吉亚，亲统精干义军借夜色绕小道疾趋下山；拂晓号角齐鸣，义军猛扑以马忤斯主营，一举冲垮守敌并纵火焚营。待高尔吉亚在山中扑空回救，望见主营浓烟冲天，不战惊溃逃奔沿海。"],"history":"公元前一六五年秋，塞琉古国王安条克四世东征波斯前命吕西亚斯平定犹太，吕西亚斯遣名将尼卡诺尔与高尔吉亚率重兵屯驻平原边缘的以马忤斯，大批奴隶商携金银镣铐随军准备贩卖犹太战俘。高尔吉亚乘夜率精兵入山搜袭米斯巴义军营地；犹大马加比探知敌情，留篝火诱敌扑空，亲率义军夜间急行下山，拂晓突袭以马忤斯塞琉古主营大获全胜，吓退回援的高尔吉亚。","sources":"马加比一书·第三至四章；约瑟夫斯·犹太古史·第十二卷"},
    "xichu_xiangyu": {"strategic":["公元前二〇五年春，西楚霸王项羽统主力北上齐地平叛，后方楚都彭城守备空虚。汉王刘邦乘隙东出，收降关东诸王组成浩荡联军一举占领彭城，收罗财宝日夜置酒高会；项羽闻变震怒，留步卒继续攻齐，亲选精锐铁骑昼夜兼程南返奇袭彭城。"],"tactical":["彭城外有谷泗与睢水环绕，原野平衍利铁骑奔突。项羽率楚国精骑南下绕至城西萧县，拂晓自西向东如雷霆般猛扑毫无戒备的汉联军大营。诸侯联军各怀异心，自晨至午便被楚骑彻底冲垮，溃兵争相逃入谷泗与睢水，河道为尸骸堵塞不流；刘邦仅携随骑借风沙突围，项羽一战尽复西楚声威。"],"history":"公元前二〇五年春，西楚霸王项羽深陷齐地平叛，汉王刘邦乘虚合五诸侯大军攻占楚都彭城，日夜置酒高会。项羽闻变留诸将继续攻齐，亲选精锐铁骑星夜南驰，经萧县于拂晓自西向东反扑彭城，半日击溃汉联军主力，败兵挤入谷泗睢水溺亡无数，刘邦仅携随骑突围。","sources":"史记·项羽本纪；史记·高祖本纪"},
    "xichu_xiangyu@-202": {"strategic":["公元前二〇二年冬，西楚霸王项羽与汉议和引师东归，中途突遭汉军毁约紧追，各路诸侯重兵自齐梁淮南四面合拢。粮尽援绝的楚军被迫退屯垓下筑垒自保；面对汉大将军韩信居中统辖的倾国合围大阵，项羽披甲跨骓，决意率江东子弟杀出重围。"],"tactical":["垓下平畴旷野之上，韩信布下前中后与两翼层叠大阵严阵以待。项羽亲率楚军精骑怒吼冲阵，一举撞退韩信前军；怎奈韩信两翼斜向合拢、中军返身反扑，楚军力战受挫被迫退回壁垒。入夜寒营四面皆闻楚歌，项羽痛饮悲歌泣别虞姬，乘夜率亲骑突围南走，虽于东城快战连斩汉将，终耻渡乌江挥剑自刎。"],"history":"公元前二〇二年冬，西楚霸王项羽在鸿沟议和东归途中遭刘邦毁约追击，韩信、彭越、英布各路大军会师合围项羽于垓下。白昼会战项羽冲阵受韩信十面进退包抄重创退守壁垒；夜间闻汉营四面楚歌，霸王别姬泣饮，率壮骑突围南走，于东城快战斩汉将溃围，行至乌江亭长备舟劝渡，项羽耻以败身见江东父老，赠马挥剑自刎。","sources":"史记·项羽本纪"},
    "xichu_xiangyu@-207": {"strategic":["公元前二〇七年冬，秦名将之孙王离统边塞劲旅猛围赵都巨鹿，南有章邯筑甬道输粮，各路救赵诸侯畏秦强盛皆高筑营壁作壁上观。楚次将项羽愤斩畏缩逗留的上将军宋义，受推掌印统师；他先遣偏将截断秦军粮道，亲率楚军主力进抵巨鹿漳水。"],"tactical":["漳水冰寒湍急，巨鹿城下秦军连营如铁桶合围。项羽督全军渡过漳水，下令沉毁渡船、砸碎釜甑、焚烧庐舍，只携三日口粮，向全军昭示有进无退的必死决心。楚军将士以一当十呼声震天，围城接战九合皆捷，彻底冲碎秦军重围并生擒主帅王离；诸侯将领入辕门莫不膝行仰视，项羽自此确立天下霸主之位。"],"history":"公元前二〇七年冬，秦大将王离围赵王歇于巨鹿，章邯筑甬道供粮，诸侯救兵十余壁莫敢纵兵。楚次将项羽晨入帐斩逗留四十六日的上将军宋义，被推为假上将军；先遣英布断秦甬道，随即亲率全军渡过漳水，沉船、破釜甑、烧庐舍，持三日粮示士卒必死无一还心，九战大破秦军，斩苏角、俘王离、涉间自焚，威震天下诸侯。","sources":"史记·项羽本纪；资治通鉴·秦纪三"},
    "xin_baiqi": {"strategic":["公元前二六〇年，秦赵长平相持日久，赵国粮草先匮。秦廷巧施反间流言，赵王不听苦谏，临阵撤换坚守的老将，改拜轻躁谈兵的赵括为主帅；秦王闻讯大喜，密诏武安君白起星夜赴长平接掌上将军虎符，严令军中敢泄露白起挂帅者立斩，决胜之机已至。"],"tactical":["长平谷深壁立，丹水纵贯其间。赵括到任尽废守策，倾军渡水猛攻；白起命前锋佯败后撤，将赵括主力深深诱至秦军坚壁之下，同时暗遣奇兵绕后抢占故关长垒，配轻骑绝断赵军粮道与归路。赵军被困绝谷四十余日，断粮自相残食，赵括亲率精锐突围中箭身亡，余众尽降遭白起坑杀，东方六国自此再无独抗强秦之力。"],"history":"公元前二六〇年，秦赵长平久持不下，秦相范雎行反间计诱赵孝成王以赵括取代廉颇；秦昭襄王密拜武安君白起为上将军赴前线统军。白起佯败诱赵括倾军追至秦壁，随即出奇兵绝其后路与粮道，合围困饿赵军四十余日，射杀突围的赵括并坑杀降卒，重创赵国国本。","sources":"史记·白起王翦列传；史记·赵世家；战国策"},
    "xin_baiqi@-278": {"strategic":["公元前二七八年，楚顷襄王朝政腐败、防务空虚，秦国决意给予宿敌致命一击。秦大良造白起弃淮北常规战线，率精兵翻越武当孤军直插楚境，过河即毁桥焚舟自断退路；在引水灌破北门重镇鄢城、荡平外围屏障后，白起挥师南指楚顷襄王坐镇的郢都。"],"tactical":["郢都南临大江、北倚沮漳，城郭宏阔，然楚军主力已折于鄢城，城内上下惶惧无措。白起统背水死战的秦国锐师神速抵近，分兵截断江汉水路与属邑外援，旋即架云梯冲车对郢都发起雷霆猛攻。丧失斗志的楚都防线迅速瓦解，楚顷襄王携宗室弃城东逃陈城；白起攻克郢都置为南郡，受封武安君，楚国自此元气大伤。"],"history":"公元前二七九年至前二七八年，秦大良造白起率精兵孤军深入楚汉水腹地，毁桥焚舟示死战，先引水灌破楚北门重镇鄢城，继于前二七八年春挥师直扑楚顷襄王坐镇的国都郢都，一举破郢并烧夷陵王墓，楚顷襄王东逃陈城，白起置南郡受封武安君。定值：敌将取楚顷襄王。","sources":"史记·白起王翦列传；史记·楚世家；水经注·沔水"},
    "xin_baiqi@-293": {"strategic":["公元前二九三年，秦国锐意东出函谷争夺河洛咽喉，韩魏联合周室共推魏将公孙喜统兵进驻洛邑南郊伊阙天险，欲凭优势兵力锁死秦师。秦相魏冉破格保举青年左更白起挂帅；白起率兵力居劣的秦国锐士东进伊阙山前，迎来统兵生涯成名首战。"],"tactical":["伊阙两山隔伊水夹峙如门阙，公孙喜所统魏军与韩军依山连营。白起察知韩魏同床异梦、彼此推诿观望，遂在韩营当面张旗设疑兵牵制，亲统精锐主力悄然绕出山后，骤向公孙喜的魏军侧背发起猛扑。魏军猝不及防且韩军坐视不救，全军覆没于伊水畔，公孙喜被生擒；韩军吓得弃营溃逃，秦国东进中原大门就此洞开。"],"history":"公元前二九三年，秦穰侯魏冉举荐左更白起东征韩魏，韩魏联东周以魏将公孙喜为主帅，据守洛邑南郊伊阙险隘抗秦，兵力倍于秦师。白起看穿韩魏互推保存实力的破绽，设疑兵牵制韩军，亲率主力绕伊阙山后奇袭猛扑魏军，全歼魏师并生擒公孙喜，韩军随溃。定值：敌将取公孙喜。","sources":"史记·白起王翦列传；战国策·西周策"},
    "xiongnu_maodun": {"strategic":["公元前二〇〇年，草原雄主冒顿统一大漠诸部，控弦强盛，趁汉朝初立收降边将，率匈奴铁骑越句注山南下直逼晋阳。汉高祖刘邦亲统大军顶风雪北征迎击，前哨连捷而渐生轻敌之心；冒顿暗藏主力步步后撤诱敌，将汉军引向塞北平城白登山。"],"tactical":["白登山孤峙平城东北高寒原野，朔风刺骨。冒顿藏起精壮肥马，仅驱老弱示弱佯败，诱求胜心切的刘邦脱离步兵主力，率前锋追登白登山；刹那间冒顿挥各色骏马精骑四面合拢，将白登山围得水泄不通。汉军断粮受困七日七夜，赖重赂阏氏方趁浓雾解开一角脱险，汉廷自此改行和亲休养之策。"],"history":"公元前二〇〇年冬，一统大漠的匈奴单于冒顿收降马邑韩王信，引精骑越句注山南攻晋阳。汉高祖刘邦亲统大军北击，冒顿藏匿壮马精兵，以老弱示弱节节佯退，将刘邦与前锋诱入平城白登山绝地，尽出各色骏马铁骑合围七日七夜，迫汉廷改行和亲之策。","sources":"史记·匈奴列传；史记·高祖本纪；史记·陈丞相世家"},
    "xiyuduhu_banchao": {"strategic":["公元八六年，西域长史班超孤悬绝域经营诸国，此前因疏勒王榆勒反覆背汉将其废黜。榆勒不甘失位，借强邻康居精骑卷土重来，盘踞疏勒西境坚城损中并与龟兹暗中勾连；久攻难下之际，榆勒遣使向班超诈降请和，暗藏袭执汉使的杀机。"],"tactical":["损中城池坚固，外有康居游骑奥援，班超麾下汉卒稀少难于强攻。接榆勒请降书信，班超看穿其欲乘会面劫人之计，将计就计欣然许诺，在帐外暗伏甲士严阵以待。会期当日榆勒带轻骑坦然赴宴，酒过数巡，班超骤然大喝挥手为号，伏兵齐出当场将榆勒缚斩；班超随挥兵掩击损中，无主叛众惊溃投降，西域南道复通。"],"history":"东汉章和年间公元八六年，被西域长史班超废黜的前疏勒王榆勒借康居精骑还据损中城，暗结龟兹，遣使向班超诈降，企图于宴席掩执班超。班超洞悉奸计，外示接纳而暗伏甲士，待榆勒轻骑赴宴行酒时叱伏擒斩之，继破其余众，平定疏勒。","sources":"后汉书·班超列传；资治通鉴·汉纪四十"},
    "xiyuduhu_banchao@73": {"strategic":["公元七三年，东汉假司马班超奉命率精干随从深入西域招抚诸国，首站抵达丝路南道门户鄯善国。鄯善王广起初待汉使礼敬有加，未几却态度骤变疏慢冷淡；班超敏锐断定必有北匈奴使团潜抵城外威逼，广正首鼠两端，遂拷问侍胡查明敌营所在。"],"tactical":["鄯善王城外沙原荒寂，入夜狂风怒号。面对人数远胜己方的匈奴使团营帐，班超召集随行吏士慷慨陈词不入虎穴焉得虎子，乘暗夜率众潜至匈奴营外；班超令部属顺风纵火击鼓呐喊，自执利刃率众把守营门见敌便斩。匈奴使团睡梦中惊醒以为汉家大军天降，尽数葬身火海刀下；次日班超提敌首示众，鄯善王广震怖纳质归汉。"],"history":"东汉永平十六年，假司马班超奉窦固命率三十六吏士出使西域，首抵鄯善国都扜泥城。鄯善王广初甚恭敬，数日后忽转冷淡；班超察知北匈奴使者亦抵城外，鄯善王广首鼠两端欲执汉使献匈奴。班超激励三十六壮士乘风夜袭匈奴使营，顺风纵火尽斩匈奴使团，震慑鄯善王广纳质归汉。","sources":"后汉书·班超列传"},
    "xiyuduhu_banchao@94": {"strategic":["公元九四年秋，西域南北道大部已归附东汉，唯北道强国焉耆自恃水泽险阻，当年曾攻杀汉都护，左侯元孟等权臣仍暗通匈奴怀抱二心。西域都护班超决意铲除这一北道顽疾，调发龟兹、鄯善诸国联军东征，挥师直逼焉耆王与左侯元孟据守的员渠城。"],"tactical":["员渠城四面大山环拱，外有大泽苇桥唯一通路，焉耆王与元孟预先斩断苇桥企图阻水自固。班超早有防备，分遣精兵绕他道涉浅渡水，出敌不意兵临员渠城下，并严令定期赴营受赏以辨顺逆。焉耆王与元孟见天险已失，硬着头皮赴汉营周旋；班超当场叱令甲士将元孟与焉耆王一并缚斩示众，西域诸国尽皆震服纳质。"],"history":"东汉永元六年秋，西域都护班超发龟兹、鄯善等八国联军讨伐当年攻杀都护陈睦且尚怀二心的焉耆、危须、尉犁三国。焉耆王广与左侯元孟凭水断绝苇桥拒战，班超改自他道涉水潜逼员渠城下，设赏罚大陈军威，诱执焉耆王广及左侯元孟等斩于陈睦故城，西域五十余国悉数纳质内属。","sources":"后汉书·班超列传"},
    "yan_leyi": {"strategic":["公元前二八四年，强齐吞宋后骄狂四侵，列国自危。燕昭王为雪昔日覆国之耻筑台招贤，拜名将乐毅为上将军；乐毅献合纵群攻之策，串联燕、秦、韩、赵、魏共讨强齐，并佩相印统联军东进，与齐将触子统率的齐国主力对峙于济水西岸。"],"tactical":["济水西岸平原辽阔，触子依水扎营本欲持久待变，骄躁的齐王却遣使以掘墓灭族威逼其即刻出战。触子心寒齿冷，驱军心离散之师出营列阵。乐毅看准齐阵虚浮，擂鼓挥燕军居中死战、盟军两翼合击；初交锋触子便弃军远遁，齐国累世积蓄的野战主力一朝覆没。乐毅随即遣返盟军，独率燕师渡济水攻克临淄，横扫齐境雪耻。"],"history":"公元前二八四年，齐湣王灭宋后骄横四邻结怨，燕昭王拜乐毅为上将军，合纵燕秦韩赵魏五国伐齐。齐将触子西渡济水拒敌，齐湣王以掘墓灭族逼其速战；乐毅统联军于济水西岸迎头痛击，触子离心弃战逃逸，齐军主力覆没，乐毅继而独率燕师攻克临淄，连下齐境诸城。","sources":"史记·乐毅列传；战国策·燕策；吕氏春秋·权勋"},
    "yangshao_zhoubo": {"strategic":["公元前二〇五年，汉军平定关中大部后东出函谷关经略中原；雍王之弟章平仍统秦雍旧部盘踞崤函孔道渑池，时刻威胁关中粮运后路。汉廷命骁勇善战的大将周勃统精兵回师清剿，直扑章平据守的渑池险隘。"],"tactical":["渑池夹于崤山崇岭之间，谷道逼仄，乃连通关中与河洛的咽喉锁钥，章平收拢雍地悍卒凭城依险死守。周勃素以重厚敢战著称，抵阵后绝不迁延，亲自登先督率汉军步骑分道夹击，顶着城隘矢石昼夜急攻不歇。章平守军支撑不住防线崩裂，周勃乘胜掩杀夺下渑池并追擒章平，彻底打通函谷东向通道，稳固了汉军关中根基。"],"history":"公元前二〇五年，汉王刘邦还定三秦后留军围章邯于废丘，率主力东出函谷伐楚。章邯之弟章平率残部扼守崤函东道咽喉渑池一带威胁汉军后路粮道。汉猛将周勃奉命回师攻讨，在渑池正面击破章平守军，扫清关中通往中原的后方隐患。","sources":"史记·绛侯周勃世家；汉书·周勃传"},
    "yangzhou_wangping": {"strategic":["公元二四四年春，专擅曹魏朝政的大将军曹爽急于博取灭国军功以压政敌，倾发关陇大军由秦岭骆谷大举南侵汉中。此时蜀汉北境驻兵单薄、主力远在成都，帐下诸将惊慌失措，皆请放弃关隘退缩后方坚城；镇北大将军王平断然否决退议，决意抢据骆谷出口天险兴势山御敌。"],"tactical":["兴势山群峰陡立、谷道悬绝，控扼骆谷南出汉中盆地的咽喉。王平火速派精干前部抢登兴势山脊筑寨，沿百里山岭遍插旌旗虚张声势，自统后军紧随接应。曹爽督魏军钻入险长骆谷，仰攻山寨寸步难进，后方栈道牛马困死、军粮断绝；待蜀汉援兵赶到封锁退路，曹爽惶恐拔营仓皇北逃，汉中遂安然无恙。"],"history":"公元二四四年春，曹魏辅政大将军曹爽急欲立威，调集关中重兵自骆谷南下大举伐蜀。时汉中守兵稀少，蜀汉诸将多主张弃关退保汉、乐二城待援；镇北大将军王平独排众议，坚守前出拒险之制，遣护军刘敏据兴势山遍张旗帜死守，把曹爽大军死死堵在深谷之中，待费祎援军至迫退魏师。","sources":"三国志·蜀书·黄李吕马王张传；资治通鉴·魏纪五"},
    "yangzhou_wangping@231": {"strategic":["公元二三一年夏，蜀汉大军再出祁山北伐，曹魏统帅率关陇重兵赶赴迎战。蜀汉主帅率主力北赴卤城迎击魏军本阵，特命沉勇善守的讨寇将军王平别统偏师留驻祁山南围，扼守大军侧翼要冲；魏军果分遣宿将张郃统劲旅猛扑南围，企图撕裂蜀军防线。"],"tactical":["祁山南围据山临水，与卤城主阵互为犄角，一旦有失则蜀军腹背受敌。名将张郃自恃兵力占优，督魏军精锐轮番仰攻营垒；王平临危镇定，依托山险寨栅严整调度无当飞军与强弩劲卒，节节化解敌军凶猛冲锋。任凭张郃百计强攻，南围始终岿然不动；待卤城正面魏军受挫后撤，张郃只得无功退兵，王平守险威名远扬。"],"history":"三国蜀汉建兴九年即魏太和五年五月，诸葛亮第四次出祁山北伐，自统主力赴上邽、卤城迎敌，特命讨寇将军无当监王平别领孤军留守祁山南围。曹魏大都督司马懿进攻诸葛亮本营，分遣名将车骑将军张郃统大军猛攻王平南围，王平以寡敌众从容坚守，张郃累攻竟不能克，保全卤城侧后大捷。","sources":"三国志·蜀书·黄李吕马王张传"},
    "yashu_saergong": {"strategic":["公元前七一四年，亚美尼亚高原的乌拉尔图与亚述争锋日久，国王鲁萨一世倚仗山险屡诱扎格罗斯诸侯叛亚述，令北疆岁无宁日。亚述王萨尔贡深知不破强敌难安两河，遂亲统大军翻越险隘深入高原腹地，兵指图什帕方向；鲁萨一世亦集结高原劲旅据守山谷迎截。"],"tactical":["乌拉尔图高山深谷交错，鲁萨一世陈兵险峰山谷之间，欲趁亚述军翻山疲敝以逸待劳。不料萨尔贡不等全军整队，亲率近卫骑队与战车悍然突击，一举凿穿敌军中坚，鲁萨一世弃营逃遁。萨尔贡乘胜扫荡高原迫近图什帕一带，回师又奇袭攻陷圣城穆萨西尔；鲁萨一世闻讯自尽，乌拉尔图自此一蹶不振。"],"history":"公元前七一四年，亚述王萨尔贡发动在位第八次远征，翻越扎格罗斯山脉讨伐北方劲敌乌拉尔图国王鲁萨一世。萨尔贡在瓦乌什山突袭大败鲁萨一世主力，扫荡乌拉尔图腹地逼近都城图什帕一带，回师奇袭攻陷圣城穆萨西尔，掳掠神庙珍宝，鲁萨一世闻讯自尽。","sources":"萨尔贡二世致阿舒尔神书信；亚述王家铭文"},
    "yashu_saergong@-710": {"strategic":["公元前七一〇年，亚述王萨尔贡已荡平叙利亚与乌拉尔图，唯南方巴比伦尼亚仍由迦勒底首领米罗达巴拉旦倚仗埃兰外援割据称王。萨尔贡决意收复两河下游，避开巴比伦北关坚防，率主力沿底格里斯河东岸南插，先行切断埃兰援道，自东南反包抄直逼巴比伦。"],"tactical":["巴比伦城垣宏伟、河渠纵横，米罗达巴拉旦见埃兰东援被断顿陷孤立，城中祭司贵族亦苦其苛敛而离心。萨尔贡步步紧逼，分兵肃清城外迦勒底营垒，对都城形成合围。米罗达巴拉旦自知孤城难守，趁夜弃城南逃海泽；城中祭司大开城门迎萨尔贡入城加冕，南北两河重归亚述一统。"],"history":"公元前七一〇年，已平定西方与北方的亚述王萨尔贡举兵南征割据巴比伦十余年的迦勒底王米罗达巴拉旦。萨尔贡沿底格里斯河东岸南下切断埃兰援道，合围巴比伦城，米罗达巴拉旦趁夜弃城逃往海泽，萨尔贡受祭司市民迎奉入城兼领巴比伦王号。定值：敌将取迦勒底巴比伦王米罗达巴拉旦。","sources":"萨尔贡二世年代记；巴比伦编年史"},
    "yashu_saergong@-720": {"strategic":["公元前七二〇年，萨尔贡初登亚述王位，两河与东境动荡未平。叙利亚哈马特首领伊卢比迪趁机称王，串联大马士革、撒马利亚诸城拒贡叛乱，并暗通埃及求援。一旦叙利亚走廊失控，亚述西向商赋尽绝；萨尔贡稳住东线后即刻统常备军西进，直扑伊卢比迪屯兵的卡尔卡尔。"],"tactical":["卡尔卡尔扼守奥龙特斯河渡口与南北官道，伊卢比迪纠合诸城步骑战车依河岸列阵。萨尔贡看准叛军各怀异心，抵阵即以重装战车与长矛步阵正面强压中路，同时遣精锐骑队自侧翼迂回包抄河岸退路。拼凑的联军防线顷刻崩溃，萨尔贡乘胜攻克卡尔卡尔、生擒处死伊卢比迪，黎凡特复归震慑。"],"history":"公元前七二〇年，亚述王萨尔贡初立、东方埃兰发难之际，哈马特王伊卢比迪串联阿帕德、西米拉、大马士革及撒马利亚残余结成叙利亚反亚述同盟，陈兵奥龙特斯河畔卡尔卡尔。萨尔贡疾驰西征，野战击溃联军，攻克卡尔卡尔并擒杀伊卢比迪，稳固了亚述对黎凡特的统治。定值：敌将取盟主伊卢比迪。","sources":"萨尔贡二世王家年表铭文；杜尔舍鲁金碑铭"},
    "yidou_luxun": {"strategic":["公元二二二年，蜀汉皇帝刘备倾举国精锐东下三峡讨吴复仇，水陆连营自巫峡绵延山谷直逼长江门户夷陵，东吴朝野震骇。吴王力排众议，破格拜书生出身的陆逊为大都督总统诸宿将御敌；陆逊看准蜀军初来气盛而战线狭长，严令诸营后撤让出山峡，坚壁蓄锐静待刘备破绽。"],"tactical":["夷陵至猇亭峰峦重重、林木蔽日，蜀军远离后方补给维艰。麾下老将屡请速战，陆逊皆按剑弹压，硬顶刘备百般诱战自春耗至盛夏。酷暑中蜀军水土不服，刘备被迫舍舟将连营移入深林溪涧纳凉；陆逊先试攻摸清虚实，随即命士卒各持茅草顺风纵火，烈焰席卷漫山连营，吴军四面掩杀大破刘备，东吴国祚由此转安。"],"history":"公元二二二年，蜀汉昭烈帝刘备为复荆州亲统大军东出巫峡伐吴，前锋逼近夷陵、猇亭。吴王孙权破格拜镇西将军陆逊为大都督假节拒蜀。陆逊不顾老将求战非议，主动让出山地险峡诱使蜀军战线拉长，坚壁相持半年挫尽敌锐；盛夏蜀军移营密林避暑，陆逊顺风火攻连破蜀营，大败刘备。","sources":"三国志·吴书·陆逊传；资治通鉴·魏纪一"},
    "yidou_luxun@228": {"strategic":["公元二二八年秋，东吴设计令前线太守向曹魏密书诈降，伪称愿作内应迎魏师破吴。曹魏大司马曹休求功心切，不顾同僚识诈劝阻，亲统江淮步骑大军孤军深入皖城接应；吴王拜名将陆逊为大都督假黄钺总统三军，赶赴皖北石亭张开口袋迎击曹休。"],"tactical":["石亭地处大别山南麓丘陵隘口，北退夹石山道狭窄难行。曹休深入之后方觉受骗，却自恃兵精甲利羞于后撤，执意列阵硬拼；陆逊亲自坐镇中军正面稳压，分命左右两翼悍将三道并进猛扑魏阵。魏军阵脚被冲垮后争相北逃，陆逊督军衔尾急追直逼夹石，曹休抛弃车乘器械狼狈脱险，曹魏南线二十年不敢再轻窥江东。"],"history":"三国吴黄武七年即魏太和二年秋八月，吴王孙权使鄱阳太守周鲂密书向曹魏大司马曹休诈降。曹休中计亲率步骑深入皖城接应，孙权至皖口拜陆逊为大都督假黄钺迎击。曹休觉诈犹自恃兵众不退，陆逊自居中军，令朱桓、全琮为左右翼于石亭三道并进，大破魏军追至夹石，夺尽车乘军资。","sources":"三国志·吴书·陆逊传"},
    "yingzhou_ying_d_muronghuang": {"strategic":["公元三三八年夏，中原霸主后赵天王石虎挟灭段部之余威，怒责前燕爽约，倾国东侵直扑前燕都城棘城。大敌压境之际，前燕境内郡县纷纷叛投后赵，棘城顿成风中孤岛，慕容皝一度动摇欲出奔避锋；帐下忠良力陈弃城必亡、固守必胜，慕容皝遂幡然振作登城督守。"],"tactical":["棘城城垣虽小却壁垒坚厚，城内将士深知退无死所，人人殊死搏战。面对石虎四面云梯强攻，慕容皝亲临箭雨激励守军，更派勇士开门逆击，硬顶十余日令后赵骄兵锐气丧尽。见石虎粮乏拔营后撤、队列散漫，慕容皝果断命幼子率鲜卑精骑清晨开门猛扑敌背；后赵军大溃弃甲蔽野，慕容皝尽复叛城威震塞北。"],"history":"公元三三八年夏，后赵天王石虎借口前燕王慕容皝合讨段部鲜卑时爽约先归，倾发大军东征前燕，燕境三十余城望风叛附，石虎重兵合围前燕国都棘城。慕容皝一度欲弃城出奔，纳帐下谋臣苦谏定计死守；坚守十余日待石虎力竭退兵，遣幼子率铁骑晨出突击大破石虎。定值：战场改定为棘城。","sources":"晋书·慕容皝载记；资治通鉴·晋纪十八"},
    "yingzhou_ying_d_muronghuang@342": {"strategic":["公元三四二年冬，刚迁都龙城的前燕王慕容皝决意先除东顾之患再图漠南，采纳奇谋亲统大军东征高句丽。通往高句丽国都丸都有南北两途，北道平阔而南道险狭；高句丽王高钊料燕军必走大道，遂将重兵尽屯北路，仅留弱旅看守南路，慕容皝趁机暗度南道。"],"tactical":["丸都背倚崇山、前临鸭绿江谷，南道木底峡谷窄险崎岖。慕容皝仅遣偏师走北道张旗诱敌，亲率精锐铁骑秘密穿越南道狭谷出奇突袭；高钊闻南路告警仓促回师木底迎战，被慕容皝前锋迎头冲垮主力。燕军乘胜长驱杀入丸都，高钊单骑出奔深山；慕容皝毁丸都城垣收其府库珍宝凯旋，高钊被迫遣使奉表向燕称臣纳贡。"],"history":"东晋咸康八年冬十一月，刚迁都龙城的前燕王慕容皝采兄长慕容翰先取高句丽再灭宇文部之策，亲统精锐东征高句丽。高句丽故国原王高钊重兵布防平阔北道，仅以弱兵守险狭南道；慕容皝命王寓走北道诱敌，自偕慕容翰、慕容霸由南道奇袭木底大破高钊主力，乘胜攻入国都丸都并毁城而还，迫高钊称臣。","sources":"晋书·慕容皝载记"},
    "yingzhou_ying_d_muronghuang@344": {"strategic":["公元三四四年春，解除东线高句丽威胁的前燕王慕容皝决意彻底铲除世代仇敌宇文鲜卑，亲统步骑大军分三道北伐。宇文部大人宇文逸豆归雄踞辽西草原，闻燕师压境先遣骁将前出试探失利，随即倾发部族全部精锐铁骑南下迎战慕容皝主力。"],"tactical":["辽西草原丘陵起伏、河川开阔，极利鲜卑具装铁骑正面冲杀。宇文逸豆归委头号悍将统阵猛扑前燕先锋，前锋苦战之际，慕容皝亲督中军铁骑自侧后疾驰合击；燕骑前后夹攻阵斩敌军主将，宇文鲜卑大阵瞬间瓦解。慕容皝乘胜攻克敌都，宇文逸豆归远遁漠北客死异乡，前燕尽并其众，跃居东北霸主。"],"history":"东晋建元二年春正月，前燕王慕容皝解除东面高句丽威胁后，亲统大军北伐宿敌宇文鲜卑大人宇文逸豆归，以慕容翰为前锋、刘佩副之，分命慕容恪、慕容霸等三道并进。宇文逸豆归遣骁相莫浅浑来拒轻敌先败，复尽发精兵委大将涉夜干迎战，慕容翰与慕容皝主力合击斩涉夜干，宇文逸豆归远遁漠北，宇文部灭亡。","sources":"晋书·慕容皝载记"},
    "yipilusi_piluoshi": {"strategic":["公元前二八〇年，新兴的罗马共和国南逼大希腊诸邦，重镇塔兰托渡海延请伊庇鲁斯国王皮洛士助战。皮洛士怀西进雄心，率长矛方阵与披甲战象跨海登陆；罗马执政官拉维利乌斯拒纳调停，统军南下卢卡尼亚欲先发制人，皮洛士遂出驻赫拉克利亚河岸迎敌。"],"tactical":["赫拉克利亚原野被西里斯河横分，拉维利乌斯命罗马步阵涉浅强渡，另遣骑兵自上游包抄。皮洛士亲率骑队迎战掩护方阵成列，坐骑被刺仍摘盔驰呼稳住军心，长矛方阵与罗马军团反复冲杀难解难分。决胜关头皮洛士放出巨型战象猛冲敌翼，罗马战马初见巨兽惊狂反冲本阵；拉维利乌斯败退弃营，皮洛士首战告捷。"],"history":"公元前二八〇年七月，伊庇鲁斯王皮洛士应南意大利希腊城邦塔兰托求援，携马其顿方阵与战象渡海西征，与罗马执政官拉维利乌斯首战于卢卡尼亚赫拉克利亚城外西里斯河畔。两军反复拉锯难分高下，皮洛士最后投入罗马人未曾见过的战象冲垮敌翼获胜，但精锐亦损。定值：战场定为赫拉克利亚。","sources":"普鲁塔克·皮洛士传；哈利卡纳苏斯的狄奥尼修斯·罗马古事记"},
    "yipilusi_piluoshi@-275": {"strategic":["公元前二七五年，自西西里折返的伊庇鲁斯王皮洛士元气大损，盟友萨莫奈亦濒临覆亡。罗马执政官登塔图斯与同僚分路南下，先行进驻贝内文图姆高地扎营待援；皮洛士深知敌军合流更难取胜，遂亲率精锐与战象赶赴贝内文图姆，欲抢先击破登塔图斯。"],"tactical":["贝内文图姆群山环绕，登塔图斯据险坡筑营拒战。皮洛士遣精兵战象夜入山林绕袭敌后，不料火尽迷途，天亮暴露遭登塔图斯击退。登塔图斯乘势下山决战，摸透象性的罗马兵自壕垒齐射燃烧标枪；受伤哀嚎的幼象掉头寻母，引母象惊狂反冲踏碎皮洛士本阵，皮洛士无力再战黯然东归，南意大利尽入罗马版图。"],"history":"公元前二七五年，自西西里折返的皮洛士兵疲财匮，趁罗马双执政官分兵南下，率主力扑向驻贝内文图姆高地的执政官登塔图斯。皮洛士遣精兵战象夜翻山林欲袭敌后，因迷路至天明暴露遭反击；平原决战中罗马军以火箭射伤幼象致母象狂乱反冲本阵，皮洛士败归希腊。定值：敌将取登塔图斯。","sources":"普鲁塔克·皮洛士传；狄奥·卡西乌斯·罗马史残篇"},
    "yipilusi_piluoshi@-279": {"strategic":["公元前二七九年，罗马共和国首战受挫却拒不议和；执政官德西乌斯统重兵南下阿普利亚拦截，更特制涂油火把与铁叉牛车专克战象。伊庇鲁斯王皮洛士率本部精锐与意大利盟军北上，与德西乌斯隔阿斯库路姆河谷再度对垒。"],"tactical":["阿斯库路姆首日战场林密岸陡，战象难施，两军苦斗未分高下。次日皮洛士抢先占领林坡，逼德西乌斯在平阔原野决战。面对罗马推出的烈火防象牛车，皮洛士遣投石标枪轻兵射杀车夫将其废除，随挥战象与王家骑队压垮罗马侧翼迫敌退回坚营；望着满地阵亡亲信，皮洛士长叹再赢一场便只身归国了。"],"history":"公元前二七九年夏，伊庇鲁斯王皮洛士北进阿普利亚，与罗马执政官德西乌斯等大军苦战于阿斯库路姆。首日林岸陡峭难施方阵战象；次日皮洛士抢占平阔地，以轻兵标枪废掉罗马特制防象火牛车，投入战象突破罗马军团惨胜，留下再来一胜便完蛋的皮洛士式胜利典故。定值：敌将取德西乌斯。","sources":"普鲁塔克·皮洛士传；哈利卡纳苏斯的狄奥尼修斯·罗马古事记"},
    "you_gengyan": {"strategic":["公元二九年，东汉光武帝渐次扫平关东群雄，命建威大将军耿弇统兵东讨割据齐地诸郡的强藩张步。耿弇济河连拔外围重镇，进抵西安与临淄之间；见西安城小而坚、临淄大而疏防，耿弇遂声东击西，扬言刻期攻西安，半夜却卷甲疾扑重镇临淄，引张步主力来决。"],"tactical":["临淄城郭宏阔，城东淄水与原野相连。耿弇出敌不意半夜袭拔临淄，张步惊闻要害失守，果自剧县倾发齐地主力反扑城东。激战中耿弇大腿被飞矢射中，他恐动摇军心，面不改色挥佩刀斩断箭杆继续督战；待营中精锐突骑整装齐出，耿弇亲率铁骑自侧翼横贯冲阵，一举击溃张步大军，东齐诸郡自此尽归汉廷版图。"],"history":"公元二九年冬，东汉建威大将军耿弇奉诏东征齐地割据枭雄张步。耿弇渡济水连破祝阿、巨里，进逼齐都剧县与临淄之间，用声东击西计扬言攻西安而半夜疾趋拔取临淄；张步自剧县倾师来救，于临淄城东决战，耿弇胯中飞矢挥剑断箭浴血苦战，终大破张步平定齐地。","sources":"后汉书·耿弇列传；资治通鉴·汉纪三十三"},
    "you_gengyan@29": {"strategic":["公元二九年冬，东汉建威大将军耿弇奉诏东讨齐地割据强藩，率精兵架浮桥强渡济水。齐主将济南王费邑坐镇历下，分遣精兵扼守渡口前哨祝阿与钟城，企图依托坚垒层层阻滞汉师；耿弇定下拔点打援之策，挥师疾扑祝阿，引诱历下费邑出巢来救。"],"tactical":["祝阿至巨里丘陵连绵，东接历下大道。耿弇渡河半日便以围三阙一巧计攻拔祝阿，吓跑钟城守敌，旋即进围巨里并大肆伐木扬言填壕，故意放走俘虏回历下报信。费邑果真忧虑巨里失守，亲率精兵自历下昼夜驰援；耿弇早留偏师监视城池，亲统精锐隐伏山冈，待费邑疲师抵坡下居高猛冲，临阵斩杀费邑，席卷济南全境。"],"history":"东汉建武五年冬十月，建威大将军耿弇统兵东讨齐王张步，自朝阳架桥渡济水。张步遣大将军济南王费邑屯历下，分兵守祝阿及泰山钟城。耿弇渡河半日即用围三阙一之法攻拔祝阿，继进围巨里城，诱使费邑自历下率精兵来救，耿弇登高俯冲大破齐军并临阵斩杀费邑，夺取济南全郡。","sources":"后汉书·耿弇列传"},
    "yue_goujian": {"strategic":["公元前四七三年，吴越世代宿怨迎来终局。越王勾践自会稽赦归后身自耕作、暗蓄兵威，趁吴王夫差北争中原屡耗其国，经笠泽大捷彻底打垮吴军主力。此时吴国羽翼尽折、外无诸侯来援，勾践决意灭吴雪耻，倾发水陆大军将夫差困守的姑苏团团包围。"],"tactical":["姑苏河渎纵横、城郭宏阔，夫差收拢残卒凭水陆重关死守。勾践知困兽犹斗不可急攻，在城外修筑坚垒，截断太湖与江淮通城水道，以长围消磨敌军元气。久困之下吴军突围皆被击回，城内粮尽援绝，勾践遂挥师总攻破城；夫差退上姑苏山乞求存祀，勾践纳范蠡之谏不许留国，夫差自刎，越国称霸东南。"],"history":"越王勾践夫椒兵败归国后十年生聚十年教训，先后趁夫差黄池争霸袭破吴都、于笠泽歼灭吴军主力，继而自公元前四七五年起围困吴都姑苏。经三年长围，公元前四七三年冬勾践攻克姑苏，拒夫差留国乞和，夫差自刎，吴国灭亡。","sources":"左传·哀公二十二年；国语·越语；史记·越王勾践世家"},
    "yue_goujian@-478": {"strategic":["公元前四七八年，越王勾践卧薪尝胆十余载后国富兵强，吴王夫差则因连年北征齐晋耗空精壮，国内又逢大旱饥荒。勾践见破吴时机已熟，尽起越国水陆劲旅北上讨吴；夫差闻警搜括余兵倾城南出，进驻笠泽北岸，欲凭江水天险阻挡越师。"],"tactical":["笠泽江面宽阔湍急，夫差沿北岸连营设防，与南岸越军隔水相峙。勾践避开白昼强渡，入夜分遣两翼偏师于上下游鸣鼓呐喊渡江，佯作包抄。夫差黑夜惊闻两侧鼓震，急分中军驰援两翼；勾践算定吴营中枢已虚，亲率精锐私卒衔枚潜渡中流，登岸突袭吴王本阵。吴中军溃散，两翼随之崩盘，吴国脊梁一战折断。"],"history":"公元前四七八年三月，越王勾践乘吴国连年北征耗竭及大旱饥荒之机大举伐吴，吴王夫差尽发国内余兵南下，隔笠泽设防。勾践入夜命左右两翼鸣鼓喧嚣诱吴军分兵，自率精锐私卒衔枚潜渡中流突袭夫差中军，三战皆捷歼灭吴国野战主力，奠定灭吴大局。","sources":"左传·哀公十七年；国语·吴语；史记·越王勾践世家"},
    "yue_goujian@-496": {"strategic":["公元前四九六年，吴国破楚后兵威冠于东南，与屡扰后方的越国积怨日深。适逢越国老王病逝、勾践初立，吴王阖闾趁越居国丧，亲统久战劲旅南下伐越，欲一举兼并越地。勾践临危不惧，急调越国锐士北上迎敌，两军主力对峙于吴越边境的槜李。"],"tactical":["槜李水网交错、田畴平衍，阖闾所统吴军结成严整方阵，勾践数次派兵冲锋皆被挡回。见强攻难撼，勾践遣死罪士卒分列走到吴阵前齐呼挥剑自刎；吴军上下惊愕张望，阵线瞬间松动。勾践看准破绽擂鼓挥全军猛冲，击溃吴师并重创阖闾足趾；阖闾伤重卒于归途，吴越死仇自此彻结。"],"history":"公元前四九六年夏，越王允常卒，勾践初立，吴王阖闾乘越丧亲率精兵南下伐越，两军对阵于槜李。勾践见吴阵森严难撼，遣死罪士卒于阵前排剑自刭，趁吴军错愕观望之际全军突击大败吴师，阖闾伤足病卒于归途。定值：敌将取吴王阖闾。","sources":"左传·定公十四年；史记·越王勾践世家"},
    "yuzhou_zuti": {"strategic":["公元三二〇年，中流击楫誓复神州的东晋豫州刺史祖逖推进至中原腹心雍丘，后赵急遣名将桃豹统重兵南下争夺。双方在残破的雍丘大城之内形成奇特对峙：桃豹据守西台，祖逖前部据守东台；两军仅隔断垣昼夜鏖战四十余日，粮草双双逼近枯竭关头。"],"tactical":["雍丘地处汴水冲要，谁先露缺粮怯态便立遭吞没。祖逖急生妙计，命大批士卒用布囊装满泥土，大张旗鼓扛上东台佯作江南新粮运抵；后赵兵望见米袋堆积如山大为气沮，急向后方求粮。待后赵以驴马驼队护送大批军粮南援桃豹，祖逖早派两路奇兵半途夹击纵火尽夺其粮；西台绝粮的桃豹惊惧绝望，乘夜弃雍丘仓皇北逃。"],"history":"公元三二〇年，东晋豫州刺史祖逖北伐进据河南要冲雍丘，与后赵大将桃豹同处一城东西对垒四十余日。两军俱陷缺粮困境，祖逖用布袋装满泥土伪装运粮车入营迷惑敌军，又趁后赵运粮队驰援桃豹之际设奇伏半途截获真粮，吓得饥困交加的桃豹乘夜弃雍丘北逃。","sources":"晋书·祖逖列传；资治通鉴·晋纪十三"},
    "yuzhou_zuti@319": {"strategic":["公元三一九年，击楫中流矢志北伐的东晋豫州刺史祖逖正经略河南，叛将却杀害晋官割据谯县并向后赵求援。后赵急派悍将石虎统精锐步骑大举南下救援谯县，兵势浩大震动淮颍；祖逖审度敌我虚实，避开初来锐锋，寻机与石虎在浚仪至谯县原野周旋。"],"tactical":["谯县与浚仪之间涡水、睢水纵横，平原村坞密布。祖逖见石虎铁骑势猛，先主动收兵南保淮畔休整蓄锐，诱使石虎放心分兵四出抄掠；待后赵骑队散漫疲敝、队列脱节之际，祖逖果断挥精卒回师北上，在浚仪与谯北一带设伏分头邀击。石虎猝遭痛击损兵折将，只得掠走叛部仓皇北撤，祖逖收复谯县，黄河以南尽复晋土。"],"history":"东晋大兴二年，蓬陂坞主陈川杀死祖逖部将叛据谯城，劫掠豫州诸郡并附后赵石勒。祖逖挥师攻围陈川，石勒急遣侄儿中山公石虎统步骑南下救谯城。祖逖审势主动退屯淮南寿春近侧休整，待石虎分兵抄掠之际回师于浚仪及谯北设奇邀击，大破石虎，石虎仅掠陈川部众北徙襄国，谯城复归东晋。","sources":"晋书·祖逖列传"},
    "zhao_lianpo": {"strategic":["公元前二五一年，赵国历经长平与邯郸血战后青壮凋敝。燕相栗腹奉使赴赵祝寿归国，密劝燕王乘赵孤幼未壮举兵吞赵；燕王不听忠谏，命栗腹亲统主力南侵鄗城。赵王怒盟邦背信偷袭，复拜老帅廉颇统兵北上鄗城迎敌。"],"tactical":["鄗城位居邯郸以北平原要道，乃赵都北门重镇。栗腹率燕军进抵鄗城，认定赵无精兵可用，行军骄狂松懈。廉颇看准燕军将骄兵惰而赵卒同仇敌忾，舍弃持久战法，集中宿战精锐趁敌立足未稳骤发猛攻。赵军铁骑重步直捣中坚，燕阵顷刻崩溃，栗腹当场被斩；廉颇乘胜追围燕都蓟城，迫燕割城谢罪，重振赵威。"],"history":"公元前二五一年，燕王喜听信国相栗腹所言赵壮者尽死长平、孤幼未壮可伐，命栗腹攻鄗、卿秦攻代大举侵赵。赵王起用老将廉颇御敌，廉颇集中主力于鄗城迎头痛击轻敌深入的栗腹大军，阵斩栗腹，乘胜长驱围燕都蓟城，迫燕割城求和。定值：战场定为鄗城。","sources":"史记·廉颇蔺相如列传；史记·燕召公世家；战国策·燕策三"},
    "zhao_lianpo@-260": {"strategic":["公元前二六〇年，赵国受纳上党引发强秦倾力来攻，秦将王龁夺占上党诸邑后北压太行腹地长平。赵王委派宿将廉颇挂帅西御强敌；廉颇深知秦军远越崇山运粮维艰、唯求速战，只要赵军稳守消耗便能挫敌锐气，遂统主力赶赴长平布防。"],"tactical":["长平群峰连绵、丹水穿谷，廉颇初设西岸前哨遭王龁猛扑攻破，果断不再野战硬拼，收拢主力退守丹水东岸依山筑起绵延高垒。任凭王龁涉水逼营叫骂搦战，廉颇严令诸将闭营固守，仅凭险关强弩居高射退敌军，将秦师死死钉在深山。惜赵王难忍粮耗、误信反间临阵换将，廉颇含恨交印，赵军旋即覆败。"],"history":"公元前二六二年赵受上党，秦遣王龁攻上党进逼长平，赵王命宿将廉颇率军迎防。初战前哨失利后，廉颇审势退守丹水东岸修筑长垒坚壁不出，任王龁百般挑战始终稳守，拖住秦军主力累年；惜公元前二六〇年赵王中秦反间计以赵括代廉颇，终致长平覆军。","sources":"史记·廉颇蔺相如列传；史记·白起王翦列传"},
    "zhong_xiexuan@379": {"strategic":["公元三七九年春，一统北方的强敌前秦分兵南侵，征东将军彭超连陷彭城、盱眙，重兵围困三阿；兵锋逼近京师北门广陵，建康朝野震恐。镇守京口的建武将军谢玄临危受命，统领新练成的北府精兵渡江北驰，迎救三阿痛击彭超。"],"tactical":["淮南白马塘至淮阴君川水网密布、河湖纵横，限制北方骑兵驰骋。谢玄一面统主力正面疾进连破秦军外围阻截解三阿之围，一面妙派水师偏将乘舟夜袭留城焚烧彭超后方辎重船队；彭超唯恐后路断绝仓皇北撤，谢玄挥动悍不畏死的北府劲卒衔尾猛追，在君川隔水大战彻底击溃彭超主力，北府兵由此一战成名威震江淮。"],"history":"东晋太元三年至四年春，前秦攻陷襄阳与彭城，征东将军彭超与后将军俱难乘胜南下攻拔盱眙，进围幽州刺史田洛于三阿，距建康北屏广陵仅百里，朝野震骇。建武将军兖州刺史谢玄自京口统新建北府兵驰援，遣何谦偏师声袭留城秦军辎重诱彭超解围北顾，乘势连破秦军于白马塘、盱眙，终在淮阴君川彻底击溃彭超与俱难。","sources":"晋书·谢玄列传"},
    "zhou_jifa": {"strategic":["约公元前一〇四六年，殷商渐入暮年，商王子受暴虐无道、贵族离心，商军主力又久陷东南夷战事。西方渭水周族日益强盛，诸侯多叛商归周。周武王姬发见时机成熟，遍告诸侯兴兵伐商；周师会合西南诸方国部族自孟津冒雨东渡黄河，昼夜兼程直扑朝歌南郊牧野。"],"tactical":["朝歌南郊牧野平坦开阔，极利战车驰骋列阵。子受不及召回远征主力，仓促武装战俘与罪隶出城迎战。姬发阵前誓师申严军纪，命战车与虎贲猛士率先冲阵；商军前阵士卒素恨子受暴政，交锋未久便纷纷倒戈反冲本阵。商师大溃，子受退登鹿台自焚，姬发入主中原，开启周代礼乐格局。"],"history":"约公元前一〇四六年，周武王姬发乘商王子受连年征伐东夷、王畿空虚怨叛之机，率周军东渡孟津，会合庸、蜀、羌、髳、微、卢、彭、濮诸方国联军决战于朝歌南郊牧野。商军临时武装的战俘与罪隶临阵倒戈，周军击溃商师，子受登鹿台自焚，商亡周兴。异说：克商之年另有前一〇二七年、前一〇四五年诸说。","sources":"尚书·牧誓；史记·周本纪；利簋铭文"},
};
